import Image from 'next/image';
import { cn } from '../lib/utils';

export function Avatar({ 
  src, 
  fallback, 
  alt, 
  size = "default", 
  variant = "default",
  className, 
  ...props 
}) {
  const sizeClasses = {
    xs: "h-6 w-6 text-xs",
    sm: "h-8 w-8 text-sm",
    default: "h-10 w-10 text-base",
    lg: "h-12 w-12 text-lg",
    xl: "h-16 w-16 text-xl",
    "2xl": "h-20 w-20 text-2xl",
    "3xl": "h-24 w-24 text-3xl"
  };

  const variantClasses = {
    default: "bg-gradient-to-br from-primary-500 to-primary-700 text-white",
    secondary: "bg-gradient-to-br from-secondary-400 to-secondary-600 text-white",
    success: "bg-gradient-to-br from-success-500 to-success-700 text-white",
    warning: "bg-gradient-to-br from-warning-500 to-warning-700 text-white",
    error: "bg-gradient-to-br from-error-500 to-error-700 text-white",
    neutral: "bg-gradient-to-br from-gray-400 to-gray-600 text-white"
  };

  const getInitials = (name) => {
    if (!name) return "?";
    return name
      .split(" ")
      .map(word => word.charAt(0))
      .join("")
      .substring(0, 2)
      .toUpperCase();
  };

  const baseClasses = cn(
    "relative inline-flex items-center justify-center rounded-full font-semibold shrink-0 transition-all duration-200 hover:scale-105 shadow-lg ring-2 ring-white/20 overflow-hidden",
    sizeClasses[size],
    !src && variantClasses[variant],
    className
  );

  if (src) {
    return (
      <div className={baseClasses} {...props}>
        <Image
          src={src}
          alt={alt || "Avatar"}
          fill
          className="object-cover"
          sizes="(max-width: 48px) 48px, (max-width: 64px) 64px, 96px"
        />
      </div>
    );
  }

  return (
    <div className={baseClasses} {...props}>
      <span className="select-none">
        {getInitials(fallback)}
      </span>
    </div>
  );
}

