import { useState, useEffect, useRef } from 'react';
import { FiSearch, FiX, FiCheck, FiChevronDown, FiUser } from 'react-icons/fi';
import { Input } from './Input';
import { Button } from './Button';

export const EmployeeSelector = ({ 
  value, 
  onChange, 
  label, 
  placeholder = "Search and select employee...", 
  required = false,
  employees = []
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [filteredEmployees, setFilteredEmployees] = useState(employees);
  const [dropdownPosition, setDropdownPosition] = useState('bottom');
  const dropdownRef = useRef(null);
  const inputRef = useRef(null);
  const buttonRef = useRef(null);

  // Debug logging for development
  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      console.log('EmployeeSelector Debug:');
      console.log('- Employees prop type:', typeof employees);
      console.log('- Employees is array:', Array.isArray(employees));
      console.log('- Employees count:', employees?.length || 0);
      console.log('- Sample employee data:', employees?.[0]);
    }
  }, [employees]);

  useEffect(() => {
    // Ensure employees is always an array
    const employeeArray = Array.isArray(employees) ? employees : [];

    if (searchQuery) {
      const filtered = employeeArray.filter(emp => {
        // Handle different possible field names
        const name = emp.name || emp.full_name || '';
        const email = emp.email || '';
        const designation = emp.designation || emp.job_role || '';

        return name.toLowerCase().includes(searchQuery.toLowerCase()) ||
               email.toLowerCase().includes(searchQuery.toLowerCase()) ||
               designation.toLowerCase().includes(searchQuery.toLowerCase());
      });
      setFilteredEmployees(filtered);
    } else {
      setFilteredEmployees(employeeArray);
    }
  }, [searchQuery, employees]);

  // Calculate dropdown position when opening
  useEffect(() => {
    if (isOpen && buttonRef.current) {
      const buttonRect = buttonRef.current.getBoundingClientRect();
      const viewportHeight = window.innerHeight;
      const dropdownMaxHeight = 320; // max-h-80 = 20rem = 320px

      // Check if there's enough space below
      const spaceBelow = viewportHeight - buttonRect.bottom;
      const spaceAbove = buttonRect.top;

      if (spaceBelow < dropdownMaxHeight && spaceAbove > spaceBelow) {
        setDropdownPosition('top');
      } else {
        setDropdownPosition('bottom');
      }
    }
  }, [isOpen]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
        setSearchQuery('');
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen]);

  const handleSelect = (employee) => {
    onChange(employee);
    setIsOpen(false);
    setSearchQuery('');
  };

  const handleClear = (e) => {
    e.stopPropagation();
    onChange(null);
    setSearchQuery('');
  };

  const handleToggle = () => {
    setIsOpen(!isOpen);
    if (!isOpen && inputRef.current) {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  };

  const selectedEmployee = value;

  return (
    <div className="relative" ref={dropdownRef}>
      <label className="block text-sm font-medium text-gray-700 mb-2">
        {label}
        {required && <span className="text-red-500 ml-1">*</span>}
      </label>

      <div className="relative">
        {/* Main selector button */}
        <button
          ref={buttonRef}
          type="button"
          className={`relative w-full bg-white border border-gray-300 rounded-lg shadow-sm pl-3 pr-10 py-3 text-left cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all duration-200 ${
            isOpen ? 'border-blue-500 ring-2 ring-blue-500 ring-opacity-20' : 'hover:border-gray-400'
          }`}
          onClick={handleToggle}
        >
          {selectedEmployee ? (
            <div className="flex items-center">
              <div className="flex-shrink-0 w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center mr-3">
                <FiUser className="w-4 h-4 text-blue-600" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-gray-900 truncate">
                  {selectedEmployee.name || selectedEmployee.full_name || 'Unknown Name'}
                </div>
                <div className="text-sm text-gray-500 truncate">
                  {selectedEmployee.email || 'No email'}
                </div>
              </div>
              <button
                type="button"
                onClick={handleClear}
                className="flex-shrink-0 ml-2 p-1 text-gray-400 hover:text-gray-600 rounded-full hover:bg-gray-100 transition-colors"
              >
                <FiX className="w-4 h-4" />
              </button>
            </div>
          ) : (
            <div className="flex items-center">
              <div className="flex-shrink-0 w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center mr-3">
                <FiUser className="w-4 h-4 text-gray-400" />
              </div>
              <span className="text-gray-500 truncate">{placeholder}</span>
            </div>
          )}

          <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
            <FiChevronDown 
              className={`w-4 h-4 text-gray-400 transition-transform duration-200 ${
                isOpen ? 'transform rotate-180' : ''
              }`} 
            />
          </div>
        </button>

        {/* Dropdown panel */}
        {isOpen && (
          <div className={`absolute z-[9999] w-full bg-white border border-gray-200 rounded-lg shadow-lg max-h-80 overflow-hidden ${
            dropdownPosition === 'top' ? 'bottom-full mb-2' : 'top-full mt-2'
          }`}>
            {/* Search input */}
            <div className="p-3 border-b border-gray-100">
              <div className="relative">
                <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input
                  ref={inputRef}
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search employees..."
                  className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            </div>

            {/* Employee list */}
            <div className="max-h-60 overflow-y-auto">
              {filteredEmployees.length > 0 ? (
                <div className="py-1">
                  {filteredEmployees.map((employee) => (
                    <button
                      key={employee.id}
                      type="button"
                      className="w-full flex items-center px-4 py-3 hover:bg-gray-50 focus:bg-gray-50 focus:outline-none transition-colors text-left"
                      onClick={() => handleSelect(employee)}
                    >
                      <div className="flex-shrink-0 w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center mr-3">
                        <FiUser className="w-4 h-4 text-blue-600" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="font-medium text-gray-900 truncate">
                          {employee.name || employee.full_name || 'Unknown Name'}
                        </div>
                        <div className="text-sm text-gray-500 truncate">
                          {employee.email || 'No email'}
                        </div>
                        {(employee.designation || employee.job_role) && (
                          <div className="text-xs text-gray-400 truncate">
                            {employee.designation || employee.job_role}
                          </div>
                        )}
                      </div>
                      {selectedEmployee?.id === employee.id && (
                        <div className="flex-shrink-0 ml-2">
                          <FiCheck className="w-4 h-4 text-blue-600" />
                        </div>
                      )}
                    </button>
                  ))}
                </div>
              ) : (
                <div className="px-4 py-8 text-center">
                  <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
                    <FiUser className="w-6 h-6 text-gray-400" />
                  </div>
                  <div className="text-sm text-gray-500">
                    {!Array.isArray(employees) ? 
                      'Invalid employee data format' : 
                      employees.length === 0 ? 
                        'No employees available' : 
                        'No employees found matching your search'
                    }
                  </div>
                  {searchQuery && (
                    <button
                      type="button"
                      onClick={() => setSearchQuery('')}
                      className="mt-2 text-xs text-blue-600 hover:text-blue-700"
                    >
                      Clear search
                    </button>
                  )}
                </div>
              )}
            </div>

            {/* Footer with count */}
            {filteredEmployees.length > 0 && (
              <div className="px-4 py-2 bg-gray-50 border-t border-gray-100">
                <div className="text-xs text-gray-500">
                  {filteredEmployees.length} of {employees.length} employees
                  {searchQuery && ` matching "${searchQuery}"`}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

