import { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/router';
import { 
  FiMenu, FiX, FiHome, FiUsers, FiFolderPlus, 
  FiBriefcase, FiCalendar, FiBarChart2, FiFileText,
  FiUser, FiLogOut
} from 'react-icons/fi';
import { isAuthenticated, logout, getUser, isAdmin, isTeamLead, isProjectManager, isCoFounder } from '../lib/auth';

export default function Layout({ children }) {
  const router = useRouter();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [user, setUser] = useState(null);

  // Helper function to check if a path is active
  const isActivePath = (path) => {
    if (path === '/') {
      return router.pathname === path;
    }

    // Handle dynamic URLs with query parameters
    if (path.includes('?')) {
      const [basePath] = path.split('?');
      return router.pathname.startsWith(basePath) && router.asPath.includes(path);
    }

    return router.pathname.startsWith(path);
  };

  // Helper function to get active class
  const getActiveClass = (path) => {
    const baseClass = "flex items-center px-4 py-3 text-sm font-medium rounded-xl transition-all duration-200 group relative overflow-hidden";
    return isActivePath(path) 
      ? `${baseClass} bg-white/20 text-white shadow-lg backdrop-blur-sm border border-white/30` 
      : `${baseClass} hover:bg-white/10 text-white/90 hover:text-white hover:backdrop-blur-sm hover:border-white/20 border border-transparent`;
  };

  useEffect(() => {
    setUser(getUser());
  }, []);

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
  };

  // Permission checks
  const canViewEmployees = user && (isAdmin() || isCoFounder() || isTeamLead() || isProjectManager());
  const canViewDepartments = user && isAdmin(); // Only admin can view departments
  const canViewProjects = user && (isAdmin() || isCoFounder() || isTeamLead() || isProjectManager() || user.isEmployee);
  const canViewForms = user && (isAdmin() || isCoFounder() || isTeamLead() || isProjectManager() || user.isEmployee);
  const canViewAnalytics = false; // Hidden from all portals
  const canViewReports = false; // Hidden from all portals

  // Dynamic URLs based on user role
  const getProjectsUrl = () => {
    if (user && user.isEmployee) return '/projects?my=true';
    return '/projects';
  };

  const getFormsUrl = () => {
    if (user && user.isEmployee) return '/forms?my=true';
    return '/forms';
  };

  const getReportsUrl = () => {
    if (user && user.isEmployee) return '/reports?my=true';
    return '/reports';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-blue-50 flex flex-col">
      {/* Enhanced Header with Gradient */}
      <nav className="page-header relative overflow-hidden">
        {/* Background gradient overlay */}
        <div className="absolute inset-0 bg-gradient-to-r from-primary-600 via-primary-700 to-primary-800"></div>
        <div className="absolute inset-0 opacity-20">
          <div className="absolute inset-0" style={{
            backgroundImage: 'radial-gradient(circle at 1px 1px, rgba(255,255,255,0.15) 1px, transparent 0)',
            backgroundSize: '20px 20px'
          }}></div>
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-20">
            <div className="flex items-center flex-1">
              <div className="flex-shrink-0 flex items-center mr-8">
                <div className="flex items-center space-x-3 cursor-default group">
                  <div className="relative">
                    <div className="absolute inset-0 bg-white/20 rounded-2xl blur group-hover:blur-sm transition-all duration-300"></div>
                    <Image
                      src="/tericsoft_logo.jpeg"
                      alt="TericSoft Logo"
                      width={56}
                      height={56}
                      className="relative rounded-2xl border-2 border-white/30 shadow-lg"
                      priority
                    />
                  </div>
                  <div className="flex flex-col">
                    <span className="text-xl font-bold text-white tracking-tight">TericSoft</span>
                  </div>
                </div>
              </div>
            </div>

            {/* Desktop Navigation */}
            <div className="hidden md:flex md:items-center md:space-x-2">
              <Link href="/">
                <a className={getActiveClass('/')}>
                  <FiHome className="mr-3 h-4 w-4" />
                  <span>Dashboard</span>
                </a>
              </Link>

              {canViewEmployees && (
                <Link href="/employees">
                  <a className={getActiveClass('/employees')}>
                    <FiUsers className="mr-3 h-4 w-4" />
