import { useState, useEffect } from 'react';
import { FiClock, FiX, FiCalendar } from 'react-icons/fi';
import { Card } from './Card';
import { Button } from './Button';
import { Badge } from './Badge';

export const DueFormsNotification = ({ user }) => {
  const [dueForms, setDueForms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    const fetchDueForms = async () => {
      try {
        const response = await fetch('/api/forms/check-due');
        if (response.ok) {
          const dueSubmissions = await response.json();

          // Filter due forms relevant to current user
          const relevantDueForms = dueSubmissions.filter(submission => {
            // Show forms that are due for the current user (filled_for) or filled by them
            return submission.filled_for_email?.toLowerCase() === user.email?.toLowerCase() ||
                   submission.filled_by_email?.toLowerCase() === user.email?.toLowerCase();
          });

          setDueForms(relevantDueForms);
        }
      } catch (error) {
        console.error('Error fetching due forms:', error);
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchDueForms();
    }
  }, [user]);

  if (loading || dismissed || dueForms.length === 0) {
    return null;
  }

  const handleDismiss = () => {
    setDismissed(true);
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString();
  };

  return (
    <Card className="border-orange-200 bg-orange-50">
      <Card.Content className="p-4">
        <div className="flex items-start justify-between">
          <div className="flex items-center">
            <FiClock className="text-orange-500 mr-2" size={20} />
            <div>
              <h3 className="text-lg font-medium text-orange-800">
                Forms Due for Submission
              </h3>
              <p className="text-sm text-orange-600 mt-1">
                You have {dueForms.length} form{dueForms.length > 1 ? 's' : ''} that need attention.
              </p>
            </div>
          </div>
          <button
            onClick={handleDismiss}
            className="text-orange-400 hover:text-orange-600"
          >
            <FiX size={20} />
          </button>
        </div>

        <div className="mt-4 space-y-2">
          {dueForms.slice(0, 3).map((submission) => (
            <div
              key={submission.id}
              className="flex items-center justify-between p-3 bg-white rounded-md border border-orange-200"
            >
              <div className="flex-1">
                <h4 className="font-medium text-gray-900">{submission.form_title}</h4>
                <div className="flex items-center space-x-4 text-sm text-gray-600 mt-1">
                  <span>For: {submission.filled_for_name}</span>
                  <div className="flex items-center">
                    <FiCalendar className="mr-1" size={14} />
                    Due: {formatDate(submission.next_due_date)}
                  </div>
                </div>
              </div>
              <div className="flex items-center space-x-2">
                <Badge className="bg-orange-100 text-orange-800">
                  {submission.frequency}
                </Badge>
                <Button
                  size="sm"
                  onClick={() => window.location.href = `/forms/${submission.form_id}/submit`}
                >
                  Fill Form
                </Button>
              </div>
            </div>
          ))}

          {dueForms.length > 3 && (
            <div className="text-center pt-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => window.location.href = '/forms/submissions?tab=due'}
              >
                View all {dueForms.length} due forms
              </Button>
            </div>
          )}
        </div>
      </Card.Content>
    </Card>
  );
};

