// Server-side only auth functions that can safely import database operations

// Helper function to get employee ID from email
export const getEmployeeIdFromEmail = (email) => {
  try {
    const { getEmployeeByEmail } = require('./data');
    const employee = getEmployeeByEmail(email);
    return employee ? employee.id : null;
  } catch (error) {
    console.error('Error getting employee ID:', error);
    return null;
  }
};

// Helper function to check if employee is a team lead
export const isEmployeeTeamLead = (employeeId) => {
  try {
    const { isEmployeeTeamLead } = require('./data');
    return isEmployeeTeamLead(employeeId);
  } catch (error) {
    console.error('Error checking if employee is team lead:', error);
    return false;
  }
};

// Helper function to check if employee is a project manager
export const isEmployeeProjectManager = (employeeId) => {
  try {
    const { isEmployeeProjectManager } = require('./data');
    return isEmployeeProjectManager(employeeId);
  } catch (error) {
    console.error('Error checking if employee is project manager:', error);
    return false;
  }
};

export const canViewEmployeeServer = (user, employeeId) => {
  if (!user) return false;

  // Admin can view all employees
  if (user.role === 'admin') return true;

  // Users can view their own profile
  if (user.id === employeeId) return true;

  // Team leads can view their team members
  if (user.role === 'team_lead') {
    try {
      const { getDepartmentsForTeamLead, getDepartmentMembers } = require('./data');
      const departments = getDepartmentsForTeamLead(user.id);
      for (const dept of departments) {
        const members = getDepartmentMembers(dept.id);
        if (members.some(member => member.id === employeeId)) {
          return true;
        }
      }
    } catch (error) {
      console.error('Error checking team lead permissions:', error);
    }
  }

  // Project managers can view their project members
  if (user.role === 'project_manager') {
    try {
      const { getProjects, getProjectMembers } = require('./data');
      const projects = getProjects().filter(p => p.projectManagerId === user.id);
      for (const proj of projects) {
        const members = getProjectMembers(proj.id);
        if (members.some(member => member.id === employeeId)) {
          return true;
        }
      }
    } catch (error) {
      console.error('Error checking project manager permissions:', error);
    }
  }

  return false;
};

export const canViewDepartmentServer = (user, departmentId) => {
  if (!user) return false;

  // Admin can view all departments
  if (user.role === 'admin') return true;

  try {
    const { getEmployeeById, getDepartmentMembers } = require('./data');
    const employee = getEmployeeById(user.id);

    // Users can view their own department
    if (employee && employee.departmentId === departmentId) return true;

    // Team leads can view their departments
    if (user.role === 'team_lead') {
      const { getDepartmentsForTeamLead } = require('./data');
      const departments = getDepartmentsForTeamLead(user.id);
      return departments.some(dept => dept.id === departmentId);
    }
  } catch (error) {
    console.error('Error checking department permissions:', error);
  }

  return false;
};

export const canViewProjectServer = (user, projectId) => {
  if (!user) return false;

  // Admin can view all projects
  if (user.role === 'admin') return true;

  try {
    const { getProjectById, getProjectMembers } = require('./data');
    const project = getProjectById(projectId);

    // Project managers can view their projects
    if (user.role === 'project_manager' && project && project.projectManagerId === user.id) {
      return true;
    }

    // Team leads and employees can view projects they're members of
    const members = getProjectMembers(projectId);
    return members.some(member => member.id === user.id);
  } catch (error) {
    console.error('Error checking project permissions:', error);
  }

  return false;
};

export const canViewReportServer = (user, reportUserId) => {
  if (!user) return false;

  // Admin can view all reports
  if (user.role === 'admin') return true;

  // Users can view their own reports
  if (user.id === reportUserId) return true;

  // Team leads can view reports of their team members
  if (user.role === 'team_lead') {
    try {
      const { getDepartmentsForTeamLead, getDepartmentMembers } = require('./data');
      const departments = getDepartmentsForTeamLead(user.id);
      for (const dept of departments) {
        const members = getDepartmentMembers(dept.id);
        if (members.some(member => member.id === reportUserId)) {
          return true;
        }
      }
    } catch (error) {
      console.error('Error checking team lead report permissions:', error);
    }
  }

  // Project managers can view reports of their project members
  if (user.role === 'project_manager') {
    try {
      const { getProjects, getProjectMembers } = require('./data');
      const projects = getProjects().filter(p => p.projectManagerId === user.id);
      for (const proj of projects) {
        const members = getProjectMembers(proj.id);
        if (members.some(member => member.id === reportUserId)) {
          return true;
        }
      }
    } catch (error) {
      console.error('Error checking project manager report permissions:', error);
    }
  }

  return false;
};

