/**
 * Authentication and Authorization Helper Functions for API endpoints
 */

// Extract user from request cookies
export const getUserFromRequest = (req) => {
  try {
    if (req.headers.cookie) {
      const cookies = req.headers.cookie.split(';').reduce((acc, cookie) => {
        const [key, value] = cookie.trim().split('=');
        acc[key] = value;
        return acc;
      }, {});

      if (cookies.user) {
        return JSON.parse(decodeURIComponent(cookies.user));
      }
    }
    return null;
  } catch (error) {
    console.error('Error parsing user from cookies:', error);
    return null;
  }
};

// Check if user is authenticated
export const requireAuth = (req, res, next) => {
  const user = getUserFromRequest(req);
  if (!user) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  req.user = user;
  if (next) next();
  return user;
};

// Check if user has admin role
export const requireAdmin = (req, res, next) => {
  const user = requireAuth(req, res);
  if (!user) return false;

  if (user.role !== 'admin') {
    return res.status(403).json({ error: 'Access denied. Administrator privileges required.' });
  }

  if (next) next();
  return true;
};

// Check if user has project manager role or is admin
export const requireProjectManagerOrAdmin = (req, res, next) => {
  const user = requireAuth(req, res);
  if (!user) return false;

  if (user.role !== 'admin' && user.role !== 'project_manager') {
    return res.status(403).json({ error: 'Access denied. Project Manager or Administrator privileges required.' });
  }

  if (next) next();
  return true;
};

// Check if user has team lead role or is admin
export const requireTeamLeadOrAdmin = (req, res, next) => {
  const user = requireAuth(req, res);
  if (!user) return false;

  if (user.role !== 'admin' && user.role !== 'team_lead') {
    return res.status(403).json({ error: 'Access denied. Team Lead or Administrator privileges required.' });
  }

  if (next) next();
  return true;
};

// Check if user can manage the specified project (project manager of that project or admin)
export const canManageProject = async (user, projectId) => {
  if (!user) return false;

  // Admin can manage all projects
  if (user.role === 'admin') return true;

  // Check if user is the project manager
  try {
    const { getProjectById } = require('./data');
    const project = await getProjectById(projectId);

    if (project && (
      project.manager_id === user.id || 
      project.project_manager_id === user.id ||
      project.assigned_pm === user.email
    )) {
      return true;
    }
  } catch (error) {
    console.error('Error checking project management permissions:', error);
  }

  return false;
};

// Generic response helpers
export const unauthorized = (res, message = 'Authentication required') => {
  return res.status(401).json({ error: message });
};

export const forbidden = (res, message = 'Access denied') => {
  return res.status(403).json({ error: message });
};

export const badRequest = (res, message = 'Bad request') => {
  return res.status(400).json({ error: message });
};

export const serverError = (res, message = 'Internal server error', details = null) => {
  const response = { error: message };
  if (details) response.details = details;
  return res.status(500).json(response);
};

