// Utility function to safely serialize dates for Next.js JSON serialization
export const safeSerializeDate = (date) => {
  if (date instanceof Date) {
    return date.toISOString();
  }
  if (date === undefined) {
    return null;
  }
  return date;
};

// Utility function to serialize an object with date fields
export const serializeObject = (obj, dateFields = []) => {
  if (!obj) return obj;

  const serialized = { ...obj };
  dateFields.forEach(field => {
    if (field in serialized) {
      serialized[field] = safeSerializeDate(serialized[field]);
    }
  });

  return serialized;
};

// Utility function to serialize arrays of objects with date fields
export const serializeArray = (array, dateFields = []) => {
  if (!Array.isArray(array)) return array;

  return array.map(item => serializeObject(item, dateFields));
};

