require('dotenv').config({ path: '.env.local' });
const { query, testConnection } = require('./postgres.js');

async function migrateDatabase() {
  try {
    console.log('Testing database connection...');
    const isConnected = await testConnection();

    if (!isConnected) {
      console.error('Failed to connect to database. Please check your connection settings.');
      return false;
    }

    console.log('Starting database migration...');

    // Check existing tables
    const existingTables = await query(`
      SELECT table_name 
      FROM information_schema.tables 
      WHERE table_schema = 'public' 
      ORDER BY table_name
    `);

    console.log('Existing tables:', existingTables.rows.map(r => r.table_name));

    // Drop existing tables if they exist (in correct order to handle foreign keys)
    const tablesToDrop = [
      'submission_answers',
      'form_submissions', 
      'question_options',
      'form_questions',
      'score_categories',
      'score_forms',
      'allocation_members',
      'project_allocations',
      'project_members',
      'projects',
      'department_team_leads',
      'employees',
      'departments',
      'scores',
      'otps'
    ];

    for (const table of tablesToDrop) {
      try {
        await query(`DROP TABLE IF EXISTS ${table} CASCADE`);
        console.log(`Dropped table: ${table}`);
      } catch (error) {
        console.log(`Table ${table} doesn't exist or couldn't be dropped:`, error.message);
      }
    }

    // Drop existing types if they exist
    const typesToDrop = [
      'user_role',
      'form_frequency', 
      'form_status',
      'audience_type',
      'question_type',
      'reporting_period'
    ];

    for (const type of typesToDrop) {
      try {
        await query(`DROP TYPE IF EXISTS ${type} CASCADE`);
        console.log(`Dropped type: ${type}`);
      } catch (error) {
        console.log(`Type ${type} doesn't exist or couldn't be dropped:`, error.message);
      }
    }

    console.log('Migration completed successfully!');
    return true;
  } catch (error) {
    console.error('Error during migration:', error);
    return false;
  }
}

// Run migration if this file is executed directly
if (require.main === module) {
  migrateDatabase()
    .then((success) => {
      if (success) {
        console.log('Migration completed. Now run: node lib/setup-db.js');
      }
      process.exit(success ? 0 : 1);
    })
    .catch((error) => {
      console.error('Migration failed:', error);
      process.exit(1);
    });
}

module.exports = { migrateDatabase };

