const { query, getClient } = require('./postgres.js');
const { v4: uuidv4 } = require('uuid');

// ===== DEPARTMENT FUNCTIONS =====
const getDepartments = async () => {
  try {
    const result = await query('SELECT * FROM departments ORDER BY created_at DESC');
    return result.rows;
  } catch (error) {
    console.error('Error fetching departments:', error);
    throw error;
  }
};

const getDepartmentById = async (id) => {
  try {
    const result = await query('SELECT * FROM departments WHERE id = $1', [id]);
    return result.rows[0] || null;
  } catch (error) {
    console.error('Error fetching department by id:', error);
    throw error;
  }
};

const addDepartment = async (departmentData) => {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    const departmentId = `dept-${Date.now()}`;
    const newDepartment = {
      id: departmentId,
      name: departmentData.name,
      team_lead_id: departmentData.teamLeadId || null,
      created_at: new Date(),
      updated_at: new Date()
    };

    const result = await client.query(
      'INSERT INTO departments (id, name, team_lead_id, created_at, updated_at) VALUES ($1, $2, $3, $4, $5) RETURNING *',
      [newDepartment.id, newDepartment.name, newDepartment.team_lead_id, newDepartment.created_at, newDepartment.updated_at]
    );

    // Add team leads if provided
    if (departmentData.teamLeadIds && Array.isArray(departmentData.teamLeadIds)) {
      for (const leadId of departmentData.teamLeadIds) {
        if (leadId) {
          await client.query(
            'INSERT INTO department_team_leads (department_id, employee_id, created_at, updated_at) VALUES ($1, $2, $3, $4)',
            [departmentId, leadId, new Date(), new Date()]
          );
        }
      }
    } else if (departmentData.teamLeadId) {
      await client.query(
        'INSERT INTO department_team_leads (department_id, employee_id, created_at, updated_at) VALUES ($1, $2, $3, $4)',
        [departmentId, departmentData.teamLeadId, new Date(), new Date()]
      );
    }

    await client.query('COMMIT');
    return result.rows[0];
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error adding department:', error);
    throw error;
  } finally {
    client.release();
  }
};

const updateDepartment = async (id, departmentData) => {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    const result = await client.query(
      'UPDATE departments SET name = $1, team_lead_id = $2, updated_at = $3 WHERE id = $4 RETURNING *',
      [departmentData.name, departmentData.teamLeadId || null, new Date(), id]
    );

    if (result.rows.length === 0) {
      await client.query('ROLLBACK');
      return null;
    }

    // Update team leads if provided
    if (departmentData.teamLeadIds && Array.isArray(departmentData.teamLeadIds)) {
      // Remove existing team leads
      await client.query('DELETE FROM department_team_leads WHERE department_id = $1', [id]);

      // Add new team leads
      for (const leadId of departmentData.teamLeadIds) {
        if (leadId) {
          await client.query(
            'INSERT INTO department_team_leads (department_id, employee_id, created_at, updated_at) VALUES ($1, $2, $3, $4)',
            [id, leadId, new Date(), new Date()]
          );
        }
      }
    }

    await client.query('COMMIT');
    return result.rows[0];
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error updating department:', error);
    throw error;
  } finally {
    client.release();
  }
};

const deleteDepartment = async (id) => {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    // Update employees to remove department reference
    await client.query('UPDATE employees SET department_id = NULL WHERE department_id = $1', [id]);

    // Remove department team leads
    await client.query('DELETE FROM department_team_leads WHERE department_id = $1', [id]);

    // Delete department
    const result = await client.query('DELETE FROM departments WHERE id = $1', [id]);

    await client.query('COMMIT');
    return result.rowCount > 0;
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error deleting department:', error);
    throw error;
  } finally {
    client.release();
  }
};

