const getEmployees = async () => {
  try {
    const result = await query(`
      SELECT 
        e.id,
        e.name,
        e.email,
        e.phone_number,
        e.designation,
        e.department_id,
        e.job_role,
        e.employee_number,
        e.joining_date,
        e.created_at,
        e.updated_at,
        d.id as department_id,
        d.name as department_name
      FROM employees e
      LEFT JOIN departments d ON e.department_id = d.id
      ORDER BY e.created_at DESC
    `);

    // Process the results to normalize field names and department data
    return result.rows.map(emp => ({
      ...emp,
      // Normalize field names for consistency
      departmentId: emp.department_id,
      phoneNumber: emp.phone_number,
      jobRole: emp.job_role,
      // Add department info
      department: emp.department_id ? {
        id: emp.department_id,
        name: emp.department_name
      } : null,
      // Ensure joining_date is properly formatted
      joining_date: emp.joining_date instanceof Date ? emp.joining_date.toISOString() : (emp.joining_date || null)
    }));
  } catch (error) {
    console.error('Error fetching employees:', error);
    throw error;
  }
};

