const copyAllocationFromMonth = async (projectId, sourceMonth, sourceYear, targetMonth, targetYear) => {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    // Find source allocation
    const sourceResult = await client.query(
      'SELECT * FROM project_allocations WHERE project_id = $1 AND month = $2 AND year = $3',
      [projectId, sourceMonth, sourceYear]
    );

    if (sourceResult.rows.length === 0) {
      await client.query('ROLLBACK');
      return null;
    }

    const sourceAllocation = sourceResult.rows[0];

    // Check if target allocation already exists
    const targetResult = await client.query(
      'SELECT * FROM project_allocations WHERE project_id = $1 AND month = $2 AND year = $3',
      [projectId, targetMonth, targetYear]
    );

    let targetAllocation;

    if (targetResult.rows.length > 0) {
      // Update existing allocation
      const updateResult = await client.query(
        'UPDATE project_allocations SET project_manager_id = $1, updated_at = $2 WHERE id = $3 RETURNING *',
        [sourceAllocation.project_manager_id, new Date(), targetResult.rows[0].id]
      );
      targetAllocation = updateResult.rows[0];
    } else {
      // Create new allocation
      const allocationId = `alloc-${Date.now()}`;
      const insertResult = await client.query(
        'INSERT INTO project_allocations (id, project_id, month, year, project_manager_id, created_at, updated_at) VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING *',
        [allocationId, projectId, targetMonth, targetYear, sourceAllocation.project_manager_id, new Date(), new Date()]
      );
      targetAllocation = insertResult.rows[0];
    }

    // Remove existing members from target if it already existed
    await client.query('DELETE FROM allocation_members WHERE allocation_id = $1', [targetAllocation.id]);

    // Copy members from source to target
    const membersResult = await client.query(
      'SELECT employee_id FROM allocation_members WHERE allocation_id = $1',
      [sourceAllocation.id]
    );

    for (const member of membersResult.rows) {
      await client.query(
        'INSERT INTO allocation_members (allocation_id, employee_id, created_at, updated_at) VALUES ($1, $2, $3, $4)',
        [targetAllocation.id, member.employee_id, new Date(), new Date()]
      );
    }

    await client.query('COMMIT');
    return targetAllocation;
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error copying allocation from month:', error);
    throw error;
  } finally {
    client.release();
  }
};

const copyAllAllocationsFromPreviousMonth = async (currentMonth, currentYear) => {
  // Calculate previous month
  let prevMonth = parseInt(currentMonth, 10) - 1;
  let prevYear = parseInt(currentYear, 10);

  if (prevMonth === 0) {
    prevMonth = 12;
    prevYear -= 1;
  }

  // Format month to have leading zero if needed
  prevMonth = prevMonth < 10 ? `0${prevMonth}` : `${prevMonth}`;

  try {
    // Get all projects
    const projects = await getProjects();
    const results = [];

    // For each project, copy allocation from previous month if exists
    for (const project of projects) {
      try {
        const result = await copyAllocationFromMonth(
          project.id,
          prevMonth,
          prevYear.toString(),
          currentMonth,
          currentYear
        );

        if (result) {
          results.push({
            projectId: project.id,
            projectName: project.name,
            allocationId: result.id,
            success: true
          });
        } else {
          results.push({
            projectId: project.id,
            projectName: project.name,
            success: false
          });
        }
      } catch (error) {
        results.push({
          projectId: project.id,
          projectName: project.name,
          success: false,
          error: error.message
        });
      }
    }

    return results;
  } catch (error) {
    console.error('Error copying all allocations from previous month:', error);
    throw error;
  }
};

