    const formResult = await query('SELECT * FROM score_forms WHERE id = $1', [id]);
    if (formResult.rows.length === 0) return null;

    const form = formResult.rows[0];

    // Get form questions
    const questionsResult = await query(`
      SELECT 
        fq.*,
        COALESCE(
          json_agg(
            json_build_object(
              'id', qo.id,
              'value', qo.option_text,
              'label', qo.option_text
            ) ORDER BY qo.order_number
          ) FILTER (WHERE qo.id IS NOT NULL),
          '[]'::json
        ) as options
      FROM form_questions fq
      LEFT JOIN question_options qo ON fq.id = qo.question_id
      WHERE fq.form_id = $1
      GROUP BY fq.id, fq.order_number
      ORDER BY fq.order_number
    `, [id]);

    // Format questions for frontend compatibility
    const questions = questionsResult.rows.map(q => ({
      id: q.id,
      type: q.question_type,
      title: q.question_text,
      question: q.question_text,
      description: q.description || null,
      required: q.is_required || false,
      placeholder: q.placeholder || null,
      options: q.options || [],
      min_value: q.min_value || null,
      max_value: q.max_value || null,
      max_score: q.max_score || null,
      score_weight: q.score_weight || null,
      category_id: q.category_id || null,
      scale: q.min_value && q.max_value ? {
        min: q.min_value,
        max: q.max_value,
        min_label: q.min_label || null,
        max_label: q.max_label || null
      } : null
    }));

    return {
      ...form,
      questions: questions
    };
  } catch (error) {
    console.error('Error fetching form by id:', error);
    throw error;
  }
};

