// Helper function to update a question
const updateFormQuestion = async (questionId, formId, questionData) => {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    // Update question
    const result = await client.query(
      'UPDATE form_questions SET question_text = $1, question_type = $2, is_required = $3, order_number = $4, updated_at = $5 WHERE id = $6 AND form_id = $7 RETURNING *',
      [questionData.question, questionData.type, questionData.required, questionData.order_number || 0, new Date(), questionId, formId]
    );

    if (result.rows.length === 0) {
      await client.query('ROLLBACK');
      return null;
    }

    // Update options if provided
    if (questionData.options && Array.isArray(questionData.options)) {
      // Delete existing options
      await client.query('DELETE FROM question_options WHERE question_id = $1', [questionId]);

      // Add new options
      for (let i = 0; i < questionData.options.length; i++) {
        const option = questionData.options[i];
        await client.query(
          'INSERT INTO question_options (id, question_id, option_text, order_number, created_at, updated_at) VALUES ($1, $2, $3, $4, $5, $6)',
          [uuidv4(), questionId, option.label || option, i, new Date(), new Date()]
        );
      }
    }

    await client.query('COMMIT');
    return result.rows[0];
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error updating form question:', error);
    throw error;
  } finally {
    client.release();
  }
};

// Helper function to delete a question
const deleteFormQuestion = async (questionId, formId) => {
  const client = await getClient();

  try {
    await client.query('BEGIN');

    // Delete question options first
    await client.query('DELETE FROM question_options WHERE question_id = $1', [questionId]);

    // Delete question
    const result = await client.query(
      'DELETE FROM form_questions WHERE id = $1 AND form_id = $2 RETURNING *',
      [questionId, formId]
    );

    await client.query('COMMIT');
    return result.rows.length > 0;
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error deleting form question:', error);
    throw error;
  } finally {
    client.release();
  }
};

