import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import '../styles/globals.css';
import Layout from '../components/Layout';
import { isAuthenticated, getUser } from '../lib/auth';

function MyApp({ Component, pageProps }) {
  const router = useRouter();
  const [loaded, setLoaded] = useState(false);
  const [user, setUser] = useState(null);

  useEffect(() => {
    // Check if user is authenticated
    const checkAuth = async () => {
      const isAuthed = isAuthenticated();
      const currentUser = getUser();
      setUser(currentUser);

      // If not authenticated and not on login page, redirect to login
      if (!isAuthed && router.pathname !== '/login') {
        router.push('/login');
      }

      // Handle role-based access restrictions
      if (isAuthed && currentUser && !canAccessPage(currentUser, router.pathname)) {
        router.push('/unauthorized');
      }

      setLoaded(true);
    };

    checkAuth();
  }, [router.pathname]);

  // Function to check if user can access the current page based on their role
  const canAccessPage = (user, path) => {
    if (!user) return false;

    // Admin can access everything
    if (user.role === 'admin') return true;

    // Public pages that anyone can access when logged in
    const publicPages = ['/', '/profile', '/unauthorized'];
    if (publicPages.some(p => path === p || path.startsWith('/profile/'))) return true;

    // Employee-specific access for portal features
    if (user.isEmployee || user.role === 'employee') {
      // Employees can access their own projects, forms, and reports
      if (path.startsWith('/projects') && path.includes('my=true')) return true;
      if (path.startsWith('/forms') && path.includes('my=true')) return true; 
      if (path.startsWith('/reports') && path.includes('my=true')) return true;

      // Employees can also access form submission pages
      if (path.match(/^\/forms\/[^\/]+\/submit$/)) return true;
      if (path.match(/^\/forms\/[^\/]+\/preview$/)) return true;
      if (path.match(/^\/forms\/[^\/]+\/view-submission$/)) return true;

      // Allow basic access to main pages (they have internal filtering)
      if (path === '/projects' || path === '/forms' || path === '/reports') return true;

      // Allow employees to access individual project pages (they can view their assigned projects)
      if (path.match(/^\/projects\/[^\/]+$/)) return true;
    }

    // Path-specific permissions for non-employee roles
    if (path.startsWith('/employees')) {
      // Team leads, project managers, and co-founders can view employees, plus admins
      return ['admin', 'team_lead', 'project_manager', 'co_founder'].includes(user.role);
    }

    if (path.startsWith('/departments')) {
      // Team leads and admins can view departments
      return ['admin', 'team_lead'].includes(user.role);
    }

    if (path.startsWith('/projects')) {
      // Project managers, team leads, admins can view projects
      // Employees can also view individual project pages for their assignments
      return ['admin', 'project_manager', 'team_lead'].includes(user.role) || 
             (user.isEmployee || user.role === 'employee');
    }

    if (path.startsWith('/reports')) {
      // Everyone can access reports (access control is handled in the reports page)
      return true;
    }

    if (path.startsWith('/forms')) {
      // Admins and employees can access forms (with internal filtering)
      return user.role === 'admin' || user.isEmployee || user.role === 'employee';
    }

    // Analytics is admin only
    if (path.startsWith('/analytics')) {
      return user.role === 'admin';
    }

    // Default allow access for authenticated users to other pages
    return true;
  };

  if (!loaded) {
    return null;
  }

  // If the path is /login, don't wrap with Layout
  if (router.pathname === '/login') {
    return (
      <>
        <Component {...pageProps} />
        <ToastContainer 
          position="top-right"
          autoClose={3000}
          hideProgressBar={false}
          newestOnTop
          closeOnClick
          rtl={false}
          pauseOnFocusLoss
          draggable
          pauseOnHover
        />
      </>
    );
  }

  // For unauthorized page
  if (router.pathname === '/unauthorized') {
    return (
      <>
        <Component {...pageProps} />
        <ToastContainer 
          position="top-right"
          autoClose={3000}
          hideProgressBar={false}
          newestOnTop
          closeOnClick
          rtl={false}
          pauseOnFocusLoss
          draggable
          pauseOnHover
        />
      </>
    );
  }

  return (
    <>
      <Layout>
        <Component {...pageProps} user={user} />
      </Layout>
      <ToastContainer 
        position="top-right"
        autoClose={3000}
        hideProgressBar={false}
        newestOnTop
        closeOnClick
        rtl={false}
        pauseOnFocusLoss
        draggable
        pauseOnHover
      />
    </>
  );
}

export default MyApp;

