import { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { FiUsers, FiLayers, FiUserPlus, FiFolderPlus, FiBriefcase, FiPlusCircle, FiFileText, FiBarChart2 } from 'react-icons/fi';
import { DashboardCard } from '../components/DashboardCard';
import { Card } from '../components/Card';
import { Button } from '../components/Button';
import { Avatar } from '../components/Avatar';
import { serializeArray, serializeObject, COMMON_DATE_FIELDS } from '../lib/utils';

export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getDepartments, getEmployees, getProjects, getDepartmentMembers, getProjectMembers, getForms, getProjectAllocations, getFormSubmissions } = require('../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    const [departments, employees, projects, forms, projectAllocations, formSubmissions] = await Promise.all([
      getDepartments(),
      getEmployees(),
      getProjects(),
      getForms(),
      getProjectAllocations().catch(() => []), // Fallback if function doesn't exist
      getFormSubmissions().catch(() => [])
    ]);

    // For employee users AND project managers, filter data to their specific info
    let employeeData = null;
    let employeeProjects = [];
    let employeeForms = [];

    if (user && (user.isEmployee || user.role === 'employee' || user.role === 'project_manager') && user.email) {
      // Find employee data
      employeeData = employees.find(emp => 
        emp.email.toLowerCase() === user.email.toLowerCase()
      );

      if (employeeData) {
        // Get employee's department
        let employeeDepartment = null;
        if (employeeData.department_id) {
          employeeDepartment = departments.find(dept => dept.id === employeeData.department_id);
        }

        // Get employee's projects - FIXED: Check both project_allocations AND project_members
        // Also check if user is a project manager for any projects
        const userEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());
        if (userEmployee) {
          const assignedProjectIds = new Set();

          // Check project allocations
          try {
            const userAllocations = projectAllocations.filter(allocation => allocation.employee_id === userEmployee.id);
            userAllocations.forEach(allocation => assignedProjectIds.add(allocation.project_id));
          } catch (error) {
            console.error('Error fetching project allocations for dashboard:', error);
          }

          // Check project members for each project
          for (const project of projects) {
            try {
              const { getProjectMembers } = require('../lib/data');
              const members = await getProjectMembers(project.id);
              const isMember = members.some(member => 
                member.id === userEmployee.id || 
                member.employee_id === userEmployee.id
              );
              if (isMember) {
                assignedProjectIds.add(project.id);
              }
            } catch (error) {
              console.error(`Error checking membership for project ${project.id} in dashboard:`, error);
            }
          }

          // For project managers, also check if they manage any projects
          if (user.role === 'project_manager') {
            const managedProjects = projects.filter(project => 
              project.manager_id === user.id || 
              project.project_manager_id === user.id ||
              project.assigned_pm === user.email
            );
            managedProjects.forEach(project => assignedProjectIds.add(project.id));
          }

          employeeProjects = projects.filter(project => assignedProjectIds.has(project.id));
          console.log(`Dashboard: Found ${employeeProjects.length} projects for user ${userEmployee.name} (role: ${user.role})`);
        }

        // Get employee's forms (only those they haven't completed)
        const userSubmissions = formSubmissions.filter(submission => 
          submission.user_email?.toLowerCase() === user.email?.toLowerCase() ||
          submission.filled_by_email?.toLowerCase() === user.email?.toLowerCase()
        );

        const completedFormIds = new Set(
          userSubmissions
            .filter(sub => sub.status === 'completed')
            .map(sub => sub.form_id)
        );

        employeeForms = forms.filter(form => {
          // Skip if already completed
          if (completedFormIds.has(form.id)) return false;

          if (form.status !== 'published') return false;
          switch (form.audience) {
            case 'all':
              return true;
            case 'employee':
              return user.isEmployee || user.role === 'employee';
            case 'project_manager':
              return user.role === 'project_manager';
            case 'team_lead':
              return user.role === 'team_lead';
            case 'co_founders':
              return user.role === 'co_founder';
            case 'employee_to_pm':
              return user.isEmployee || user.role === 'employee' || user.role === 'project_manager';
            case 'pm_to_employee':
              return user.role === 'project_manager' || user.isEmployee || user.role === 'employee';
            default:
              return false;
          }
        });
      }
    }

    // Calculate department distribution
    const distribution = Array.isArray(departments) ? await Promise.all(
      departments.map(async (dept) => ({
        id: dept.id,
        name: dept.name,
        count: (await getDepartmentMembers(dept.id)).length
      }))
    ) : [];

    // Sort by count (descending)
    distribution.sort((a, b) => b.count - a.count);

    // Get recent employees and serialize dates
    const recentEmps = Array.isArray(employees) ? [...employees].slice(0, 3).map(emp => {
      const { joining_date, ...empRest } = emp; // Exclude joining_date to avoid serialization issues
      return serializeObject(empRest, ['created_at', 'updated_at']);
    }) : [];

    const stats = {
      totalEmployees: Array.isArray(employees) ? employees.length : 0,
      totalDepartments: Array.isArray(departments) ? departments.length : 0,
      totalProjects: Array.isArray(projects) ? projects.length : 0,
      totalForms: Array.isArray(forms) ? forms.length : 0,
      recentEmployees: recentEmps,
      departmentDistribution: distribution
    };

    // Serialize employee data
    const serializedEmployeeData = employeeData ? (() => {
      const { joining_date, ...restEmp } = employeeData;
      return serializeObject(restEmp, ['created_at', 'updated_at']);
    })() : null;

    const serializedEmployeeProjects = serializeArray(employeeProjects, COMMON_DATE_FIELDS.project);

    // Fix: Serialize ALL date fields in forms
    const serializedEmployeeForms = serializeArray(employeeForms, COMMON_DATE_FIELDS.form);

    return {
      props: {
        initialStats: stats,
        user: user,
        employeeData: serializedEmployeeData,
        employeeProjects: serializedEmployeeProjects,
        employeeForms: serializedEmployeeForms
      }
    };
  } catch (error) {
    console.error('Error fetching dashboard data:', error);
    return {
      props: {
        initialStats: {
          totalEmployees: 0,
          totalDepartments: 0,
          totalProjects: 0,
          totalForms: 0,
          recentEmployees: [],
          departmentDistribution: []
        },
        user: null,
        employeeData: null,
        employeeProjects: [],
        employeeForms: []
      }
    };
  }
}

export default function Home({ initialStats, user, employeeData, employeeProjects, employeeForms }) {
  const [stats, setStats] = useState(initialStats);
  const [projects, setProjects] = useState(employeeProjects);
  const [forms, setForms] = useState(employeeForms);
  const [lastRefresh, setLastRefresh] = useState(Date.now());
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Real-time refresh functionality for employee dashboard
  useEffect(() => {
    if (user && (user.isEmployee || user.role === 'employee' || user.role === 'project_manager')) {
      const refreshEmployeeData = async () => {
        try {
          setIsRefreshing(true);

          // Fetch updated data from the employee dashboard API
          const response = await fetch('/api/dashboard/employee');

          if (response.ok) {
            const data = await response.json();
            setProjects(data.projects);
            setForms(data.forms);
            console.log(`Dashboard refreshed: ${data.projectCount} projects, ${data.formCount} forms`);
          } else {
            console.error('Failed to refresh dashboard data:', response.statusText);
          }

          setLastRefresh(Date.now());
        } catch (error) {
          console.error('Error refreshing employee dashboard data:', error);
        } finally {
          setIsRefreshing(false);
        }
      };

      // Auto-refresh every 2 minutes
      const interval = setInterval(refreshEmployeeData, 120000);

      // Listen for project/form updates from other tabs/windows
      const handleVisibilityChange = () => {
        if (!document.hidden) {
          refreshEmployeeData();
        }
      };

      document.addEventListener('visibilitychange', handleVisibilityChange);

      return () => {
        clearInterval(interval);
        document.removeEventListener('visibilitychange', handleVisibilityChange);
      };
    }
  }, [user]);

  const handleManualRefresh = async () => {
    if (user && user.isEmployee) {
      try {
        setIsRefreshing(true);

        // Refresh the entire page to get server-side data
        window.location.reload();
      } catch (error) {
        console.error('Error refreshing dashboard:', error);
        setIsRefreshing(false);
      }
    }
  };

  // If user is an employee, show employee dashboard
  if (user && user.isEmployee) {
    return (
      <div className="space-y-8 fade-in">
