export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getDepartments, 
    getEmployees 
  } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    const [departments, employees] = await Promise.all([
      getDepartments(),
      getEmployees()
    ]);

    // Filter departments based on user role
    let filteredDepartments = departments;
    let userDepartment = null;

    if (user && user.role === 'team_lead') {
      // Team leads only see their own department
      const teamLeadEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());
      if (teamLeadEmployee) {
        userDepartment = departments.find(dept => dept.id === teamLeadEmployee.department_id);
        filteredDepartments = userDepartment ? [userDepartment] : [];
      }
    }

    // Calculate member counts and pass through dates
    const enhancedDepartments = Array.isArray(filteredDepartments) ? filteredDepartments.map(dept => {
      const memberCount = employees.filter(emp => emp.department_id === dept.id || emp.departmentId === dept.id).length;
      const departmentMembers = employees.filter(emp => emp.department_id === dept.id || emp.departmentId === dept.id);

      return {
        ...dept,
        memberCount,
        members: departmentMembers.map(emp => ({
          ...emp,
          created_at: emp.created_at instanceof Date ? emp.created_at.toISOString() : (emp.created_at || null),
          updated_at: emp.updated_at instanceof Date ? emp.updated_at.toISOString() : (emp.updated_at || null),
        })),
        created_at: dept.created_at instanceof Date ? dept.created_at.toISOString() : (dept.created_at || null),
        updated_at: dept.updated_at instanceof Date ? dept.updated_at.toISOString() : (dept.updated_at || null)
      };
    }) : [];

    return {
      props: {
        initialDepartments: enhancedDepartments,
        user: user,
        userDepartment: userDepartment ? {
          ...userDepartment,
          created_at: userDepartment.created_at instanceof Date ? userDepartment.created_at.toISOString() : (userDepartment.created_at || null),
          updated_at: userDepartment.updated_at instanceof Date ? userDepartment.updated_at.toISOString() : (userDepartment.updated_at || null)
        } : null
      }
    };
  } catch (error) {
    console.error('Error fetching departments data:', error);
    return {
      props: {
        initialDepartments: [],
        user: null,
        userDepartment: null
      }
    };
  }
}

