export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getDepartmentById, 
    getDepartmentMembers, 
    getDepartmentTeamLeads,
    getEmployees
  } = require('../../../lib/data');
  const { id } = context.params;

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    if (!user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    const [deptData, memberData, teamLeadData, allEmployees] = await Promise.all([
      getDepartmentById(id),
      getDepartmentMembers(id),
      getDepartmentTeamLeads(id),
      getEmployees()
    ]);

    if (!deptData) {
      return {
        notFound: true
      };
    }

    // Access control: Users can only view their own department (except admins)
    if (user.role !== 'admin') {
      // Find the user's employee record to get their department
      const userEmployee = allEmployees.find(emp => 
        emp.email?.toLowerCase() === user.email?.toLowerCase()
      );

      if (!userEmployee) {
        return {
          redirect: {
            destination: '/unauthorized',
            permanent: false,
          },
        };
      }

      // Check if user belongs to this department
      const userDepartmentId = userEmployee.department_id || userEmployee.departmentId;
      if (userDepartmentId !== id && userDepartmentId !== parseInt(id)) {
        return {
          redirect: {
            destination: '/unauthorized',
            permanent: false,
          },
        };
      }
    }

    // Get available employees (employees not in this department) - only for admins
    const availableEmps = user.role === 'admin' 
      ? allEmployees.filter(emp => emp.departmentId !== id && emp.department_id !== id)
      : [];

    // Serialize dates
    const serializedDepartment = {
      ...deptData,
      created_at: deptData.created_at ? deptData.created_at.toISOString() : null,
      updated_at: deptData.updated_at ? deptData.updated_at.toISOString() : null
    };

    const serializedMembers = memberData.map(member => ({
      ...member,
      created_at: member.created_at ? member.created_at.toISOString() : null,
      updated_at: member.updated_at ? member.updated_at.toISOString() : null
    }));

    const serializedTeamLeads = teamLeadData.map(lead => ({
      ...lead,
      created_at: lead.created_at ? lead.created_at.toISOString() : null,
      updated_at: lead.updated_at ? lead.updated_at.toISOString() : null
    }));

    const serializedAvailableEmployees = availableEmps.map(emp => ({
      ...emp,
      created_at: emp.created_at ? emp.created_at.toISOString() : null,
      updated_at: emp.updated_at ? emp.updated_at.toISOString() : null
    }));

    return {
      props: {
        department: serializedDepartment,
        members: serializedMembers,
        teamLeads: serializedTeamLeads,
        availableEmployees: serializedAvailableEmployees,
        user: user
      }
    };
  } catch (error) {
    console.error('Error fetching department data:', error);
    return {
      notFound: true
    };
  }
}

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { 
  FiArrowLeft, FiEdit, FiTrash2, FiPlus, 
  FiUsers, FiUser, FiMail, FiPhone, FiBriefcase 
} from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Card } from '../../../components/Card';
import { Avatar } from '../../../components/Avatar';
import { Modal } from '../../../components/Modal';
import { EmptyState } from '../../../components/EmptyState';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';

export default function DepartmentDetails({ department: initialDepartment, members: initialMembers, teamLeads: initialTeamLeads, availableEmployees: initialAvailableEmployees, user }) {
  const [department, setDepartment] = useState(initialDepartment);
  const [members, setMembers] = useState(initialMembers);
  const [teamLeads, setTeamLeads] = useState(initialTeamLeads);
  const [loading, setLoading] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isAddEmployeeModalOpen, setIsAddEmployeeModalOpen] = useState(false);
  const [availableEmployees, setAvailableEmployees] = useState(initialAvailableEmployees);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState('');
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [isRemoveMemberModalOpen, setIsRemoveMemberModalOpen] = useState(false);
  const [memberToRemove, setMemberToRemove] = useState(null);
  const [isRemovingMember, setIsRemovingMember] = useState(false);
  const [isRemoveTeamLeadModalOpen, setIsRemoveTeamLeadModalOpen] = useState(false);
  const [teamLeadToRemove, setTeamLeadToRemove] = useState(null);
  const router = useRouter();
  const { id } = router.query;

  // Check if user can manage this department (admin only)
  const canManageDepartment = user && user.role === 'admin';

  const loadDepartmentData = async () => {
    try {
      // Refresh data via API calls
      const response = await fetch(`/api/departments/${id}`);
      if (response.ok) {
        const deptData = await response.json();
        setDepartment(deptData);
      }
    } catch (error) {
      console.error('Failed to load department data:', error);
      toast.error('Failed to load department data');
    }
  };

  const handleDelete = async () => {
    setIsDeleting(true);

    try {
      const response = await fetch(`/api/departments/${id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        toast.success(`Department "${department.name}" has been deleted`);
        router.push('/departments');
      } else {
        throw new Error('Failed to delete department');
      }
    } catch (error) {
      console.error('Failed to delete department:', error);
      toast.error('Failed to delete department');
      setIsDeleting(false);
      setIsDeleteModalOpen(false);
    }
  };

  const handleAddEmployeeClick = () => {
    setSelectedEmployeeId('');
    setIsAddEmployeeModalOpen(true);
  };

  const handleEmployeeSelect = (e) => {
    setSelectedEmployeeId(e.target.value);
  };

  const handleAddEmployee = async () => {
    if (!selectedEmployeeId) {
      toast.error('Please select an employee');
      return;
    }

    setIsAddingEmployee(true);
    try {
      const response = await fetch(`/api/departments/${id}/employees`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          employeeId: selectedEmployeeId
        }),
      });

      if (response.ok) {
        const updatedEmployee = await response.json();
        toast.success(`${updatedEmployee.name} has been added to this department`);
        setIsAddEmployeeModalOpen(false);

        // Update the local state
        setMembers(prev => [...prev, updatedEmployee]);
        setAvailableEmployees(prev => prev.filter(emp => emp.id !== selectedEmployeeId));

        await loadDepartmentData(); // Reload department data
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to add employee to department');
      }
    } catch (error) {
      console.error('Failed to add employee:', error);
      toast.error('Failed to add employee to department');
    } finally {
      setIsAddingEmployee(false);
    }
  };

  const handleRemoveTeamLeadClick = (teamLead) => {
    setTeamLeadToRemove(teamLead);
    setIsRemoveTeamLeadModalOpen(true);
  };

  const handleRemoveTeamLead = async () => {
    if (!teamLeadToRemove) return;

    try {
      const response = await fetch(`/api/departments/${id}/team-leads/${teamLeadToRemove.id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        toast.success(`${teamLeadToRemove.name} has been removed as a team lead`);
        setIsRemoveTeamLeadModalOpen(false);
        setTeamLeadToRemove(null);

        // Update local state
        setTeamLeads(prev => prev.filter(lead => lead.id !== teamLeadToRemove.id));

        await loadDepartmentData(); // Reload department data
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to remove team lead');
      }
    } catch (error) {
      console.error('Failed to remove team lead:', error);
      toast.error('Failed to remove team lead');
    }
  };

  const handleRemoveMemberClick = (member) => {
    setMemberToRemove(member);
    setIsRemoveMemberModalOpen(true);
  };

  const handleRemoveMember = async () => {
    if (!memberToRemove) return;

    setIsRemovingMember(true);
    try {
      const response = await fetch(`/api/departments/${id}/employees`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          employeeId: memberToRemove.id
        }),
      });

      if (response.ok) {
        toast.success(`${memberToRemove.name} has been removed from this department`);
        setIsRemoveMemberModalOpen(false);
        setMemberToRemove(null);

        // Update local state
        setMembers(prev => prev.filter(member => member.id !== memberToRemove.id));
        setAvailableEmployees(prev => [...prev, memberToRemove]);

        await loadDepartmentData(); // Reload department data
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to remove member from department');
      }
    } catch (error) {
      console.error('Failed to remove member:', error);
      toast.error('Failed to remove member from department');
    } finally {
      setIsRemovingMember(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
