          </Card.Header>
          <Card.Content>
            <div className="space-y-4">
              <div>
                <h3 className="text-sm font-medium text-gray-500">Name</h3>
                <p className="mt-1">{department.name}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Members</h3>
                <p className="mt-1">{members.length} employee{members.length !== 1 ? 's' : ''}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Team Leads</h3>
                <p className="mt-1">{teamLeads.length} lead{teamLeads.length !== 1 ? 's' : ''}</p>
              </div>
            </div>
          </Card.Content>
        </Card>

        {/* Team Leads */}
        <Card className="lg:col-span-2">
          <Card.Header>
            <div className="flex justify-between items-center">
              <Card.Title>Team Leads</Card.Title>
