              </p>
            </div>
          )}
        </div>
      </Modal>

      {/* Remove Team Lead Modal */}
      <Modal
        isOpen={isRemoveTeamLeadModalOpen}
        onClose={() => setIsRemoveTeamLeadModalOpen(false)}
        title="Remove Team Lead"
        description="Are you sure you want to remove this team lead?"
        footer={
          <>
            {canManageDepartment && (
              <Button 
                variant="outline" 
                onClick={() => setIsRemoveTeamLeadModalOpen(false)}
              >
                Cancel
              </Button>
            )}
            {canManageDepartment && (
              <Button 
                variant="destructive" 
                onClick={handleRemoveTeamLead}
              >
                Remove Team Lead
              </Button>
            )}
          </>
        }
      >
        {teamLeadToRemove && (
          <div className="text-sm text-gray-500">
            <p>
              This will remove <span className="font-semibold text-gray-700">{teamLeadToRemove.name}</span> as a team lead for this department.
            </p>
            <p className="mt-2">
              The employee will still remain a member of the department, but will no longer have team lead privileges.
            </p>
          </div>
        )}
      </Modal>

      {/* Remove Member Modal */}
      <Modal
        isOpen={isRemoveMemberModalOpen}
        onClose={() => setIsRemoveMemberModalOpen(false)}
        title="Remove Member"
        description="Are you sure you want to remove this member from this department?"
        footer={
          <>
            {canManageDepartment && (
              <Button 
                variant="outline" 
                onClick={() => setIsRemoveMemberModalOpen(false)}
              >
                Cancel
              </Button>
            )}
            {canManageDepartment && (
              <Button 
                variant="destructive" 
                onClick={handleRemoveMember}
              >
                Remove Member
              </Button>
            )}
          </>
        }
      >
        {memberToRemove && (
          <div className="text-sm text-gray-500">
            <p>
              This will remove <span className="font-semibold text-gray-700">{memberToRemove.name}</span> from this department.
            </p>
            <p className="mt-2">
              The employee will still remain in the system, but will no longer be associated with this department.
            </p>
          </div>
        )}
      </Modal>
    </div>
  );
}

