export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getEmployees, getDepartmentById } = require('../../lib/data');

  try {
    // Get user data from cookie (basic auth check)
    const cookies = context.req.cookies;
    if (!cookies.user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    const user = JSON.parse(cookies.user);

    // If it's admin, they don't have an employee profile
    if (user.role === 'admin') {
      return {
        props: {
          isAdmin: true,
          user: user
        }
      };
    }

    // For employees, fetch their data from database
    let employee = null;
    let department = null;

    if (user.email) {
      const employees = await getEmployees();
      employee = employees.find(emp => 
        emp.email.toLowerCase() === user.email.toLowerCase()
      );

      // Check for both department_id and departmentId
      const deptId = employee?.department_id || employee?.departmentId;
      if (deptId) {
        try {
          department = await getDepartmentById(deptId);
        } catch (error) {
          // fallback below
        }
      }
      // Fallback: use department from employee object if available
      if (!department && employee?.department) {
        department = employee.department;
      }
    }

    // Serialize dates
    const serializedEmployee = employee ? {
      ...employee,
      created_at: employee.created_at ? employee.created_at.toISOString() : null,
      updated_at: employee.updated_at ? employee.updated_at.toISOString() : null
    } : null;

    const serializedDepartment = department ? {
      ...department,
      created_at: department.created_at ? department.created_at.toISOString() : null,
      updated_at: department.updated_at ? department.updated_at.toISOString() : null
    } : null;

    return {
      props: {
        user: user,
        employee: serializedEmployee,
        department: serializedDepartment,
        isAdmin: false
      }
    };
  } catch (error) {
    console.error('Error fetching profile data:', error);
    return {
      props: {
        user: null,
        employee: null,
        department: null,
        error: 'Failed to load profile data'
      }
    };
  }
}

