import { useState } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';
import { getJobRoles } from '../../lib/utils';

export default function NewEmployee({ departments }) {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    departmentIds: [],
    phoneNumber: '',
    designation: '',
    jobRole: 'employee',
    employeeNumber: '',
    joiningDate: ''
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const router = useRouter();
  const jobRoles = getJobRoles();

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Email is invalid';
    }

    if (!formData.phoneNumber.trim()) {
      newErrors.phoneNumber = 'Phone number is required';
    }

    if (!formData.designation.trim()) {
      newErrors.designation = 'Designation is required';
    }

    if (!formData.jobRole) {
      newErrors.jobRole = 'Job role is required';
    }

    if (!formData.joiningDate) {
      newErrors.joiningDate = 'Joining date is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleDepartmentToggle = (departmentId) => {
    setFormData(prev => ({
      ...prev,
      departmentIds: prev.departmentIds.includes(departmentId)
        ? prev.departmentIds.filter(id => id !== departmentId)
        : [...prev.departmentIds, departmentId]
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      // Prepare form data for submission
      const submitData = {
        ...formData,
        // Set the main department_id to the first selected department (for backward compatibility)
        departmentId: formData.departmentIds.length > 0 ? formData.departmentIds[0] : null
      };

      const response = await fetch('/api/employees', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(submitData),
      });

      if (response.ok) {
        const newEmployee = await response.json();
        toast.success(`Employee "${newEmployee.name}" has been created`);
        router.push('/employees');
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to create employee');
      }
    } catch (error) {
      console.error('Failed to create employee:', error);
      toast.error('Failed to create employee. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/employees')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Employees
        </Button>
        <h1 className="text-2xl font-bold">Add New Employee</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Full Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="John Doe"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">
                Email <span className="text-red-500">*</span>
              </Label>
              <Input
                id="email"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="john.doe@tericsoft.com"
                className={errors.email ? 'border-red-500' : ''}
              />
              {errors.email && (
                <p className="text-red-500 text-sm mt-1">{errors.email}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="phoneNumber">
                Phone Number <span className="text-red-500">*</span>
              </Label>
              <Input
                id="phoneNumber"
                name="phoneNumber"
                value={formData.phoneNumber}
                onChange={handleChange}
                placeholder="555-123-4567"
                className={errors.phoneNumber ? 'border-red-500' : ''}
              />
              {errors.phoneNumber && (
                <p className="text-red-500 text-sm mt-1">{errors.phoneNumber}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="designation">
                Designation <span className="text-red-500">*</span>
              </Label>
              <Input
                id="designation"
                name="designation"
                value={formData.designation}
                onChange={handleChange}
                placeholder="Software Engineer"
                className={errors.designation ? 'border-red-500' : ''}
              />
              {errors.designation && (
                <p className="text-red-500 text-sm mt-1">{errors.designation}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="jobRole">
                Job Role <span className="text-red-500">*</span>
              </Label>
              <Select
                id="jobRole"
                name="jobRole"
                value={formData.jobRole}
                onChange={handleChange}
                className={errors.jobRole ? 'border-red-500' : ''}
              >
                {jobRoles.map((role) => (
                  <option key={role.value} value={role.value}>
                    {role.label}
                  </option>
                ))}
              </Select>
              {errors.jobRole && (
                <p className="text-red-500 text-sm mt-1">{errors.jobRole}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="employeeNumber">
                Employee Number
              </Label>
              <Input
                id="employeeNumber"
                name="employeeNumber"
                value={formData.employeeNumber}
                onChange={handleChange}
                placeholder="e.g., EMP001, TS-2024-001 (optional)"
                className={errors.employeeNumber ? 'border-red-500' : ''}
              />
              <p className="text-sm text-gray-500">
                Employee number is optional. Admin can assign or leave empty.
              </p>
              {errors.employeeNumber && (
                <p className="text-red-500 text-sm mt-1">{errors.employeeNumber}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="joiningDate">
                Joining Date <span className="text-red-500">*</span>
              </Label>
              <Input
                id="joiningDate"
                name="joiningDate"
                type="date"
                value={formData.joiningDate}
                onChange={handleChange}
                className={errors.joiningDate ? 'border-red-500' : ''}
              />
              <p className="text-sm text-gray-500">
                Select the actual date when the employee joined the company.
              </p>
              {errors.joiningDate && (
                <p className="text-red-500 text-sm mt-1">{errors.joiningDate}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label>Departments</Label>
              <div className="border border-gray-300 rounded-md p-4 max-h-48 overflow-y-auto">
                <div className="space-y-2">
                  {Array.isArray(departments) && departments.length > 0 ? (
                    departments.map(dept => (
                      <div key={dept.id} className="flex items-center">
                        <input
                          type="checkbox"
                          id={`department-${dept.id}`}
                          checked={formData.departmentIds.includes(dept.id)}
                          onChange={() => handleDepartmentToggle(dept.id)}
                          className="mr-2 h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                        />
                        <label 
                          htmlFor={`department-${dept.id}`} 
                          className="text-sm font-medium text-gray-700 cursor-pointer"
                        >
                          {dept.name}
                        </label>
                      </div>
                    ))
                  ) : (
                    <p className="text-gray-500 text-sm">No departments available</p>
                  )}
                </div>
              </div>
              <div className="flex justify-between text-sm text-gray-500">
                <span>
                  {formData.departmentIds.length} department{formData.departmentIds.length !== 1 ? 's' : ''} selected
                </span>
                {formData.departmentIds.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, departmentIds: [] }))}
                    className="text-primary-600 hover:text-primary-800"
                  >
                    Clear selection
                  </button>
                )}
              </div>
              <p className="text-sm text-gray-500">
                Select one or more departments for this employee (optional).
              </p>
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push('/employees')}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Creating...' : 'Create Employee'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}

