export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getEmployees, 
    getDepartments,
    getDepartmentById
  } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    const [employees, departments] = await Promise.all([
      getEmployees(),
      getDepartments()
    ]);

    // Enrich employees with department data using the same logic as getEmployeeById
    const enrichedEmployees = Array.isArray(employees) ? await Promise.all(
      employees.map(async (emp) => {
        let department = null;
        let departments = [];

        try {
          // Use the same getEmployeeById logic to get complete employee data including departments
          const { getEmployeeById } = require('../../lib/data');
          const fullEmployeeData = await getEmployeeById(emp.id);

          if (fullEmployeeData) {
            departments = fullEmployeeData.departments || [];
            department = fullEmployeeData.department || null;
          }
        } catch (error) {
          console.error(`Error fetching employee data for ${emp.name}:`, error);
        }

        return {
          ...emp,
          department: department,
          departments: departments,
          created_at: emp.created_at instanceof Date ? emp.created_at.toISOString() : (emp.created_at || null),
          updated_at: emp.updated_at instanceof Date ? emp.updated_at.toISOString() : (emp.updated_at || null),
          joining_date: emp.joining_date instanceof Date ? emp.joining_date.toISOString() : (emp.joining_date || null),
        };
      })
    ) : [];

    // Serialize employees (now enriched with department data)
    const serializedEmployees = enrichedEmployees;

    const serializedDepartments = Array.isArray(departments) ? departments.map(dept => ({
      ...dept,
      created_at: dept.created_at ? dept.created_at.toISOString() : null,
      updated_at: dept.updated_at ? dept.updated_at.toISOString() : null
    })) : [];

    return {
      props: {
        initialEmployees: serializedEmployees,
        initialDepartments: serializedDepartments,
        user: user
      }
    };
  } catch (error) {
    console.error('Error fetching employees data:', error);
    return {
      props: {
        initialEmployees: [],
        initialDepartments: [],
        user: null
      }
    };
  }
}

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { FiUsers, FiUserPlus, FiPlus, FiSearch, FiFilter, FiX, FiEdit, FiTrash2, FiEye, FiChevronDown, FiChevronUp } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Card } from '../../components/Card';
import { Avatar } from '../../components/Avatar';
import { EmptyState } from '../../components/EmptyState';
import { Modal } from '../../components/Modal';
import { isAdmin } from '../../lib/auth';

export default function Employees({ initialEmployees, initialDepartments, user }) {
  const [employees, setEmployees] = useState(initialEmployees);
  const [departments, setDepartments] = useState(initialDepartments);
  const [searchQuery, setSearchQuery] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('');
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [employeeToDelete, setEmployeeToDelete] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [expandedEmployee, setExpandedEmployee] = useState(null);
  const [isAdminUser, setIsAdminUser] = useState(false);

  useEffect(() => {
    setIsAdminUser(isAdmin());
  }, []);

  const refreshData = async () => {
    try {
      // Use API routes for client-side data updates
      const [employeesRes, departmentsRes] = await Promise.all([
        fetch('/api/employees'),
        fetch('/api/departments')
      ]);

      if (employeesRes.ok && departmentsRes.ok) {
        const employeeData = await employeesRes.json();
        const departmentData = await departmentsRes.json();

        setEmployees(employeeData);
        setDepartments(departmentData);
      }
    } catch (error) {
      console.error('Failed to refresh data:', error);
    }
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const handleDepartmentFilterChange = (e) => {
    setDepartmentFilter(e.target.value);
  };

  const clearFilters = () => {
    setSearchQuery('');
    setDepartmentFilter('');
  };

  const handleDeleteClick = (employee) => {
    setEmployeeToDelete(employee);
    setIsDeleteModalOpen(true);
  };

  const handleEditClick = (employee) => {
    // Navigate to edit page
    window.location.href = `/employees/${employee.id}/edit`;
  };

  const confirmDelete = async () => {
    if (!employeeToDelete) return;

    setIsLoading(true);
    try {
      const response = await fetch(`/api/employees/${employeeToDelete.id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        toast.success(`${employeeToDelete.name} has been deleted`);
        await refreshData();
      } else {
        toast.error('Failed to delete employee');
      }
    } catch (error) {
      toast.error('An error occurred while deleting');
      console.error(error);
    } finally {
      setIsLoading(false);
      setIsDeleteModalOpen(false);
      setEmployeeToDelete(null);
    }
  };

  const toggleEmployeeDetails = (employeeId) => {
    if (expandedEmployee === employeeId) {
      setExpandedEmployee(null);
    } else {
      setExpandedEmployee(employeeId);
    }
  };

  // Filter employees based on search and department filter
  const filteredEmployees = employees.filter(emp => {
    const matchesSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          emp.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          emp.designation.toLowerCase().includes(searchQuery.toLowerCase());

    // Fix department filtering to handle department data structure
    const matchesDepartment = !departmentFilter || 
      emp.department_id === departmentFilter ||
      (emp.department && emp.department.id === departmentFilter) ||
      (emp.departments && emp.departments.some(dept => dept.id === departmentFilter));

    return matchesSearch && matchesDepartment;
  });

  const hasActiveFilters = searchQuery || departmentFilter;

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <h1 className="text-2xl font-bold">Employees</h1>
        {isAdminUser && (
          <Link href="/employees/new">
            <a>
              <Button className="w-full sm:w-auto flex items-center justify-center">
                <FiUserPlus className="mr-2" />
                Add Employee
              </Button>
            </a>
          </Link>
        )}
      </div>

      {/* Search and Filter */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="sm:col-span-2 relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
            <FiSearch />
          </div>
          <Input
            type="text"
            placeholder="Search employees by name, email, or designation..."
            value={searchQuery}
            onChange={handleSearchChange}
            className="pl-10"
          />
        </div>

        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
            <FiFilter />
          </div>
          <Select
            value={departmentFilter}
            onChange={handleDepartmentFilterChange}
            className="pl-10"
          >
            <option value="">All Departments</option>
            {departments.map(dept => (
              <option key={dept.id} value={dept.id}>
                {dept.name}
              </option>
            ))}
          </Select>
        </div>
      </div>

      {/* Filter indicator */}
      {hasActiveFilters && (
        <div className="flex items-center bg-gray-100 px-4 py-2 rounded-md">
          <span className="text-sm text-gray-600 mr-2">Filters applied:</span>
          {searchQuery && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Search: &quot;{searchQuery}&quot;
              <button 
                onClick={() => setSearchQuery('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          {departmentFilter && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Department: {departments.find(d => d.id === departmentFilter)?.name}
              <button 
                onClick={() => setDepartmentFilter('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          <button 
            onClick={clearFilters}
            className="text-xs text-gray-500 hover:text-gray-700 ml-auto"
          >
            Clear all
          </button>
        </div>
      )}

      {/* Employee List */}
      {employees.length === 0 ? (
        <EmptyState 
          title="No employees yet"
          description="Get started by adding your first employee"
          action={() => window.location.href = '/employees/new'}
        >
          <p>Click &quot;Add Employee&quot; to create a new employee record.</p>
        </EmptyState>
      ) : filteredEmployees.length === 0 ? (
        <EmptyState 
          title="No matching employees"
          description="Try different search terms or filters"
          action={clearFilters}
          actionText="Clear Filters"
        />
      ) : (
        <div className="space-y-4">
          {filteredEmployees.map((employee) => (
            <Card key={employee.id} className="overflow-hidden">
              <div 
                onClick={() => toggleEmployeeDetails(employee.id)}
                className="p-4 flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors"
              >
                <div className="flex items-center">
                  <Avatar 
                    fallback={employee.name} 
                    size="md" 
                    className="mr-4"
                  />
                  <div>
                    <h3 className="font-medium">{employee.name}</h3>
                    <p className="text-sm text-gray-600">{employee.designation}</p>
                    <p className="text-xs text-gray-500 capitalize">
                      {employee.job_role?.replace(/_/g, ' ') || 'Employee'}
                    </p>
                  </div>
                </div>
                <div className="flex items-center">
                  <span className="text-sm text-gray-500 mr-3">
                    {employee.departments && employee.departments.length > 0 
                      ? employee.departments.map(dept => dept.name).join(', ')
                      : (employee.department?.name || 'No Department')
                    }
                  </span>
                  {expandedEmployee === employee.id ? (
                    <FiChevronUp className="text-gray-400" />
                  ) : (
                    <FiChevronDown className="text-gray-400" />
                  )}
                </div>
              </div>

              {expandedEmployee === employee.id && (
                <div className="border-t border-gray-100 p-4 bg-gray-50 fade-in">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <div>
                        <p className="text-xs text-gray-500">Email</p>
                        <p className="text-sm">{employee.email}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-500">Phone</p>
                        <p className="text-sm">{employee.phoneNumber || employee.phone_number || 'Not provided'}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-500">Role</p>
                        <p className="text-sm capitalize">
                          {employee.job_role?.replace(/_/g, ' ') || 'Employee'}
                        </p>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <div>
                        <p className="text-xs text-gray-500">Department</p>
                        <p className="text-sm">
                          {employee.departments && employee.departments.length > 0 
                            ? employee.departments.map(dept => dept.name).join(', ')
                            : (employee.department?.name || 'None')
                          }
                        </p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-500">Employee Number</p>
