import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { getJobRoles } from '../../../lib/utils';

export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getEmployeeById, getDepartments } = require('../../../lib/data');

  // Define date fields directly since require() may not work properly with ES6 exports
  const EMPLOYEE_DATE_FIELDS = ['created_at', 'updated_at', 'joining_date'];
  const { id } = context.params;

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      try {
        user = JSON.parse(cookies.user);
      } catch (cookieError) {
        console.error('Error parsing user cookie:', cookieError);
        return {
          redirect: {
            destination: '/login',
            permanent: false,
          },
        };
      }
    }

    if (!user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    // Fetch employee and departments data
    let employeeData = null;
    let departmentData = [];

    try {
      [employeeData, departmentData] = await Promise.all([
        getEmployeeById(id),
        getDepartments()
      ]);
    } catch (fetchError) {
      console.error('Error fetching data:', fetchError);
      return {
        notFound: true
      };
    }

    // Check if employee exists
    if (!employeeData || employeeData === null) {
      console.log('Employee not found for ID:', id);
      return {
        notFound: true
      };
    }

    // Serialize employee data safely
    let serializedEmployee = null;
    try {
      // Custom serialization function for server-side
      const safeSerializeDate = (date) => {
        if (date instanceof Date) {
          return date.toISOString();
        }
        if (date === undefined || date === null) {
          return null;
        }
        return date;
      };

      serializedEmployee = { ...employeeData };
      EMPLOYEE_DATE_FIELDS.forEach(field => {
        if (field in serializedEmployee) {
          serializedEmployee[field] = safeSerializeDate(serializedEmployee[field]);
        }
      });

      // Ensure required fields are present
      if (!serializedEmployee || !serializedEmployee.id) {
        throw new Error('Invalid employee data structure');
      }
    } catch (serializeError) {
      console.error('Error serializing employee data:', serializeError);
      return {
        notFound: true
      };
    }

    // Serialize departments data safely
    const serializedDepartments = Array.isArray(departmentData) ? departmentData.map(dept => ({
      ...dept,
      created_at: dept.created_at ? dept.created_at.toISOString() : null,
      updated_at: dept.updated_at ? dept.updated_at.toISOString() : null
    })) : [];

    console.log('Edit page - Employee data:', {
      internalId: serializedEmployee?.id,
      employeeNumber: serializedEmployee?.employee_number,
      joiningDate: serializedEmployee?.joining_date,
      name: serializedEmployee?.name,
      departments: serializedEmployee?.departments?.length || 0
    });

    return {
      props: {
        employee: serializedEmployee,
        departments: serializedDepartments,
        user: user
      }
    };
  } catch (error) {
    console.error('Error in getServerSideProps:', error);
    return {
      notFound: true
    };
  }
}

export default function EditEmployee({ employee, departments, user }) {
  const [formData, setFormData] = useState({
    name: employee?.name || '',
    email: employee?.email || '',
    departmentIds: employee?.departments && Array.isArray(employee.departments) ? employee.departments.map(d => d.id).filter(id => id) : [],
    phoneNumber: employee?.phoneNumber || employee?.phone_number || '',
    designation: employee?.designation || '',
    jobRole: employee?.jobRole || employee?.job_role || 'employee',
    // Admin-only fields
    employeeId: employee?.employee_number || '',
    joinedDate: employee?.joining_date && employee?.joining_date !== 'null' && employee?.joining_date !== '' 
      ? employee.joining_date.split('T')[0] 
      : ''
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const router = useRouter();
  const { id } = router.query;
  const jobRoles = getJobRoles();
  const isAdmin = user?.role === 'admin';

  // Add safety check for employee prop
  if (!employee) {
    return <div>Loading employee data...</div>;
  }

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Email is invalid';
    }

    if (!formData.phoneNumber.trim()) {
      newErrors.phoneNumber = 'Phone number is required';
    }

    if (!formData.designation.trim()) {
      newErrors.designation = 'Designation is required';
    }

    if (!formData.jobRole) {
      newErrors.jobRole = 'Job role is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleDepartmentToggle = (departmentId) => {
    setFormData(prev => ({
      ...prev,
      departmentIds: prev.departmentIds.includes(departmentId)
        ? prev.departmentIds.filter(id => id !== departmentId)
        : [...prev.departmentIds, departmentId]
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const response = await fetch(`/api/employees/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        const updatedEmployee = await response.json();
        toast.success(`Employee "${updatedEmployee.name}" has been updated successfully`);
        router.push(`/employees/${id}`);
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to update employee');
      }
    } catch (error) {
      console.error('Failed to update employee:', error);
      toast.error('Failed to update employee. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push(`/employees/${id}`)}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Employee
        </Button>
        <h1 className="text-2xl font-bold">Edit Employee</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Full Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="John Doe"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">
                Email <span className="text-red-500">*</span>
              </Label>
              <Input
                id="email"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="john.doe@tericsoft.com"
                className={errors.email ? 'border-red-500' : ''}
              />
              {errors.email && (
                <p className="text-red-500 text-sm mt-1">{errors.email}</p>
              )}
            </div>

            {/* Admin-only fields */}
            {isAdmin && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="employeeId">
                    Employee Number
                  </Label>
                  <Input
                    id="employeeId"
                    name="employeeId"
                    value={formData.employeeId}
                    onChange={handleChange}
                    placeholder="EMP-001"
                    className={errors.employeeId ? 'border-red-500' : ''}
                  />
                  {errors.employeeId && (
                    <p className="text-red-500 text-sm mt-1">{errors.employeeId}</p>
                  )}
                  <p className="text-gray-500 text-sm">
                    Admin can manually update the Employee Number
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="joinedDate">
                    Joining Date
                  </Label>
                  <Input
                    id="joinedDate"
                    name="joinedDate"
                    type="date"
                    value={formData.joinedDate}
                    onChange={handleChange}
                    className={errors.joinedDate ? 'border-red-500' : ''}
                  />
                  {errors.joinedDate && (
                    <p className="text-red-500 text-sm mt-1">{errors.joinedDate}</p>
                  )}
                  <p className="text-gray-500 text-sm">
                    Admin can manually update the joining date
                  </p>
                </div>
              </>
            )}

            <div className="space-y-2">
              <Label htmlFor="phoneNumber">
                Phone Number <span className="text-red-500">*</span>
              </Label>
              <Input
                id="phoneNumber"
                name="phoneNumber"
                value={formData.phoneNumber}
                onChange={handleChange}
                placeholder="555-123-4567"
                className={errors.phoneNumber ? 'border-red-500' : ''}
              />
              {errors.phoneNumber && (
                <p className="text-red-500 text-sm mt-1">{errors.phoneNumber}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="designation">
                Designation <span className="text-red-500">*</span>
              </Label>
              <Input
                id="designation"
                name="designation"
                value={formData.designation}
                onChange={handleChange}
                placeholder="Software Engineer"
                className={errors.designation ? 'border-red-500' : ''}
              />
              {errors.designation && (
                <p className="text-red-500 text-sm mt-1">{errors.designation}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="jobRole">
                Job Role <span className="text-red-500">*</span>
              </Label>
              <Select
                id="jobRole"
                name="jobRole"
                value={formData.jobRole}
                onChange={handleChange}
                className={errors.jobRole ? 'border-red-500' : ''}
              >
                {jobRoles.map((role) => (
                  <option key={role.value} value={role.value}>
                    {role.label}
                  </option>
                ))}
              </Select>
              {errors.jobRole && (
                <p className="text-red-500 text-sm mt-1">{errors.jobRole}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label>Departments</Label>
              <div className="border border-gray-300 rounded-md p-4 max-h-48 overflow-y-auto">
                <div className="space-y-2">
                  {Array.isArray(departments) && departments.length > 0 ? (
