import { Label } from '../../components/Label';
import { getMonthsArray, getYearsArray } from '../../lib/utils';

// Chart component to display a simple bar chart
const BarChart = ({ data, title, color = 'primary' }) => {
  const maxValue = Math.max(...data.map(item => item.value));

  return (
    <div className="w-full">
      {title && <h3 className="text-sm font-medium mb-2">{title}</h3>}
      <div className="space-y-2">
        {data.map((item, index) => (
          <div key={index} className="space-y-1">
            <div className="flex justify-between text-xs">
              <span className="truncate">{item.label}</span>
              <span className="font-medium">{item.value}</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div 
                className={`bg-${color}-600 h-2 rounded-full transition-all duration-500 ease-out`}
                style={{ width: `${(item.value / maxValue) * 100}%` }}
              ></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// Donut chart component
const DonutChart = ({ data, title, colors = ['primary', 'indigo', 'green', 'amber', 'red'] }) => {
  const total = data.reduce((sum, item) => sum + item.value, 0);
  let startAngle = 0;

  return (
    <div className="flex flex-col items-center">
      {title && <h3 className="text-sm font-medium mb-2">{title}</h3>}
      <div className="relative w-48 h-48">
        <svg viewBox="0 0 100 100" className="w-full h-full">
          {data.map((item, index) => {
            const percentage = (item.value / total) * 100;
            const angle = (percentage / 100) * 360;
            const largeArcFlag = angle > 180 ? 1 : 0;

            // Convert from polar to cartesian coordinates
            const x1 = 50 + 40 * Math.cos((Math.PI * startAngle) / 180);
            const y1 = 50 + 40 * Math.sin((Math.PI * startAngle) / 180);
            const x2 = 50 + 40 * Math.cos((Math.PI * (startAngle + angle)) / 180);
            const y2 = 50 + 40 * Math.sin((Math.PI * (startAngle + angle)) / 180);

            const pathData = [
              `M 50 50`,
              `L ${x1} ${y1}`,
              `A 40 40 0 ${largeArcFlag} 1 ${x2} ${y2}`,
              `Z`
            ].join(' ');

            const segment = (
              <path
                key={index}
                d={pathData}
                fill={`var(--color-${colors[index % colors.length]}-600)`}
                stroke="#fff"
                strokeWidth="1"
              />
            );

            startAngle += angle;
            return segment;
          })}
          <circle cx="50" cy="50" r="25" fill="white" />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-xl font-bold">{total}</span>
        </div>
      </div>
      <div className="mt-4 grid grid-cols-2 gap-2 w-full">
        {data.map((item, index) => (
          <div key={index} className="flex items-center text-sm">
            <div className={`w-3 h-3 rounded-full bg-${colors[index % colors.length]}-600 mr-2`}></div>
            <span className="truncate">{item.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getEmployees, 
    getDepartments, 
    getProjects,
    getProjectAllocations
  } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    const [employees, departments, projects, allocations] = await Promise.all([
      getEmployees(),
      getDepartments(),
      getProjects(),
      getProjectAllocations()
    ]);

    // Filter data based on user role
    let filteredEmployees = employees;
    let filteredDepartments = departments;
    let userDepartment = null;

    if (user && user.role === 'team_lead') {
      // Team leads only see their department's analytics
      const teamLeadEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());
      if (teamLeadEmployee) {
        userDepartment = departments.find(dept => dept.id === teamLeadEmployee.department_id);
        filteredEmployees = employees.filter(emp => emp.department_id === teamLeadEmployee.department_id);
        filteredDepartments = userDepartment ? [userDepartment] : [];
      }
    } else if (user && user.role === 'project_manager') {
      // Project managers see analytics for their project team members
      // In a real implementation, this would filter based on project allocations
      // For now, showing analytics for all employees who could be in their projects
      filteredEmployees = employees; // Would be filtered by actual project membership
      filteredDepartments = departments; // Show all departments for broader project context
    }

    const stats = {
      totalEmployees: filteredEmployees.length,
      totalDepartments: filteredDepartments.length,
      totalProjects: projects.length,
      totalAllocations: allocations.length,
      isTeamLead: user && user.role === 'team_lead',
      isProjectManager: user && user.role === 'project_manager',
      departmentName: userDepartment?.name || null
    };

    // Department distribution (for team leads, show role distribution within their department)
    const deptData = user && user.role === 'team_lead' && userDepartment ? 
      // For team leads, show role distribution within department
      [
        { label: 'Employees', value: filteredEmployees.filter(emp => emp.job_role === 'employee').length },
        { label: 'Senior Employees', value: filteredEmployees.filter(emp => emp.job_role === 'senior_employee').length },
        { label: 'Project Managers', value: filteredEmployees.filter(emp => emp.job_role === 'project_manager').length },
        { label: 'Team Leads', value: filteredEmployees.filter(emp => emp.job_role === 'team_lead').length }
      ].filter(item => item.value > 0) :
      user && user.role === 'project_manager' ?
      // For project managers, show department distribution of their project team
      filteredDepartments.map(dept => {
        const memberCount = employees.filter(emp => emp.departmentId === dept.id || emp.department_id === dept.id).length;
        return {
          label: dept.name,
          value: memberCount
        };
      }).sort((a, b) => b.value - a.value) :
      // For admins, show department distribution
      filteredDepartments.map(dept => {
        const memberCount = employees.filter(emp => emp.departmentId === dept.id || emp.department_id === dept.id).length;
        return {
          label: dept.name,
          value: memberCount
        };
      }).sort((a, b) => b.value - a.value);

    // Project allocation data
    const projData = projects.slice(0, 5).map(proj => {
      const memberCount = filteredEmployees.filter(emp => {
        // Check if employee is allocated to this project
        return allocations.some(alloc => 
          alloc.projectId === proj.id && 
          alloc.members && 
          alloc.members.some(m => m.id === emp.id)
        );
      }).length;

      return {
        label: proj.name,
        value: memberCount
      };
    }).sort((a, b) => b.value - a.value);

    return {
      props: {
        initialStats: stats,
        initialDepartmentDistribution: deptData,
        initialProjectAllocation: projData,
        user: user,
        userDepartment: userDepartment ? {
          ...userDepartment,
          created_at: userDepartment.created_at ? userDepartment.created_at.toISOString() : null,
          updated_at: userDepartment.updated_at ? userDepartment.updated_at.toISOString() : null
        } : null
      }
    };
  } catch (error) {
    console.error('Error fetching analytics data:', error);
    return {
      props: {
        initialStats: {
          totalEmployees: 0,
          totalDepartments: 0,
          totalProjects: 0,
          totalAllocations: 0,
          isTeamLead: false,
          departmentName: null
        },
        initialDepartmentDistribution: [],
        initialProjectAllocation: [],
        user: null,
        userDepartment: null
      }
    };
  }
}

