        valid: true 
      });
    } else {
      return res.status(400).json({ 
        message: 'Invalid manual OTP. Please use 000000', 
        valid: false 
      });
    }
  }

  // Handle email OTP verification (existing logic)
  let client;
  try {
    client = await getClient();

    // Get the OTP record
    const result = await client.query(
      'SELECT * FROM otps WHERE email = $1 ORDER BY created_at DESC LIMIT 1',
      [email]
    );

    const otpRecord = result.rows[0];

    if (!otpRecord) {
      return res.status(400).json({ message: 'No OTP found for this email' });
    }

    // Check if too many attempts
    if (otpRecord.attempts >= 3) {
      return res.status(400).json({ message: 'Too many attempts. Please request a new OTP' });
    }

    // Check if OTP matches
    if (otpRecord.otp !== otp) {
      // Increment attempts
      await client.query(
        'UPDATE otps SET attempts = attempts + 1 WHERE id = $1',
        [otpRecord.id]
      );

      return res.status(400).json({ message: 'Invalid OTP' });
    }

    // OTP is valid, delete it
    await client.query('DELETE FROM otps WHERE id = $1', [otpRecord.id]);

    res.status(200).json({ message: 'OTP verified successfully', valid: true });
  } catch (error) {
    console.error('Verify OTP Error:', {
      message: error.message,
      stack: error.stack,
      code: error.code
    });
    res.status(500).json({ 
      message: 'Failed to verify OTP',
      error: error.message 
    });
  } finally {
    if (client) {
      client.release();
    }
  }
}

