      client = await getClient();

      // Delete any existing OTP for this email
      await client.query('DELETE FROM otps WHERE email = $1', [email]);

      // Save new OTP
      await client.query(
        'INSERT INTO otps (email, otp, attempts) VALUES ($1, $2, $3)',
