export default async function handler(req, res) {
  const { id } = req.query;

  if (req.method === 'GET') {
    try {
      const employee = await getEmployeeById(id);
      if (!employee) {
        return res.status(404).json({ error: 'Employee not found' });
      }

      // Serialize dates for JSON response
      const serializedEmployee = {
        ...employee,
        created_at: employee.created_at ? employee.created_at.toISOString() : null,
        updated_at: employee.updated_at ? employee.updated_at.toISOString() : null,
        joining_date: employee.joining_date ? employee.joining_date.toISOString() : null,
      };

      res.status(200).json(serializedEmployee);
    } catch (error) {
      console.error('Error fetching employee:', error);
      res.status(500).json({ error: 'Failed to fetch employee' });
    }
  } else if (req.method === 'PUT') {
    try {
      const employeeData = req.body;

      // Validate required fields
      if (!employeeData.name || !employeeData.email) {
        return res.status(400).json({ error: 'Name and email are required' });
      }

      // Check if another employee with same email already exists (excluding current employee)
      const existingEmployees = await getEmployees();
      const duplicateEmail = existingEmployees.find(emp => 
        emp.email.toLowerCase() === employeeData.email.toLowerCase() && emp.id !== id
      );

      if (duplicateEmail) {
        return res.status(400).json({ error: 'An employee with this email already exists' });
      }

      console.log('Updating employee with data:', {
        id: id,
        joiningDate: employeeData.joinedDate,
        employeeNumber: employeeData.employeeId,
        name: employeeData.name
      });

      const updatedEmployee = await updateEmployee(id, employeeData);
      if (!updatedEmployee) {
        return res.status(404).json({ error: 'Employee not found' });
      }

      // Serialize dates for JSON response
      const serializedEmployee = {
        ...updatedEmployee,
        created_at: updatedEmployee.created_at ? updatedEmployee.created_at.toISOString() : null,
        updated_at: updatedEmployee.updated_at ? updatedEmployee.updated_at.toISOString() : null,
        joining_date: updatedEmployee.joining_date ? updatedEmployee.joining_date.toISOString() : null,
      };

      console.log('Employee updated successfully:', {
        id: serializedEmployee.id,
        joining_date: serializedEmployee.joining_date,
        employee_number: serializedEmployee.employee_number
      });

      res.status(200).json(serializedEmployee);
    } catch (error) {
      console.error('Error updating employee:', error);

      // Check for PostgreSQL unique constraint violation
      if (error.code === '23505') {
        return res.status(400).json({ error: 'An employee with this email already exists' });
      }

      res.status(500).json({ error: 'Failed to update employee', details: error.message });
    }
  } else if (req.method === 'DELETE') {
    try {
      const success = await deleteEmployee(id);
      if (success) {
        res.status(200).json({ message: 'Employee deleted successfully' });
      } else {
        res.status(404).json({ error: 'Employee not found' });
      }
    } catch (error) {
      console.error('Error deleting employee:', error);
      res.status(500).json({ error: 'Failed to delete employee' });
    }
  } else {
    res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}

