// Load environment variables
require('dotenv').config({ path: '.env.local' });

import { 
  copyAllocationFromMonth,
  getProjectAllocation,
  getProjects
} from '../../../lib/data';

export default async function handler(req, res) {
  if (req.method === 'POST') {
    try {
      const { sourceMonth, sourceYear, targetMonth, targetYear } = req.body;

      // Validate required fields
      if (!sourceMonth || !sourceYear || !targetMonth || !targetYear) {
        return res.status(400).json({ error: 'Source and target month/year are required' });
      }

      // Validate that source and target aren't the same
      if (sourceMonth === targetMonth && sourceYear === targetYear) {
        return res.status(400).json({ error: 'Source and target months cannot be the same' });
      }

      // Get all projects
      const projects = await getProjects();

      if (projects.length === 0) {
        return res.status(400).json({ error: 'No projects found in the system' });
      }

      // Copy allocations for each project from source to target month/year
      const copyResults = [];
      let hasSourceAllocations = false;

      for (const project of projects) {
        try {
          // Check if source allocation exists
          const sourceAllocation = await getProjectAllocation(
            project.id,
            sourceMonth,
            sourceYear
          );

          if (sourceAllocation) {
            hasSourceAllocations = true;
            // Copy allocation to target month/year
            const result = await copyAllocationFromMonth(
              project.id,
              sourceMonth,
              sourceYear,
              targetMonth,
              targetYear
            );

            if (result) {
              copyResults.push({
                projectId: project.id,
                projectName: project.name,
                success: true,
                allocationId: result.id
              });
            } else {
              copyResults.push({
                projectId: project.id,
                projectName: project.name,
                success: false
              });
            }
          } else {
            // Add project to results even if it has no allocation in source month
            copyResults.push({
              projectId: project.id,
              projectName: project.name,
              success: false,
              noSourceAllocation: true
            });
          }
        } catch (error) {
          console.error(`Error processing project ${project.id}:`, error);
          copyResults.push({
            projectId: project.id,
            projectName: project.name,
            success: false,
            error: error.message
          });
        }
      }

      res.status(200).json({
        results: copyResults,
        hasSourceAllocations,
        successCount: copyResults.filter(r => r.success).length
      });
    } catch (error) {
      console.error('Error copying project allocations:', error);
      res.status(500).json({ error: 'Failed to copy project allocations' });
    }
  } else {
    res.setHeader('Allow', ['POST']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}

