} from '../../../lib/data';

export default async function handler(req, res) {
  const { method } = req;

  try {
    switch (method) {
      case 'GET':
        await handleGet(req, res);
        break;
      case 'POST':
        await handlePost(req, res);
        break;
      default:
        res.setHeader('Allow', ['GET', 'POST']);
        res.status(405).json({ error: `Method ${method} Not Allowed` });
    }
  } catch (error) {
    console.error('Project allocation API error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}

async function handleGet(req, res) {
  const { month, year } = req.query;

  if (month && year) {
    // Get allocations for specific month/year
    const allocations = await getProjectAllocations();
    const filtered = allocations.filter(alloc => 
      alloc.month === month && alloc.year === year
    );

    // Enhance with project and member info
    const enhanced = filtered.map(alloc => ({
      ...alloc,
      project_name: alloc.project?.name || 'Unknown Project',
      manager_name: alloc.project_manager?.name || 'Unassigned',
      member_count: alloc.members?.length || 0
    }));

    res.status(200).json(enhanced);
  } else {
    // Get all allocations
    const allocations = await getProjectAllocations();
    res.status(200).json(allocations);
  }
}

async function handlePost(req, res) {
  const { projectId, month, year, projectManagerId, members } = req.body;

  if (!projectId || !month || !year) {
    return res.status(400).json({ error: 'Project ID, month, and year are required' });
  }

  try {
    // Check if allocation already exists
    const existing = await getProjectAllocation(projectId, month, year);
    if (existing) {
      return res.status(409).json({ error: 'Allocation already exists for this project in the specified month/year' });
    }

    // Create allocation
    const allocationData = {
      projectId,
      month,
      year,
      projectManagerId: projectManagerId || null
    };

    const allocation = await addProjectAllocation(allocationData);

    // Add members if provided
    if (members && Array.isArray(members)) {
      for (const member of members) {
        try {
          const memberId = typeof member === 'object' ? member.id : member;
          await addAllocationMember(allocation.id, memberId);
        } catch (memberError) {
          console.warn(`Failed to add member ${member} to allocation:`, memberError);
        }
      }
    }

    res.status(201).json(allocation);
  } catch (error) {
    console.error('Error creating allocation:', error);
    res.status(500).json({ error: 'Failed to create allocation: ' + error.message });
  }
}

