import { 
  getProjectAllocation, 
  getAllocationMembers,
  addAllocationMember,
  removeAllocationMember
} from '../../../../lib/data';

export default async function handler(req, res) {
  const { method } = req;
  const { id } = req.query;

  try {
    switch (method) {
      case 'GET':
        await handleGet(req, res, id);
        break;
      case 'PUT':
        await handlePut(req, res, id);
        break;
      default:
        res.setHeader('Allow', ['GET', 'PUT']);
        res.status(405).json({ error: `Method ${method} Not Allowed` });
    }
  } catch (error) {
    console.error('Allocation members API error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}

async function handleGet(req, res, projectId) {
  const { month, year } = req.query;

  if (!month || !year) {
    return res.status(400).json({ error: 'Month and year are required' });
  }

  try {
    const allocation = await getProjectAllocation(projectId, month, year);
    if (!allocation) {
      return res.status(404).json({ error: 'Allocation not found' });
    }

    const members = await getAllocationMembers(allocation.id);
    res.status(200).json(members);
  } catch (error) {
    console.error('Error fetching allocation members:', error);
    res.status(500).json({ error: 'Failed to fetch allocation members' });
  }
}

async function handlePut(req, res, projectId) {
  const { month, year, members } = req.body;

  if (!month || !year || !Array.isArray(members)) {
    return res.status(400).json({ error: 'Month, year, and members array are required' });
  }

  try {
    const allocation = await getProjectAllocation(projectId, month, year);
    if (!allocation) {
      return res.status(404).json({ error: 'Allocation not found' });
    }

    // Get current members
    const currentMembers = await getAllocationMembers(allocation.id);
    const currentMemberIds = currentMembers.map(m => m.id);

    // Remove members that are not in the new list
    for (const currentMemberId of currentMemberIds) {
      if (!members.includes(currentMemberId)) {
        await removeAllocationMember(allocation.id, currentMemberId);
      }
    }

    // Add members that are not in the current list
    for (const memberId of members) {
      if (!currentMemberIds.includes(memberId)) {
        await addAllocationMember(allocation.id, memberId);
      }
    }

    // Get updated members list
    const updatedMembers = await getAllocationMembers(allocation.id);
    res.status(200).json(updatedMembers);
  } catch (error) {
    console.error('Error updating allocation members:', error);
    res.status(500).json({ error: 'Failed to update allocation members' });
  }
}

