import { addFormSubmission, getFormById, getFormSubmissions } from '../../../lib/data';

export default async function handler(req, res) {
  if (req.method === 'POST') {
    try {
      const submissionData = req.body;

      // Validate required fields
      if (!submissionData.form_id || !submissionData.user_email) {
        return res.status(400).json({ 
          message: 'Form ID and user email are required' 
        });
      }

      // Validate new required fields
      if (!submissionData.filled_by_id || !submissionData.filled_for_id) {
        return res.status(400).json({ 
          message: 'Filled by and filled for information are required' 
        });
      }

      // Check for duplicate submission prevention
      // Get existing submissions to check for duplicates
      const existingSubmissions = await getFormSubmissions();
      const duplicateSubmission = existingSubmissions.find(submission => 
        submission.form_id === submissionData.form_id &&
        submission.filled_by_id === submissionData.filled_by_id &&
        submission.filled_for_id === submissionData.filled_for_id &&
        submission.submission_month === submissionData.submission_month &&
        submission.submission_year === submissionData.submission_year
      );

      if (duplicateSubmission) {
        return res.status(400).json({ 
          message: 'You have already submitted this form for this person in this month. Each form can only be submitted once per month per person.',
          existingSubmissionId: duplicateSubmission.id
        });
      }

      // Get form details to check if it allows multiple submissions
      const form = await getFormById(submissionData.form_id);
      if (form && form.frequency === 'once') {
        // For one-time forms, check if any submission exists regardless of month
        const oneTimeSubmission = existingSubmissions.find(submission => 
          submission.form_id === submissionData.form_id &&
          submission.filled_by_id === submissionData.filled_by_id &&
          submission.filled_for_id === submissionData.filled_for_id
        );

        if (oneTimeSubmission) {
          return res.status(400).json({ 
            message: 'This form can only be submitted once. You have already submitted this form for this person.',
            existingSubmissionId: oneTimeSubmission.id
          });
        }
      }

      // Calculate next due date for recurring forms
      let nextDueDate = null;
      if (submissionData.form_frequency && submissionData.form_frequency !== 'once') {
        const currentDate = new Date();
        switch (submissionData.form_frequency) {
          case 'monthly':
            nextDueDate = new Date(currentDate);
            nextDueDate.setMonth(currentDate.getMonth() + 1);
            break;
          case 'weekly':
            nextDueDate = new Date(currentDate);
            nextDueDate.setDate(currentDate.getDate() + 7);
            break;
          case 'quarterly':
            nextDueDate = new Date(currentDate);
            nextDueDate.setMonth(currentDate.getMonth() + 3);
            break;
          case 'yearly':
            nextDueDate = new Date(currentDate);
            nextDueDate.setFullYear(currentDate.getFullYear() + 1);
            break;
        }
      }

      // Ensure status is explicitly set to 'completed'
      const submissionPayload = {
        form_id: submissionData.form_id,
        user_id: submissionData.user_id,
        user_email: submissionData.user_email,
        employee_id: submissionData.employee_id,
        employee_name: submissionData.employee_name,
        department_id: submissionData.department_id,
        department_name: submissionData.department_name,
        status: 'completed', // Explicitly set to completed
        total_score: submissionData.total_score,
        max_possible_score: submissionData.max_possible_score,
        submission_month: submissionData.submission_month,
        submission_year: submissionData.submission_year,
        answers: submissionData.answers,
        // New fields
        filled_by_id: submissionData.filled_by_id,
        filled_by_email: submissionData.filled_by_email,
        filled_by_name: submissionData.filled_by_name,
        filled_for_id: submissionData.filled_for_id,
        filled_for_email: submissionData.filled_for_email,
        filled_for_name: submissionData.filled_for_name,
        next_due_date: nextDueDate,
        is_due: false
      };

      console.log('Submitting form with payload:', JSON.stringify(submissionPayload, null, 2));

      // Add the submission to database
      const newSubmission = await addFormSubmission(submissionPayload);

      console.log('Form submission created:', JSON.stringify(newSubmission, null, 2));

      res.status(201).json(newSubmission);
    } catch (error) {
      console.error('Error submitting form:', error);
      res.status(500).json({ 
        message: 'Failed to submit form',
        error: error.message 
      });
    }
  } else {
    res.setHeader('Allow', ['POST']);
    res.status(405).json({ message: 'Method not allowed' });
  }
}

