import { getProjects, getForms, getEmployees, getProjectAllocations, getProjectMembers, getFormSubmissions } from '../../../lib/data';

export default async function handler(req, res) {
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({ message: 'Method not allowed' });
  }

  try {
    // Get user data from cookies
    const cookies = req.headers.cookie;
    let user = null;

    if (cookies) {
      const cookieObj = cookies.split(';').reduce((acc, cookie) => {
        const [key, value] = cookie.trim().split('=');
        acc[key] = value;
        return acc;
      }, {});

      if (cookieObj.user) {
        user = JSON.parse(decodeURIComponent(cookieObj.user));
      }
    }

    if (!user || !(user.isEmployee || user.role === 'employee' || user.role === 'project_manager')) {
      return res.status(403).json({ message: 'Access denied. Employee or Project Manager access required.' });
    }

    // Get all data including form submissions
    const [projects, forms, employees, projectAllocations, formSubmissions] = await Promise.all([
      getProjects(),
      getForms(),
      getEmployees(),
      getProjectAllocations().catch(() => []),
      getFormSubmissions().catch(() => [])
    ]);

    // Find the user's employee record
    const userEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());

    if (!userEmployee) {
      return res.status(404).json({ message: 'Employee record not found' });
    }

    // Get user's projects - check both allocations and memberships
    const assignedProjectIds = new Set();

    // Check project allocations
    try {
      const userAllocations = projectAllocations.filter(allocation => allocation.employee_id === userEmployee.id);
      userAllocations.forEach(allocation => assignedProjectIds.add(allocation.project_id));
    } catch (error) {
      console.error('Error fetching project allocations for dashboard API:', error);
    }

    // Check project members for each project
    for (const project of projects) {
      try {
        const members = await getProjectMembers(project.id);
        const isMember = members.some(member => 
          member.id === userEmployee.id || 
          member.employee_id === userEmployee.id
        );
        if (isMember) {
          assignedProjectIds.add(project.id);
        }
      } catch (error) {
        console.error(`Error checking membership for project ${project.id} in dashboard API:`, error);
      }
    }

    // For project managers, also check if they manage any projects
    if (user.role === 'project_manager') {
      const managedProjects = projects.filter(project => 
        project.manager_id === user.id || 
        project.project_manager_id === user.id ||
        project.assigned_pm === user.email
      );
      managedProjects.forEach(project => assignedProjectIds.add(project.id));
    }

    const userProjects = projects.filter(project => assignedProjectIds.has(project.id));

    // Get employee's forms (only those they haven't completed)
    const userSubmissions = formSubmissions.filter(submission => 
      submission.user_email?.toLowerCase() === user.email?.toLowerCase() ||
      submission.filled_by_email?.toLowerCase() === user.email?.toLowerCase()
    );

    const completedFormIds = new Set(
      userSubmissions
        .filter(sub => sub.status === 'completed')
        .map(sub => sub.form_id)
    );

    const employeeForms = forms.filter(form => {
      // Skip if already completed
      if (completedFormIds.has(form.id)) return false;

      if (form.status !== 'published') return false;
      switch (form.audience) {
        case 'all':
          return true;
        case 'employee':
          return user.isEmployee || user.role === 'employee';
        case 'project_manager':
          return user.role === 'project_manager';
        case 'team_lead':
          return user.role === 'team_lead';
        case 'co_founders':
          return user.role === 'co_founder';
        case 'employee_to_pm':
          return user.isEmployee || user.role === 'employee' || user.role === 'project_manager';
        case 'pm_to_employee':
          return user.role === 'project_manager' || user.isEmployee || user.role === 'employee';
        default:
          return false;
      }
    });

    // Serialize dates
    const serializedProjects = userProjects.map(project => ({
      ...project,
      created_at: project.created_at ? project.created_at.toISOString() : null,
      updated_at: project.updated_at ? project.updated_at.toISOString() : null,
      start_date: project.start_date ? project.start_date.toISOString() : null,
      end_date: project.end_date ? project.end_date.toISOString() : null,
      due_date: project.due_date ? project.due_date.toISOString() : null
    }));

    const serializedForms = employeeForms.map(form => ({
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null,
      due_date: form.due_date ? form.due_date.toISOString() : null,
      start_date: form.start_date ? form.start_date.toISOString() : null,
      end_date: form.end_date ? form.end_date.toISOString() : null
    }));

    console.log(`Dashboard API: Found ${userProjects.length} projects and ${employeeForms.length} pending forms for employee ${userEmployee.name}`);

    res.status(200).json({
      projects: serializedProjects,
      forms: serializedForms,
      projectCount: userProjects.length,
      formCount: employeeForms.length,
      completedFormsCount: completedFormIds.size,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Error fetching employee dashboard data:', error);
    res.status(500).json({ 
      message: 'Failed to fetch dashboard data',
      error: error.message 
    });
  }
}

