import { useState } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';
import { getMonthsArray, getYearsArray } from '../../lib/utils';

export default function NewProject({ projectManagers }) {
  const [formData, setFormData] = useState({
    name: '',
    startMonth: new Date().getMonth() + 1 < 10 
      ? `0${new Date().getMonth() + 1}` 
      : `${new Date().getMonth() + 1}`,
    startYear: new Date().getFullYear().toString(),
    status: 'active',
    projectManagerId: ''
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const router = useRouter();
  const months = getMonthsArray();
  const years = getYearsArray();

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Project name is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const response = await fetch('/api/projects', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        const newProject = await response.json();
        toast.success(`Project "${newProject.name}" has been created`);
        router.push('/projects');
      } else {
        const error = await response.json();
        throw new Error(error.message || 'Failed to create project');
      }
    } catch (error) {
      console.error('Failed to create project:', error);
      toast.error('Failed to create project');
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/projects')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Projects
        </Button>
        <h1 className="text-2xl font-bold">Create New Project</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Project Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="e.g. Website Redesign, Mobile App Development"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="startMonth">
                  Start Month <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="startMonth"
                  name="startMonth"
                  value={formData.startMonth}
                  onChange={handleChange}
                >
                  {months.map(month => (
                    <option key={month.value} value={month.value}>
                      {month.label}
                    </option>
                  ))}
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="startYear">
                  Start Year <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="startYear"
                  name="startYear"
                  value={formData.startYear}
                  onChange={handleChange}
                >
                  {years.map(year => (
                    <option key={year.value} value={year.value}>
                      {year.label}
                    </option>
                  ))}
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="projectManagerId">Project Manager</Label>
              <Select
                id="projectManagerId"
                name="projectManagerId"
                value={formData.projectManagerId}
                onChange={handleChange}
              >
                <option value="">-- Select Project Manager (Optional) --</option>
                {projectManagers.map(pm => (
                  <option key={pm.id} value={pm.id}>
                    {pm.name} - {pm.designation}
                  </option>
                ))}
              </Select>
              {projectManagers.length === 0 && (
                <p className="text-amber-600 text-sm mt-1">
                  No project managers available. You can assign employees with the &quot;Project Manager (PM)&quot; job role.
                </p>
              )}
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push('/projects')}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Creating...' : 'Create Project'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}

