import { useState, useEffect } from 'react';
import Link from 'next/link';
import { FiPlusCircle, FiSearch, FiFilter, FiX, FiCalendar, FiUsers, FiBriefcase, FiEye, FiEdit, FiTrash2, FiChevronDown, FiChevronRight, FiUserPlus } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { ProjectCard } from '../../components/ProjectCard';
import { EmptyState } from '../../components/EmptyState';
import { Modal } from '../../components/Modal';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';
import { Avatar } from '../../components/Avatar';
import { getMonthsArray, getYearsArray } from '../../lib/utils';
import { useRouter } from 'next/router';
import { isAdmin } from '../../lib/auth';

export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getProjects, 
    getProjectManagers,
    getEmployees,
    getProjectAllocations,  // Add this to get project allocations
    getProjectMembers      // Add this to get project members for each project
  } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    // Check if this is "my projects" view for employees
    const isMyProjectsView = context.query.my === 'true';

    const [projects, projectManagers, employees, projectAllocations] = await Promise.all([
      getProjects(),
      getProjectManagers(),
      getEmployees(),
      getProjectAllocations().catch(() => []) // Fallback if function doesn't exist yet
    ]);

    let filteredProjects = projects;

    // Filter projects based on user role and project assignments
    if (user && user.role !== 'admin') {
      if (user.role === 'project_manager') {
        // Project managers see projects they manage
        filteredProjects = projects.filter(project => 
          project.manager_id === user.id || 
          project.project_manager_id === user.id ||
          project.assigned_pm === user.email
        );
      } else if (user.isEmployee || user.role === 'employee') {
        // Regular employees see projects they are allocated to OR are members of
        const userEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());
        if (userEmployee) {
          const assignedProjectIds = new Set();

          // Check project allocations
          try {
            const userAllocations = projectAllocations.filter(allocation => allocation.employee_id === userEmployee.id);
            userAllocations.forEach(allocation => assignedProjectIds.add(allocation.project_id));
          } catch (error) {
            console.error('Error fetching project allocations:', error);
          }

          // Check project members for each project
          for (const project of projects) {
            try {
              const { getProjectMembers } = require('../../lib/data');
              const members = await getProjectMembers(project.id);
              const isMember = members.some(member => 
                member.id === userEmployee.id || 
                member.employee_id === userEmployee.id
              );
              if (isMember) {
                assignedProjectIds.add(project.id);
              }
            } catch (error) {
              console.error(`Error checking membership for project ${project.id}:`, error);
            }
          }

          filteredProjects = projects.filter(project => assignedProjectIds.has(project.id));
        } else {
          filteredProjects = []; // No employee record found
        }
      }
    }
    // Admin users see all projects (no filtering needed)

    // Serialize dates
    const serializedProjects = Array.isArray(filteredProjects) ? filteredProjects.map(project => ({
      ...project,
      created_at: project.created_at instanceof Date ? project.created_at.toISOString() : (project.created_at || null),
      updated_at: project.updated_at instanceof Date ? project.updated_at.toISOString() : (project.updated_at || null),
      start_date: project.start_date instanceof Date ? project.start_date.toISOString() : (project.start_date || null),
      end_date: project.end_date instanceof Date ? project.end_date.toISOString() : (project.end_date || null),
      due_date: project.due_date instanceof Date ? project.due_date.toISOString() : (project.due_date || null)
    })) : [];

    const serializedProjectManagers = Array.isArray(projectManagers) ? projectManagers.map(pm => ({
      ...pm,
      created_at: pm.created_at instanceof Date ? pm.created_at.toISOString() : (pm.created_at || null),
      updated_at: pm.updated_at instanceof Date ? pm.updated_at.toISOString() : (pm.updated_at || null)
    })) : [];

    const serializedEmployees = Array.isArray(employees) ? employees.map(emp => ({
      ...emp,
      created_at: emp.created_at instanceof Date ? emp.created_at.toISOString() : (emp.created_at || null),
      updated_at: emp.updated_at instanceof Date ? emp.updated_at.toISOString() : (emp.updated_at || null)
    })) : [];

    return {
      props: {
        initialProjects: serializedProjects,
        initialProjectManagers: serializedProjectManagers,
        initialEmployees: serializedEmployees,
        user: user,
        isMyProjectsView: isMyProjectsView
      }
    };
  } catch (error) {
    console.error('Error fetching projects data:', error);
    return {
      props: {
        initialProjects: [],
        initialProjectManagers: [],
        initialEmployees: [],
        user: null,
        isMyProjectsView: false
      }
    };
  }
}

export default function Projects({ initialProjects, initialProjectManagers, initialEmployees, user, isMyProjectsView }) {
