    // Group projects by their start month within the selected year
    const projectsGroupedByMonth = {};
    const monthsWithProjects = new Set();

    for (const project of projects) {
      // Use start_month and start_year from project data, or fall back to created_at
      let projectYear, projectMonth;

      if (project.start_year && project.start_month) {
        projectYear = parseInt(project.start_year);
        // Keep month as string with leading zero to match getMonthsArray format
        projectMonth = project.start_month.toString().padStart(2, '0');
      } else if (project.start_date) {
        const startDate = new Date(project.start_date);
        projectYear = startDate.getFullYear();
        projectMonth = (startDate.getMonth() + 1).toString().padStart(2, '0');
      } else if (project.created_at) {
        const createdDate = new Date(project.created_at);
        projectYear = createdDate.getFullYear();
        projectMonth = (createdDate.getMonth() + 1).toString().padStart(2, '0');
      } else {
        continue; // Skip if no date information
      }

      if (projectYear === parseInt(selectedYear)) {
        monthsWithProjects.add(projectMonth);

        if (!projectsGroupedByMonth[projectMonth]) {
          projectsGroupedByMonth[projectMonth] = [];
        }

        // Add manager info to project
        const manager = employees.find(emp => 
          emp.id === project.manager_id || 
          emp.id === project.project_manager_id || 
          emp.email === project.assigned_pm
        ) || { name: 'PM not allocated', email: '' };

        // Don't load member count here - load it on demand instead
        projectsGroupedByMonth[projectMonth].push({
          ...project,
          manager: manager,
          memberCount: 0 // Default to 0, will be loaded on demand
        });
      }
    }

    setProjectsByMonth(projectsGroupedByMonth);
  };

  const loadProjectsForMonth = () => {
    // This function can be used to load detailed project data for a specific month
    // For now, the data is already loaded in loadProjectsByYear
  };

  const loadProjectMemberCounts = async () => {
    // This function is no longer needed as we load counts in loadProjectsByYear
  };

  const refreshProjects = async () => {
    try {
      const url = isMyProjectsView ? '/api/projects?my=true' : '/api/projects';
      const response = await fetch(url);
      if (response.ok) {
        const projectData = await response.json();
        setProjects(projectData);
      }
    } catch (error) {
      console.error('Failed to refresh projects:', error);
    }
  };

  const handleYearChange = (e) => {
    setSelectedYear(e.target.value);
    setSelectedMonth('');
  };

  const handleMonthSelect = (month) => {
