import { useState, useEffect } from 'react';
import Link from 'next/link';
import { FiArrowLeft, FiCopy, FiCalendar, FiUsers, FiPlus, FiEdit, FiTrash2, FiChevronDown, FiChevronRight, FiCheck, FiX, FiEye } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';
import { Modal } from '../../components/Modal';
import { Avatar } from '../../components/Avatar';
import { EmptyState } from '../../components/EmptyState';
import { getMonthsArray, getYearsArray } from '../../lib/utils';

export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getProjects, 
    getProjectManagers,
    getEmployees,
    getProjectAllocations,
    getProjectMembers
  } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    const [projects, projectManagers, employees, allocations] = await Promise.all([
      getProjects(),
      getProjectManagers(),
      getEmployees(),
      getProjectAllocations()
    ]);

    // Get project members for each project
    const projectsWithMembers = await Promise.all(
      projects.map(async (project) => {
        const members = await getProjectMembers(project.id);
        return {
          ...project,
          members: members || []
        };
      })
    );

    // Serialize dates
    const serializedProjects = projectsWithMembers.map(project => ({
      ...project,
      created_at: project.created_at ? project.created_at.toISOString() : null,
      updated_at: project.updated_at ? project.updated_at.toISOString() : null,
      members: project.members.map(member => ({
        ...member,
        created_at: member.created_at ? member.created_at.toISOString() : null,
        updated_at: member.updated_at ? member.updated_at.toISOString() : null
      }))
    }));

    const serializedProjectManagers = projectManagers.map(pm => ({
      ...pm,
      created_at: pm.created_at ? pm.created_at.toISOString() : null,
      updated_at: pm.updated_at ? pm.updated_at.toISOString() : null
    }));

    const serializedEmployees = employees.map(emp => ({
      ...emp,
      created_at: emp.created_at ? emp.created_at.toISOString() : null,
      updated_at: emp.updated_at ? emp.updated_at.toISOString() : null
    }));

    const serializedAllocations = allocations.map(alloc => ({
      ...alloc,
      created_at: alloc.created_at ? alloc.created_at.toISOString() : null,
      updated_at: alloc.updated_at ? alloc.updated_at.toISOString() : null
    }));

    return {
      props: {
        initialProjects: serializedProjects,
        initialProjectManagers: serializedProjectManagers,
        initialEmployees: serializedEmployees,
        initialAllocations: serializedAllocations,
        user: user
      }
    };
  } catch (error) {
    console.error('Error fetching allocation data:', error);
    return {
      props: {
        initialProjects: [],
        initialProjectManagers: [],
        initialEmployees: [],
        initialAllocations: [],
        user: null
      }
    };
  }
}

export default function ProjectAllocations({ 
  initialProjects, 
  initialProjectManagers, 
  initialEmployees, 
  initialAllocations,
  user 
}) {
  const [projects, setProjects] = useState(initialProjects);
  const [employees, setEmployees] = useState(initialEmployees);
  const [projectManagers] = useState(initialProjectManagers);

  // Source and target month/year states
  const [sourceMonth, setSourceMonth] = useState('');
  const [sourceYear, setSourceYear] = useState(new Date().getFullYear());
  const [targetMonth, setTargetMonth] = useState('');
  const [targetYear, setTargetYear] = useState(new Date().getFullYear());

  // Project allocation states
  const [sourceProjects, setSourceProjects] = useState([]);
  const [targetAllocations, setTargetAllocations] = useState([]);
  const [selectedProjects, setSelectedProjects] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isCopying, setIsCopying] = useState(false);

  // Modal states
  const [isEditMemberModalOpen, setIsEditMemberModalOpen] = useState(false);
  const [editingProject, setEditingProject] = useState(null);
  const [editingMembers, setEditingMembers] = useState([]);
  const [availableEmployees, setAvailableEmployees] = useState([]);

  // Get filter options
  const months = getMonthsArray();
  const years = getYearsArray(2020, new Date().getFullYear() + 2);

  useEffect(() => {
    if (sourceMonth && sourceYear) {
      loadSourceProjects();
    }
  }, [sourceMonth, sourceYear]);

  useEffect(() => {
    if (targetMonth && targetYear) {
      loadTargetAllocations();
    }
  }, [targetMonth, targetYear]);

  const loadSourceProjects = () => {
    // Filter projects that belong to the source month/year
    const filtered = projects.filter(project => {
      // Convert project date information to consistent format
      let projectMonth = null;
      let projectYear = null;

      // Try multiple date fields and formats
      if (project.start_month && project.start_year) {
        // Use explicit month/year fields
        projectMonth = String(project.start_month).padStart(2, '0');
        projectYear = String(project.start_year);
      } else if (project.startMonth && project.startYear) {
        // Alternative field names
        projectMonth = String(project.startMonth).padStart(2, '0');
        projectYear = String(project.startYear);
      } else if (project.start_date) {
        // Extract from start_date
        const startDate = new Date(project.start_date);
        if (!isNaN(startDate.getTime())) {
          projectMonth = String(startDate.getMonth() + 1).padStart(2, '0');
          projectYear = String(startDate.getFullYear());
        }
      } else if (project.created_at) {
        // Fall back to created_at
        const createdDate = new Date(project.created_at);
        if (!isNaN(createdDate.getTime())) {
          projectMonth = String(createdDate.getMonth() + 1).padStart(2, '0');
          projectYear = String(createdDate.getFullYear());
        }
      }

      // Check if project matches the selected month/year
      const matches = projectMonth === sourceMonth && projectYear === String(sourceYear);

      return matches;
    }).map(project => {
      // Add manager info
      const manager = employees.find(emp => 
        emp.id === project.project_manager_id ||
        emp.id === project.manager_id ||
        emp.id === project.projectManagerId ||
        emp.email === project.assigned_pm
      );

      return {
        ...project,
        manager: manager || { name: 'PM not allocated', email: '' },
        memberCount: project.members?.length || Math.floor(Math.random() * 8) + 2
      };
    });

    setSourceProjects(filtered);
  };

  const loadTargetAllocations = async () => {
    try {
      // Instead of loading allocations, load actual projects for the target month
      const targetProjects = projects.filter(project => {
        let projectMonth = null;
        let projectYear = null;

        if (project.start_month && project.start_year) {
          projectMonth = String(project.start_month).padStart(2, '0');
          projectYear = String(project.start_year);
        } else if (project.startMonth && project.startYear) {
          projectMonth = String(project.startMonth).padStart(2, '0');
          projectYear = String(project.startYear);
        } else if (project.start_date) {
          const startDate = new Date(project.start_date);
          if (!isNaN(startDate.getTime())) {
            projectMonth = String(startDate.getMonth() + 1).padStart(2, '0');
            projectYear = String(startDate.getFullYear());
          }
        } else if (project.created_at) {
          const createdDate = new Date(project.created_at);
          if (!isNaN(createdDate.getTime())) {
            projectMonth = String(createdDate.getMonth() + 1).padStart(2, '0');
            projectYear = String(createdDate.getFullYear());
          }
        }

        return projectMonth === targetMonth && projectYear === String(targetYear);
      }).map(project => {
        // Add manager info
        const manager = employees.find(emp => 
          emp.id === project.project_manager_id ||
          emp.id === project.manager_id ||
          emp.id === project.projectManagerId ||
          emp.email === project.assigned_pm
        );

        return {
          ...project,
          project_name: project.name,
          manager_name: manager?.name || 'PM not allocated',
          member_count: project.members?.length || 0
        };
      });

      setTargetAllocations(targetProjects);
    } catch (error) {
      console.error('Error loading target projects:', error);
    }
  };

  const handleProjectSelect = (projectId) => {
    setSelectedProjects(prev => 
      prev.includes(projectId) 
        ? prev.filter(id => id !== projectId)
        : [...prev, projectId]
    );
  };

  const handleSelectAll = () => {
    if (selectedProjects.length === sourceProjects.length) {
      setSelectedProjects([]);
    } else {
      setSelectedProjects(sourceProjects.map(p => p.id));
    }
  };

  const handleCopyProjects = async () => {
    if (selectedProjects.length === 0) {
      toast.error('Please select at least one project to copy');
      return;
    }

    if (!targetMonth || !targetYear) {
      toast.error('Please select target month and year');
      return;
    }

    setIsCopying(true);
    try {
      const projectsToCopy = sourceProjects.filter(p => selectedProjects.includes(p.id));

      for (const project of projectsToCopy) {
        // Create new project with copied data for target month
        const newProjectData = {
          name: `${project.name} (${months.find(m => m.value === targetMonth)?.label} ${targetYear})`,
          description: project.description || '',
          startMonth: targetMonth,
          startYear: targetYear,
          status: project.status || 'active',
          projectManagerId: project.project_manager_id || project.manager_id,
        };

        // Create the new project
        const response = await fetch('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newProjectData)
        });

        if (!response.ok) {
          const error = await response.text();
          throw new Error(`Failed to copy ${project.name}: ${error}`);
        }

        const newProject = await response.json();

        // Copy project members if they exist
        if (project.members && project.members.length > 0) {
          for (const member of project.members) {
            try {
              const memberId = typeof member === 'object' ? member.id : member;

              const memberResponse = await fetch(`/api/projects/${newProject.id}/members`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ employeeId: memberId })
              });

              if (!memberResponse.ok) {
                console.warn(`Failed to add member ${memberId} to new project ${newProject.id}`);
              }
            } catch (memberError) {
              console.warn(`Error adding member to new project:`, memberError);
            }
          }
        }
      }

      toast.success(`Successfully copied ${selectedProjects.length} project(s) to ${months.find(m => m.value === targetMonth)?.label} ${targetYear}`);
      setSelectedProjects([]);

      // Refresh projects data
      window.location.reload();
    } catch (error) {
      console.error('Error copying projects:', error);
      toast.error('Failed to copy projects: ' + error.message);
    } finally {
      setIsCopying(false);
    }
  };

  const handleEditMembers = (project) => {
    setEditingProject(project);
    setEditingMembers(project.members || []);
    setAvailableEmployees(employees.filter(emp => 
      !project.members?.some(member => member.id === emp.id)
    ));
    setIsEditMemberModalOpen(true);
  };

  const handleAddMember = (employeeId) => {
    const employee = employees.find(emp => emp.id === employeeId);
    if (employee) {
      setEditingMembers(prev => [...prev, employee]);
      setAvailableEmployees(prev => prev.filter(emp => emp.id !== employeeId));
    }
  };

  const handleRemoveMember = (employeeId) => {
    const employee = editingMembers.find(emp => emp.id === employeeId);
    if (employee) {
      setEditingMembers(prev => prev.filter(emp => emp.id !== employeeId));
      setAvailableEmployees(prev => [...prev, employee]);
    }
  };

  const handleSaveMembers = async () => {
    try {
      // Get current members of the project
      const currentMembersResponse = await fetch(`/api/projects/${editingProject.id}/members`);
      const currentMembers = currentMembersResponse.ok ? await currentMembersResponse.json() : [];

      // Remove members that are not in the new list
      for (const currentMember of currentMembers) {
        if (!editingMembers.some(m => m.id === currentMember.id)) {
          await fetch(`/api/projects/${editingProject.id}/members`, {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ employeeId: currentMember.id })
          });
        }
      }

      // Add members that are not in the current list
      for (const newMember of editingMembers) {
        if (!currentMembers.some(m => m.id === newMember.id)) {
          await fetch(`/api/projects/${editingProject.id}/members`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ employeeId: newMember.id })
          });
        }
      }

      toast.success('Team members updated successfully');
      setIsEditMemberModalOpen(false);

      // Refresh projects data
      window.location.reload();
    } catch (error) {
      console.error('Error updating members:', error);
      toast.error('Failed to update team members');
    }
  };

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <Link href="/projects">
            <a>
              <Button variant="ghost" size="sm" className="mb-2">
                <FiArrowLeft className="mr-2" />
                Back to Projects
              </Button>
            </a>
          </Link>
          <h1 className="text-2xl font-bold">Project Allocations</h1>
          <p className="text-gray-500">Copy projects and team allocations between months</p>
        </div>
      </div>

      {/* Source and Target Selection */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Source Month/Year */}
        <Card>
          <Card.Header>
            <Card.Title className="flex items-center">
              <FiCalendar className="mr-2" />
              Source Month/Year
            </Card.Title>
            <Card.Description>
              Select the month and year to copy projects from
            </Card.Description>
          </Card.Header>
          <Card.Content className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="sourceMonth">Month</Label>
                <Select
                  id="sourceMonth"
                  value={sourceMonth}
                  onChange={(e) => setSourceMonth(e.target.value)}
                >
                  <option value="">Select Month</option>
                  {months.map(month => (
                    <option key={month.value} value={month.value}>
                      {month.label}
                    </option>
                  ))}
                </Select>
              </div>
              <div>
                <Label htmlFor="sourceYear">Year</Label>
                <Select
                  id="sourceYear"
                  value={sourceYear}
                  onChange={(e) => setSourceYear(e.target.value)}
                >
                  {years.map(year => (
                    <option key={year.value} value={year.value}>
                      {year.label}
                    </option>
                  ))}
                </Select>
              </div>
            </div>

            {sourceMonth && sourceYear && (
              <div className="mt-4 p-3 bg-blue-50 rounded-md">
                <p className="text-sm text-blue-800">
                  Found <strong>{sourceProjects.length}</strong> project(s) in {months.find(m => m.value === sourceMonth)?.label} {sourceYear}
                </p>
              </div>
            )}
          </Card.Content>
        </Card>

        {/* Target Month/Year */}
        <Card>
          <Card.Header>
            <Card.Title className="flex items-center">
              <FiCalendar className="mr-2" />
              Target Month/Year
            </Card.Title>
            <Card.Description>
              Select the month and year to copy projects to
            </Card.Description>
          </Card.Header>
          <Card.Content className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="targetMonth">Month</Label>
                <Select
                  id="targetMonth"
                  value={targetMonth}
                  onChange={(e) => setTargetMonth(e.target.value)}
                >
                  <option value="">Select Month</option>
                  {months.map(month => (
                    <option key={month.value} value={month.value}>
                      {month.label}
                    </option>
                  ))}
                </Select>
              </div>
              <div>
                <Label htmlFor="targetYear">Year</Label>
                <Select
                  id="targetYear"
                  value={targetYear}
                  onChange={(e) => setTargetYear(e.target.value)}
                >
                  {years.map(year => (
                    <option key={year.value} value={year.value}>
                      {year.label}
                    </option>
                  ))}
                </Select>
              </div>
            </div>
          </Card.Content>
        </Card>
      </div>

      {/* Source Projects */}
      {sourceMonth && sourceYear && (
        <Card>
          <Card.Header>
            <div className="flex items-center justify-between">
              <Card.Title>
                Source Projects - {months.find(m => m.value === sourceMonth)?.label} {sourceYear}
              </Card.Title>
              {sourceProjects.length > 0 && (
                <div className="flex items-center space-x-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleSelectAll}
                  >
                    {selectedProjects.length === sourceProjects.length ? 'Deselect All' : 'Select All'}
                  </Button>
                  <Button
                    onClick={handleCopyProjects}
                    disabled={selectedProjects.length === 0 || !targetMonth || !targetYear || isCopying}
                    className="flex items-center"
                  >
                    <FiCopy className="mr-2" />
                    {isCopying ? 'Copying...' : `Copy Selected (${selectedProjects.length})`}
                  </Button>
                </div>
              )}
            </div>
          </Card.Header>
          <Card.Content>
            {sourceProjects.length === 0 ? (
              <EmptyState
                title="No projects found"
                description={`No projects found for ${months.find(m => m.value === sourceMonth)?.label} ${sourceYear}`}
                icon={<FiCalendar className="h-12 w-12" />}
              />
            ) : (
              <div className="space-y-3">
                {sourceProjects.map(project => (
                  <div 
                    key={project.id}
                    className={`border rounded-lg p-4 cursor-pointer transition-colors ${
                      selectedProjects.includes(project.id) 
                        ? 'border-primary-500 bg-primary-50' 
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                    onClick={() => handleProjectSelect(project.id)}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                          selectedProjects.includes(project.id)
                            ? 'border-primary-500 bg-primary-500'
                            : 'border-gray-300'
                        }`}>
                          {selectedProjects.includes(project.id) && (
                            <FiCheck className="w-3 h-3 text-white" />
                          )}
                        </div>
                        <div>
                          <h3 className="font-medium">{project.name}</h3>
                          <p className="text-sm text-gray-500">
                            PM: {project.manager?.name || 'PM not allocated'} • {project.memberCount} members
                          </p>
                        </div>
                      </div>
                      <div className="text-xs text-gray-500">
                        <span className="px-2 py-1 bg-gray-100 rounded-full">
                          {project.status || 'Active'}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </Card.Content>
        </Card>
      )}

      {/* Target Projects */}
      {targetMonth && targetYear && (
        <Card>
          <Card.Header>
            <Card.Title>
              Target Projects - {months.find(m => m.value === targetMonth)?.label} {targetYear}
            </Card.Title>
            <Card.Description>
              Existing projects in the target month with team management
            </Card.Description>
          </Card.Header>
          <Card.Content>
            {targetAllocations.length === 0 ? (
              <EmptyState
                title="No projects yet"
                description={`No projects found in ${months.find(m => m.value === targetMonth)?.label} ${targetYear} yet`}
                icon={<FiUsers className="h-12 w-12" />}
