                          PM: {project.manager_name || 'PM not allocated'} • {project.member_count || 0} members
                        </p>
                      </div>
                      <div className="flex space-x-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleEditMembers(project)}
                        >
                          <FiEdit className="mr-1" />
                          Edit Team
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => window.open(`/projects/${project.id}`, '_blank')}
                        >
                          <FiEye className="mr-1" />
                          View Project
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </Card.Content>
        </Card>
      )}

      {/* Edit Members Modal */}
      <Modal
        isOpen={isEditMemberModalOpen}
        onClose={() => setIsEditMemberModalOpen(false)}
        title="Edit Team Members"
        description={editingProject ? `Manage team for ${editingProject.name}` : ''}
        size="lg"
        footer={
