import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiCopy, FiCalendar, FiCheck, FiAlertCircle } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { getMonthsArray, getYearsArray } from '../../../lib/utils';

export default function CopyAllocations({ initialProjects }) {
  const [sourceFormData, setSourceFormData] = useState({
    month: new Date().getMonth() === 0 
      ? '12' 
      : (new Date().getMonth() < 10 
        ? `0${new Date().getMonth()}` 
        : `${new Date().getMonth()}`),
    year: new Date().getMonth() === 0 
      ? (new Date().getFullYear() - 1).toString() 
      : new Date().getFullYear().toString(),
  });

  const [targetFormData, setTargetFormData] = useState({
    month: new Date().getMonth() + 1 < 10 
      ? `0${new Date().getMonth() + 1}` 
      : `${new Date().getMonth() + 1}`,
    year: new Date().getFullYear().toString(),
  });

  const [projects, setProjects] = useState(initialProjects);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [results, setResults] = useState(null);
  const router = useRouter();
  const months = getMonthsArray();
  const years = getYearsArray();

  const handleSourceChange = (e) => {
    const { name, value } = e.target;
    setSourceFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleTargetChange = (e) => {
    const { name, value } = e.target;
    setTargetFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Validate that source and target aren't the same
      if (sourceFormData.month === targetFormData.month && sourceFormData.year === targetFormData.year) {
        toast.error('Source and target months cannot be the same');
        setIsSubmitting(false);
        return;
      }

      // Call the copy API
      const response = await fetch('/api/project-allocations/copy', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          sourceMonth: sourceFormData.month,
          sourceYear: sourceFormData.year,
          targetMonth: targetFormData.month,
          targetYear: targetFormData.year
        }),
      });

      if (response.ok) {
        const data = await response.json();
        setResults(data.results);

        if (!data.hasSourceAllocations) {
          toast.info(`No allocations found in ${getMonthLabel(sourceFormData.month)} ${sourceFormData.year}. Projects exist but have no allocations for this month.`);
        } else {
          if (data.successCount > 0) {
            toast.success(`Successfully copied ${data.successCount} project allocations`);
          } else {
            toast.error('Failed to copy any project allocations');
          }
        }
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to copy allocations');
      }
    } catch (error) {
      console.error('Failed to copy allocations:', error);
      toast.error('Failed to copy allocations');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getMonthLabel = (monthValue) => {
    return months.find(m => m.value === monthValue)?.label || '';
  };

  return (
    <div className="max-w-4xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/projects/allocations')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Allocations
        </Button>
        <h1 className="text-2xl font-bold">Copy Project Allocations</h1>
        <p className="text-gray-500 mt-1">
          Copy project allocations from a source month to a target month, including team members and project managers.
        </p>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="bg-blue-50 border border-blue-200 rounded-md p-4 mb-4">
              <div className="flex items-start">
                <FiCalendar className="text-blue-500 mt-1 mr-3 flex-shrink-0" />
                <div>
                  <h3 className="font-medium text-blue-800">Copy project allocations</h3>
                  <p className="text-sm text-blue-600 mt-1">
                    Select both source and target months to copy project allocations
                  </p>
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-lg font-medium">Source Month</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="sourceMonth">Source Month</Label>
                  <Select
                    id="sourceMonth"
                    name="month"
                    value={sourceFormData.month}
                    onChange={handleSourceChange}
                  >
                    {months.map(month => (
                      <option key={month.value} value={month.value}>
                        {month.label}
                      </option>
                    ))}
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="sourceYear">Source Year</Label>
                  <Select
                    id="sourceYear"
                    name="year"
                    value={sourceFormData.year}
                    onChange={handleSourceChange}
                  >
                    {years.map(year => (
                      <option key={year.value} value={year.value}>
                        {year.label}
                      </option>
                    ))}
                  </Select>
                </div>
              </div>
            </div>

            <div className="border-t border-gray-200 pt-4 space-y-4">
              <h3 className="text-lg font-medium">Target Month</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="targetMonth">Target Month</Label>
                  <Select
                    id="targetMonth"
                    name="month"
                    value={targetFormData.month}
                    onChange={handleTargetChange}
                  >
                    {months.map(month => (
                      <option key={month.value} value={month.value}>
                        {month.label}
                      </option>
                    ))}
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="targetYear">Target Year</Label>
                  <Select
                    id="targetYear"
                    name="year"
                    value={targetFormData.year}
                    onChange={handleTargetChange}
                  >
                    {years.map(year => (
                      <option key={year.value} value={year.value}>
                        {year.label}
                      </option>
                    ))}
                  </Select>
                </div>
              </div>
            </div>

            <div className="bg-amber-50 border border-amber-200 rounded-md p-4">
              <div className="flex items-start">
                <FiCalendar className="text-amber-500 mt-1 mr-3 flex-shrink-0" />
                <div>
                  <p className="text-sm text-amber-700">
                    You will be copying all project allocations from <strong>{getMonthLabel(sourceFormData.month)} {sourceFormData.year}</strong> to <strong>{getMonthLabel(targetFormData.month)} {targetFormData.year}</strong>
                  </p>
                </div>
              </div>
            </div>

            {results && (
              <div className="mt-4 border rounded-md overflow-hidden">
                <div className="bg-gray-50 px-4 py-2 border-b">
                  <h3 className="font-medium">Copy Results</h3>
                </div>
                <div className="p-4">
                  {results.length === 0 ? (
                    <div className="flex items-center text-amber-600">
                      <FiAlertCircle className="mr-2" />
                      No projects found to copy allocations from
                    </div>
                  ) : !results.some(r => !r.noSourceAllocation) ? (
                    <div className="flex items-center text-amber-600">
                      <FiAlertCircle className="mr-2" />
                      Projects exist but no allocations found in {getMonthLabel(sourceFormData.month)} {sourceFormData.year} to copy
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {results.map((result, index) => (
                        <div 
                          key={index} 
                          className={`flex items-center p-2 rounded ${
                            result.success ? 'bg-green-50 text-green-800' : 
                            result.noSourceAllocation ? 'bg-gray-50 text-gray-500' : 'bg-red-50 text-red-800'
                          }`}
                        >
                          {result.success ? (
                            <FiCheck className="mr-2 flex-shrink-0" />
                          ) : (
                            <FiAlertCircle className="mr-2 flex-shrink-0" />
                          )}
                          <div>
                            <span className="font-medium">{result.projectName}</span>
                            <span className="text-sm ml-2">
                              {result.success 
                                ? 'Successfully copied' 
                                : result.noSourceAllocation 
                                ? 'No allocation in source month' 
                                : 'Failed to copy'}
                            </span>
                          </div>
                          {result.success && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="ml-auto"
                              onClick={() => router.push(`/projects/allocations/${result.allocationId}`)}
                            >
                              View
                            </Button>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            )}
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push('/projects/allocations')}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiCopy className="mr-2" />
              {isSubmitting ? 'Copying...' : 'Copy Allocations'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}

