import { useState } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave, FiPlus, FiX, FiCopy } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { Avatar } from '../../../components/Avatar';
import { getMonthsArray, getYearsArray } from '../../../lib/utils';

export default function NewProjectAllocation({ projects, employees }) {
  const [formData, setFormData] = useState({
    projectId: '',
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear(),
    projectManagerId: ''
  });
  const [selectedEmployees, setSelectedEmployees] = useState([]);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const router = useRouter();
  const months = getMonthsArray();
  const years = getYearsArray(2020, new Date().getFullYear() + 2);

  // Get project managers (employees with role 'project_manager')
  const projectManagers = employees.filter(emp => emp.job_role === 'project_manager' || emp.jobRole === 'project_manager');

  const validateForm = () => {
    const newErrors = {};

    if (!formData.projectId) {
      newErrors.projectId = 'Project is required';
    }

    if (!formData.month) {
      newErrors.month = 'Month is required';
    }

    if (!formData.year) {
      newErrors.year = 'Year is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleEmployeeToggle = (employeeId) => {
    setSelectedEmployees(prev => {
      if (prev.includes(employeeId)) {
        return prev.filter(id => id !== employeeId);
      } else {
        return [...prev, employeeId];
      }
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      // Create the allocation via API
      const response = await fetch('/api/project-allocations', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          projectId: formData.projectId,
          month: formData.month,
          year: formData.year,
          projectManagerId: formData.projectManagerId,
          employeeIds: selectedEmployees
        }),
      });

      if (response.ok) {
        const newAllocation = await response.json();
        toast.success('Project allocation has been created');
        router.push(`/projects/allocations`);
      } else {
        const errorData = await response.json();
        if (errorData.error) {
          setErrors({ general: errorData.error });
        } else {
          toast.error('Failed to create allocation');
        }
      }
    } catch (error) {
      console.error('Failed to create allocation:', error);
      toast.error('Failed to create allocation');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/projects/allocations')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Allocations
        </Button>
        <h1 className="text-2xl font-bold">Create New Project Allocation</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            {errors.general && (
              <div className="bg-red-50 text-red-600 p-3 rounded-md text-sm">
                {errors.general}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="projectId">
                  Project <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="projectId"
                  name="projectId"
                  value={formData.projectId}
                  onChange={handleChange}
                  className={errors.projectId ? 'border-red-500' : ''}
                >
                  <option value="">-- Select Project --</option>
                  {projects.map(project => (
                    <option key={project.id} value={project.id}>
                      {project.name}
                    </option>
                  ))}
                </Select>
                {errors.projectId && (
                  <p className="text-red-500 text-sm mt-1">{errors.projectId}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="projectManagerId">Project Manager</Label>
                <Select
                  id="projectManagerId"
                  name="projectManagerId"
                  value={formData.projectManagerId}
                  onChange={handleChange}
                >
                  <option value="">-- No Project Manager --</option>
                  {projectManagers.map(pm => (
                    <option key={pm.id} value={pm.id}>
                      {pm.name} - {pm.designation}
                    </option>
                  ))}
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="month">
                  Month <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="month"
                  name="month"
                  value={formData.month}
                  onChange={handleChange}
                  className={errors.month ? 'border-red-500' : ''}
                >
                  {months.map(month => (
                    <option key={month.value} value={month.value}>
                      {month.label}
                    </option>
                  ))}
                </Select>
                {errors.month && (
                  <p className="text-red-500 text-sm mt-1">{errors.month}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="year">
                  Year <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="year"
                  name="year"
                  value={formData.year}
                  onChange={handleChange}
                  className={errors.year ? 'border-red-500' : ''}
                >
                  {years.map(year => (
                    <option key={year.value} value={year.value}>
                      {year.label}
                    </option>
                  ))}
                </Select>
                {errors.year && (
                  <p className="text-red-500 text-sm mt-1">{errors.year}</p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label>
                Team Members <span className="text-gray-500 text-sm">(Optional)</span>
              </Label>
              <div className="border border-gray-300 rounded-md p-4 max-h-60 overflow-y-auto">
                <div className="space-y-2">
                  {employees.length === 0 ? (
                    <p className="text-gray-500 text-sm">No employees available</p>
                  ) : (
                    employees.map(employee => (
                      <div key={employee.id} className="flex items-center">
                        <input
                          type="checkbox"
                          id={`employee-${employee.id}`}
                          checked={selectedEmployees.includes(employee.id)}
                          onChange={() => handleEmployeeToggle(employee.id)}
                          className="mr-2 h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                        />
                        <label htmlFor={`employee-${employee.id}`} className="text-sm">
                          {employee.name} - {employee.designation}
                        </label>
                      </div>
                    ))
                  )}
                </div>
              </div>
              <div className="flex justify-between text-sm text-gray-500">
                <span>
                  {selectedEmployees.length} employees selected
                </span>
                {selectedEmployees.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setSelectedEmployees([])}
                    className="text-primary-600 hover:text-primary-800"
                  >
                    Clear selection
                  </button>
                )}
              </div>
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push('/projects/allocations')}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Creating...' : 'Create Allocation'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}

