import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getProjectAllocationById, 
  updateProjectAllocation, 
  getProjectManagers,
  getProjectById
} from '../../../../lib/data';
import { Button } from '../../../../components/Button';
import { Select } from '../../../../components/Select';
import { Label } from '../../../../components/Label';
import { Card } from '../../../../components/Card';
import { getMonthsArray, getYearsArray } from '../../../../lib/utils';

export default function EditAllocation() {
  const [formData, setFormData] = useState({
    month: '',
    year: '',
    projectManagerId: ''
  });
  const [originalData, setOriginalData] = useState(null);
  const [project, setProject] = useState(null);
  const [projectManagers, setProjectManagers] = useState([]);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const { id } = router.query;
  const months = getMonthsArray();
  const years = getYearsArray();

  useEffect(() => {
    if (id) {
      loadData();
    }
  }, [id]);

  const loadData = async () => {
    try {
      // Load allocation data
      const allocationData = getProjectAllocationById(id);

      if (!allocationData) {
        toast.error('Allocation not found');
        router.push('/projects/allocations');
        return;
      }

      // Load project
      const projectData = getProjectById(allocationData.projectId);

      // Load project managers for selection
      const pmData = getProjectManagers();

      setFormData({
        month: allocationData.month,
        year: allocationData.year,
        projectManagerId: allocationData.projectManagerId || ''
      });
      setOriginalData(allocationData);
      setProject(projectData);
      setProjectManagers(pmData);
    } catch (error) {
      console.error('Failed to load data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.month) {
      newErrors.month = 'Month is required';
    }

    if (!formData.year) {
      newErrors.year = 'Year is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const updatedAllocation = updateProjectAllocation(id, formData);

      if (updatedAllocation) {
        toast.success('Allocation has been updated');
        router.push(`/projects/allocations/${id}`);
      } else {
        throw new Error('Failed to update allocation');
      }
    } catch (error) {
      console.error('Failed to update allocation:', error);
      toast.error('Failed to update allocation');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push(`/projects/allocations/${id}`)}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Allocation
        </Button>
        <h1 className="text-2xl font-bold">Edit Allocation</h1>
        {project && (
          <p className="text-gray-500">
            {project.name}
          </p>
        )}
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="month">
                  Month <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="month"
                  name="month"
                  value={formData.month}
                  onChange={handleChange}
                  className={errors.month ? 'border-red-500' : ''}
                >
                  {months.map(month => (
                    <option key={month.value} value={month.value}>
                      {month.label}
                    </option>
                  ))}
                </Select>
                {errors.month && (
                  <p className="text-red-500 text-sm mt-1">{errors.month}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="year">
                  Year <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="year"
                  name="year"
                  value={formData.year}
                  onChange={handleChange}
                  className={errors.year ? 'border-red-500' : ''}
                >
                  {years.map(year => (
                    <option key={year.value} value={year.value}>
                      {year.label}
                    </option>
                  ))}
                </Select>
                {errors.year && (
                  <p className="text-red-500 text-sm mt-1">{errors.year}</p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="projectManagerId">Project Manager</Label>
              <Select
                id="projectManagerId"
                name="projectManagerId"
                value={formData.projectManagerId}
                onChange={handleChange}
              >
                <option value="">-- No Project Manager --</option>
                {projectManagers.map(pm => (
                  <option key={pm.id} value={pm.id}>
                    {pm.name} - {pm.designation}
                  </option>
                ))}
              </Select>
              {projectManagers.length === 0 && (
                <p className="text-amber-600 text-sm mt-1">
                  No project managers available. You can assign employees with the &quot;Project Manager (PM)&quot; job role.
                </p>
              )}
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push(`/projects/allocations/${id}`)}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Saving...' : 'Save Changes'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}

