import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { 
  FiArrowLeft, FiEdit, FiTrash2, FiPlus, FiUsers, 
  FiUser, FiCopy, FiCalendar, FiCheck 
} from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getProjectAllocationById, 
  getAllocationMembers, 
  getProjectById,
  getEmployees,
  getEmployeeById,
  getProjectManager,
  addAllocationMember,
  removeAllocationMember,
  deleteProjectAllocation,
  updateProjectAllocation,
  getProjectAllocation,
  copyAllocationFromMonth
} from '../../../../lib/data';
import { Button } from '../../../../components/Button';
import { Card } from '../../../../components/Card';
import { Avatar } from '../../../../components/Avatar';
import { Modal } from '../../../../components/Modal';
import { EmptyState } from '../../../../components/EmptyState';
import { Select } from '../../../../components/Select';
import { Label } from '../../../../components/Label';
import { getMonthsArray } from '../../../../lib/utils';

export default function AllocationDetails() {
  const [allocation, setAllocation] = useState(null);
  const [project, setProject] = useState(null);
  const [members, setMembers] = useState([]);
  const [projectManager, setProjectManager] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isAddMemberModalOpen, setIsAddMemberModalOpen] = useState(false);
  const [availableEmployees, setAvailableEmployees] = useState([]);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState('');
  const [isAddingMember, setIsAddingMember] = useState(false);
  const [isRemoveMemberModalOpen, setIsRemoveMemberModalOpen] = useState(false);
  const [memberToRemove, setMemberToRemove] = useState(null);
  const [isRemovingMember, setIsRemovingMember] = useState(false);
  const [isCopyModalOpen, setIsCopyModalOpen] = useState(false);
  const [copyFormData, setCopyFormData] = useState({ month: '', year: '' });
  const [isCopying, setIsCopying] = useState(false);
  const [months, setMonths] = useState([]);
  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      loadAllocationData();
      setMonths(getMonthsArray());
    }
  }, [id]);

  const loadAllocationData = () => {
    try {
      const allocationData = getProjectAllocationById(id);

      if (!allocationData) {
        toast.error('Allocation not found');
        router.push('/projects/allocations');
        return;
      }

      const projectData = getProjectById(allocationData.projectId);
      const memberData = getAllocationMembers(id);
      const managerData = allocationData.projectManagerId 
        ? getEmployeeById(allocationData.projectManagerId) 
        : null;

      // Get available employees (employees not in this allocation)
      const allEmployees = getEmployees();
      const memberIds = memberData.map(member => member.id);
      const availableEmps = allEmployees.filter(emp => !memberIds.includes(emp.id));

      setAllocation(allocationData);
      setProject(projectData);
      setMembers(memberData);
      setProjectManager(managerData);
      setAvailableEmployees(availableEmps);
    } catch (error) {
      console.error('Failed to load allocation data:', error);
      toast.error('Failed to load allocation data');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    setIsDeleting(true);

    try {
      const success = deleteProjectAllocation(id);

      if (success) {
        toast.success(`Allocation has been deleted`);
        router.push('/projects/allocations');
      } else {
        throw new Error('Failed to delete allocation');
      }
    } catch (error) {
      console.error('Failed to delete allocation:', error);
      toast.error('Failed to delete allocation');
      setIsDeleting(false);
      setIsDeleteModalOpen(false);
    }
  };

  const handleAddMemberClick = () => {
    setSelectedEmployeeId('');
    setIsAddMemberModalOpen(true);
  };

  const handleEmployeeSelect = (e) => {
    setSelectedEmployeeId(e.target.value);
  };

  const handleAddMember = async () => {
    if (!selectedEmployeeId) {
      toast.error('Please select an employee');
      return;
    }

    setIsAddingMember(true);
    try {
      // Add employee to allocation
      const newMember = addAllocationMember(id, selectedEmployeeId);

      if (newMember) {
        const employee = getEmployees().find(emp => emp.id === selectedEmployeeId);
        toast.success(`${employee?.name} has been added to this allocation`);
        setIsAddMemberModalOpen(false);
        loadAllocationData(); // Reload allocation data
      } else {
        throw new Error('Failed to add employee to allocation');
      }
    } catch (error) {
      console.error('Failed to add member:', error);
      toast.error('Failed to add member to allocation');
    } finally {
      setIsAddingMember(false);
    }
  };

  const handleRemoveMemberClick = (member) => {
    setMemberToRemove(member);
    setIsRemoveMemberModalOpen(true);
  };

  const handleRemoveMember = async () => {
    if (!memberToRemove) return;

    setIsRemovingMember(true);
    try {
      const success = removeAllocationMember(id, memberToRemove.id);

      if (success) {
        toast.success(`${memberToRemove.name} has been removed from this allocation`);
        setIsRemoveMemberModalOpen(false);
        loadAllocationData(); // Reload allocation data
      } else {
        throw new Error('Failed to remove member from allocation');
      }
    } catch (error) {
      console.error('Failed to remove member:', error);
      toast.error('Failed to remove member from allocation');
    } finally {
      setIsRemovingMember(false);
    }
  };

  const handleCopyToMonth = async () => {
    if (!copyFormData.month || !copyFormData.year) {
      toast.error('Please select month and year');
      return;
    }

    setIsCopying(true);
    try {
      const result = copyAllocationFromMonth(
        allocation.projectId,
        allocation.month,
        allocation.year,
        copyFormData.month,
        copyFormData.year
      );

      if (result) {
        toast.success(`Allocation has been copied to ${
          months.find(m => m.value === copyFormData.month)?.label
        } ${copyFormData.year}`);
        setIsCopyModalOpen(false);

        // Navigate to the new allocation
        router.push(`/projects/allocations/${result.id}`);
      } else {
        throw new Error('Failed to copy allocation');
      }
    } catch (error) {
      console.error('Failed to copy allocation:', error);
      toast.error('Failed to copy allocation');
    } finally {
      setIsCopying(false);
    }
  };

  const handleCopyFormChange = (e) => {
    const { name, value } = e.target;
    setCopyFormData(prev => ({ ...prev, [name]: value }));
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (!allocation || !project) {
    return (
      <div className="text-center py-12">
        <h2 className="text-xl font-semibold mb-2">Allocation not found</h2>
        <p className="text-gray-500 mb-6">The allocation you&apos;re looking for doesn&apos;t exist or has been removed.</p>
        <Link href="/projects/allocations">
          <a>
            <Button>Return to Allocations</Button>
          </a>
        </Link>
      </div>
    );
  }

  const monthName = months.find(m => m.value === allocation.month)?.label || '';

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/projects/allocations')}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Allocations
          </Button>
          <h1 className="text-2xl font-bold">
            {project.name} - {monthName} {allocation.year}
          </h1>
        </div>
        <div className="flex space-x-2">
          <Button 
            variant="outline" 
            className="flex items-center"
            onClick={() => setIsCopyModalOpen(true)}
          >
            <FiCopy className="mr-2" />
            Copy to Month
          </Button>
          <Link href={`/projects/allocations/${id}/edit`}>
            <a>
              <Button variant="outline" className="flex items-center">
                <FiEdit className="mr-2" />
                Edit
              </Button>
            </a>
          </Link>
          <Button 
            variant="outline" 
            className="flex items-center text-red-600 border-red-200 hover:bg-red-50"
            onClick={() => setIsDeleteModalOpen(true)}
          >
            <FiTrash2 className="mr-2" />
            Delete
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Allocation Info */}
        <Card className="lg:col-span-1">
          <Card.Header>
            <Card.Title>Allocation Info</Card.Title>
          </Card.Header>
          <Card.Content>
            <div className="space-y-4">
              <div>
                <h3 className="text-sm font-medium text-gray-500">Project</h3>
                <p className="mt-1">{project.name}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Month/Year</h3>
                <p className="mt-1">{monthName} {allocation.year}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Team Size</h3>
                <p className="mt-1">{members.length} member{members.length !== 1 ? 's' : ''}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Project Status</h3>
                <div className="mt-1">
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                    {project.status === 'active' ? 'Active' : 'Inactive'}
                  </span>
                </div>
              </div>
            </div>
          </Card.Content>
        </Card>

        {/* Project Manager */}
        <Card className="lg:col-span-2">
          <Card.Header>
            <div className="flex justify-between items-center">
              <Card.Title>Project Manager</Card.Title>
              <Link href={`/projects/allocations/${id}/edit`}>
                <a>
                  <Button variant="ghost" size="sm">
                    Change
                  </Button>
                </a>
              </Link>
            </div>
          </Card.Header>
          <Card.Content>
            {projectManager ? (
              <div className="flex items-center">
                <Avatar 
                  fallback={projectManager.name} 
                  size="lg" 
                  className="mr-4"
                />
                <div>
                  <h3 className="font-medium">{projectManager.name}</h3>
                  <p className="text-gray-500">{projectManager.designation}</p>
                  <p className="text-sm text-gray-500 mt-1">{projectManager.email}</p>
                </div>
              </div>
            ) : (
              <div className="text-center py-6 text-gray-500">
                <FiUser className="mx-auto h-12 w-12 text-gray-400 mb-3" />
                <p>No project manager assigned to this allocation.</p>
                <Link href={`/projects/allocations/${id}/edit`}>
                  <a>
                    <Button variant="outline" size="sm" className="mt-3">
                      Assign Project Manager
                    </Button>
                  </a>
                </Link>
              </div>
            )}
          </Card.Content>
        </Card>

        {/* Team Members */}
        <Card className="lg:col-span-3">
          <Card.Header>
            <div className="flex justify-between items-center">
              <Card.Title>Team Members</Card.Title>
              <Button 
                size="sm" 
                className="flex items-center"
                onClick={handleAddMemberClick}
              >
                <FiPlus className="mr-1" />
                Add Team Member
              </Button>
            </div>
          </Card.Header>
          <Card.Content>
            {members.length === 0 ? (
              <EmptyState 
                title="No team members yet"
                description="This allocation doesn&apos;t have any team members yet."
                icon={<FiUsers className="h-12 w-12" />}
                action={handleAddMemberClick}
                actionText="Add Team Member"
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Employee
                      </th>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Contact
                      </th>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Department
                      </th>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {members.map((member) => (
                      <tr key={member.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center">
                            <Avatar 
                              fallback={member.name} 
                              size="sm" 
                              className="mr-3"
                            />
                            <div>
                              <div className="font-medium">{member.name}</div>
                              <div className="text-sm text-gray-500">{member.designation}</div>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {member.email}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                          {member.departmentId ? (
                            <Link href={`/departments/${member.departmentId}`}>
                              <a className="text-primary-600 hover:text-primary-800">
                                {member.departmentName || 'View Department'}
                              </a>
                            </Link>
                          ) : (
                            <span className="text-gray-500">No Department</span>
                          )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                          <div className="flex space-x-2">
                            <Link href={`/employees/${member.id}`}>
                              <a className="text-primary-600 hover:text-primary-800 font-medium">
                                View
                              </a>
                            </Link>
                            <button
                              onClick={() => handleRemoveMemberClick(member)}
                              className="text-red-600 hover:text-red-800 font-medium"
                            >
                              Remove
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Card.Content>
        </Card>
      </div>

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Allocation"
        description="Are you sure you want to delete this allocation? This action cannot be undone."
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsDeleteModalOpen(false)}
              disabled={isDeleting}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={handleDelete}
              disabled={isDeleting}
            >
              {isDeleting ? 'Deleting...' : 'Delete Allocation'}
            </Button>
          </>
        }
      >
        <div className="text-sm text-gray-500">
          <p>
            This will permanently delete the allocation for 
            <span className="font-semibold text-gray-700"> {project.name} - {monthName} {allocation.year} </span>
            and remove all team member associations.
          </p>
        </div>
      </Modal>

      {/* Add Member Modal */}
      <Modal
        isOpen={isAddMemberModalOpen}
        onClose={() => setIsAddMemberModalOpen(false)}
        title="Add Team Member"
        description="Select an employee to add to this allocation"
        size="lg"
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsAddMemberModalOpen(false)}
              disabled={isAddingMember}
            >
              Cancel
            </Button>
            <Button 
              onClick={handleAddMember}
              disabled={isAddingMember || !selectedEmployeeId}
            >
              {isAddingMember ? 'Adding...' : 'Add to Allocation'}
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          {availableEmployees.length === 0 ? (
            <div className="text-center py-6">
              <p className="text-gray-500">No available employees to add to this allocation.</p>
              <p className="text-sm text-gray-400 mt-2">All employees are already assigned to this allocation.</p>
              <Link href="/employees/new">
                <a>
                  <Button variant="outline" size="sm" className="mt-4">
                    Create New Employee
                  </Button>
                </a>
              </Link>
            </div>
          ) : (
            <>
              <div className="space-y-2">
                <Label htmlFor="employeeId">Select Employee</Label>
                <Select
                  id="employeeId"
                  value={selectedEmployeeId}
                  onChange={handleEmployeeSelect}
                  className={!selectedEmployeeId ? 'border-gray-300' : ''}
                >
                  <option value="">-- Select an Employee --</option>
                  {availableEmployees.map(emp => (
                    <option key={emp.id} value={emp.id}>
                      {emp.name} - {emp.designation}
                    </option>
                  ))}
                </Select>
              </div>

              {selectedEmployeeId && (
                <div className="bg-gray-50 p-4 rounded-md mt-4">
                  <h3 className="font-medium mb-2">Employee Details</h3>
                  {(() => {
                    const employee = availableEmployees.find(e => e.id === selectedEmployeeId);
                    return employee ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                        <div>
                          <p className="text-gray-500">Name</p>
                          <p className="font-medium">{employee.name}</p>
                        </div>
                        <div>
                          <p className="text-gray-500">Email</p>
                          <p className="font-medium">{employee.email}</p>
                        </div>
                        <div>
                          <p className="text-gray-500">Phone</p>
                          <p className="font-medium">{employee.phoneNumber}</p>
                        </div>
                        <div>
                          <p className="text-gray-500">Designation</p>
                          <p className="font-medium">{employee.designation}</p>
                        </div>
                      </div>
                    ) : null;
                  })()}
                </div>
              )}
            </>
          )}
        </div>
      </Modal>

      {/* Remove Member Modal */}
      <Modal
        isOpen={isRemoveMemberModalOpen}
        onClose={() => setIsRemoveMemberModalOpen(false)}
        title="Remove Team Member"
        description="Are you sure you want to remove this member from the allocation?"
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsRemoveMemberModalOpen(false)}
              disabled={isRemovingMember}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={handleRemoveMember}
              disabled={isRemovingMember}
            >
              {isRemovingMember ? 'Removing...' : 'Remove Member'}
            </Button>
          </>
        }
      >
        {memberToRemove && (
          <div className="text-sm text-gray-500">
            <p>
              This will remove 
              <span className="font-semibold text-gray-700"> {memberToRemove.name} </span>
              from this allocation.
            </p>
          </div>
        )}
      </Modal>

      {/* Copy to Month Modal */}
      <Modal
        isOpen={isCopyModalOpen}
        onClose={() => setIsCopyModalOpen(false)}
        title="Copy Allocation to Another Month"
        description="Select a target month and year to copy this allocation to"
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsCopyModalOpen(false)}
              disabled={isCopying}
            >
              Cancel
            </Button>
            <Button 
              onClick={handleCopyToMonth}
              disabled={isCopying || !copyFormData.month || !copyFormData.year}
            >
              {isCopying ? 'Copying...' : 'Copy Allocation'}
            </Button>
          </>
        }
      >
