import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { getMonthsArray, getYearsArray } from '../../../lib/utils';

export default function EditProject({ project, projectManagers }) {
  const [formData, setFormData] = useState({
    name: project.name || '',
    startMonth: project.start_month || project.startMonth || '',
    startYear: project.start_year || project.startYear || '',
    status: project.status || 'active',
    projectManagerId: project.project_manager_id || project.projectManagerId || ''
  });
  const [originalData, setOriginalData] = useState(project);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(false);
  const router = useRouter();
  const { id } = router.query;
  const months = getMonthsArray();
  const years = getYearsArray();

  // Update form data when project data changes
  useEffect(() => {
    setFormData({
      name: project.name || '',
      startMonth: project.start_month || project.startMonth || '',
      startYear: project.start_year || project.startYear || '',
      status: project.status || 'active',
      projectManagerId: project.project_manager_id || project.projectManagerId || ''
    });
    setOriginalData(project);
  }, [project]);

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Project name is required';
    }

    if (!formData.startMonth) {
      newErrors.startMonth = 'Start month is required';
    }

    if (!formData.startYear) {
      newErrors.startYear = 'Start year is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      console.log('Submitting project data:', formData); // Debug log

      const response = await fetch(`/api/projects/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        const updatedProject = await response.json();
        console.log('Project updated successfully:', updatedProject); // Debug log
        toast.success(`Project "${updatedProject.name}" has been updated`);
        router.push(`/projects/${id}`);
      } else {
        const error = await response.json();
        console.error('API Error:', error); // Debug log
        throw new Error(error.error || 'Failed to update project');
      }
    } catch (error) {
      console.error('Failed to update project:', error);
      toast.error(error.message || 'Failed to update project');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push(`/projects/${id}`)}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Project
        </Button>
        <h1 className="text-2xl font-bold">Edit Project</h1>
        <p className="text-gray-500">Update project information</p>
      </div>

      {/* Debug Info - Remove in production */}
      {process.env.NODE_ENV === 'development' && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-md p-4 mb-6">
          <h4 className="text-sm font-medium text-yellow-800 mb-2">Debug Information:</h4>
          <div className="text-xs text-yellow-700 space-y-1">
            <p>Project ID: {project.id}</p>
            <p>Original Data: {JSON.stringify(originalData, null, 2)}</p>
            <p>Form Data: {JSON.stringify(formData, null, 2)}</p>
          </div>
        </div>
      )}

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Project Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="e.g. Website Redesign, Mobile App Development"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="startMonth">
                  Start Month <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="startMonth"
                  name="startMonth"
                  value={formData.startMonth}
                  onChange={handleChange}
                  className={errors.startMonth ? 'border-red-500' : ''}
                >
                  <option value="">Select month</option>
                  {months.map(month => (
                    <option key={month.value} value={month.value}>
                      {month.label}
                    </option>
                  ))}
                </Select>
                {errors.startMonth && (
                  <p className="text-red-500 text-sm mt-1">{errors.startMonth}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="startYear">
                  Start Year <span className="text-red-500">*</span>
                </Label>
                <Select
                  id="startYear"
                  name="startYear"
                  value={formData.startYear}
                  onChange={handleChange}
                  className={errors.startYear ? 'border-red-500' : ''}
                >
                  <option value="">Select year</option>
                  {years.map(year => (
                    <option key={year.value} value={year.value}>
                      {year.label}
                    </option>
                  ))}
                </Select>
                {errors.startYear && (
                  <p className="text-red-500 text-sm mt-1">{errors.startYear}</p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="status">Project Status</Label>
              <Select
                id="status"
                name="status"
                value={formData.status}
                onChange={handleChange}
              >
                <option value="active">Active</option>
                <option value="on_hold">On Hold</option>
                <option value="completed">Completed</option>
                <option value="cancelled">Cancelled</option>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="projectManagerId">Project Manager</Label>
              <Select
                id="projectManagerId"
                name="projectManagerId"
                value={formData.projectManagerId}
                onChange={handleChange}
              >
                <option value="">No Project Manager Assigned</option>
                {projectManagers.map(pm => (
                  <option key={pm.id} value={pm.id}>
                    {pm.name} - {pm.email}
                  </option>
                ))}
              </Select>
            </div>

            <div className="flex justify-end space-x-3 pt-6 border-t">
              <Button
                type="button"
                variant="outline"
                onClick={() => router.push(`/projects/${id}`)}
                disabled={isSubmitting}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={isSubmitting}
              >
                <FiSave className="mr-2" />
                {isSubmitting ? 'Updating...' : 'Update Project'}
              </Button>
            </div>
          </Card.Content>
        </form>
      </Card>
    </div>
  );
}

