export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getProjectById, 
    getProjectMembers, 
    getProjectManager,
    getEmployees,
    getProjectAllocations
  } = require('../../../lib/data');
  const { id } = context.params;

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    if (!user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    const [projectData, memberData, managerData, allEmployees] = await Promise.all([
      getProjectById(id),
      getProjectMembers(id),
      getProjectManager(id),
      getEmployees()
    ]);

    if (!projectData) {
      return {
        notFound: true
      };
    }

    // Check if user has permission to view this project
    if (user.role !== 'admin') {
      let hasAccess = false;

      // Find user's employee record
      const userEmployee = allEmployees.find(emp => 
        emp.email?.toLowerCase() === user.email?.toLowerCase()
      );

      if (userEmployee) {
        // Check if user is a member of this project
        const isMember = memberData.some(member => 
          member.id === userEmployee.id || 
          member.employee_id === userEmployee.id
        );

        if (isMember) {
          hasAccess = true;
        }

        // Also check project allocations
        if (!hasAccess) {
          try {
            const projectAllocations = await getProjectAllocations();
            const userAllocations = projectAllocations.filter(allocation => 
              allocation.employee_id === userEmployee.id && 
              allocation.project_id === id
            );
            if (userAllocations.length > 0) {
              hasAccess = true;
            }
          } catch (error) {
            console.error('Error checking project allocations:', error);
          }
        }

        // For project managers, check if they manage this project
        if (!hasAccess && user.role === 'project_manager') {
          if (projectData.manager_id === user.id || 
              projectData.project_manager_id === user.id ||
              projectData.assigned_pm === user.email) {
            hasAccess = true;
          }
        }
      }

      if (!hasAccess) {
        console.log(`Access denied: User ${user.email} cannot view project ${id}`);
        return {
          redirect: {
            destination: '/unauthorized',
            permanent: false,
          },
        };
      }
    }

    // Get available employees (employees not in this project)
    const memberIds = memberData.map(member => member.id);
    const availableEmps = allEmployees.filter(emp => !memberIds.includes(emp.id));

    // Serialize dates
    const serializedProject = {
      ...projectData,
      created_at: projectData.created_at ? projectData.created_at.toISOString() : null,
      updated_at: projectData.updated_at ? projectData.updated_at.toISOString() : null
    };

    const serializedMembers = memberData.map(member => ({
      ...member,
      created_at: member.created_at ? member.created_at.toISOString() : null,
      updated_at: member.updated_at ? member.updated_at.toISOString() : null
    }));

    const serializedManager = managerData ? {
      ...managerData,
      created_at: managerData.created_at ? managerData.created_at.toISOString() : null,
      updated_at: managerData.updated_at ? managerData.updated_at.toISOString() : null
    } : null;

    const serializedAvailableEmployees = availableEmps.map(emp => ({
      ...emp,
      created_at: emp.created_at ? emp.created_at.toISOString() : null,
      updated_at: emp.updated_at ? emp.updated_at.toISOString() : null
    }));

    return {
      props: {
        project: serializedProject,
        members: serializedMembers,
        projectManager: serializedManager,
        availableEmployees: serializedAvailableEmployees,
        user: user
      }
    };
  } catch (error) {
    console.error('Error fetching project data:', error);
    return {
      notFound: true
    };
  }
}

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { 
  FiArrowLeft, FiEdit, FiTrash2, FiPlus, 
  FiUsers, FiUser, FiMail, FiPhone, FiCalendar,
  FiUserMinus
} from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Card } from '../../../components/Card';
import { Avatar } from '../../../components/Avatar';
import { Modal } from '../../../components/Modal';
import { EmptyState } from '../../../components/EmptyState';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { getMonthsArray } from '../../../lib/utils';

export default function ProjectDetails({ project: initialProject, members: initialMembers, projectManager: initialProjectManager, availableEmployees: initialAvailableEmployees, user }) {
  const [project, setProject] = useState(initialProject);
  const [members, setMembers] = useState(initialMembers);
  const [projectManager, setProjectManager] = useState(initialProjectManager);
  const [loading, setLoading] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Member management states
  const [isAddMemberModalOpen, setIsAddMemberModalOpen] = useState(false);
  const [availableEmployees, setAvailableEmployees] = useState(initialAvailableEmployees);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState('');
  const [isAddingMember, setIsAddingMember] = useState(false);
  const [isRemoveMemberModalOpen, setIsRemoveMemberModalOpen] = useState(false);
  const [memberToRemove, setMemberToRemove] = useState(null);
  const [isRemovingMember, setIsRemovingMember] = useState(false);

  const router = useRouter();
  const { id } = router.query;
  const months = getMonthsArray();

  // Check if user can manage this project - simplified to admin only for team management
  const canManageProject = user && user.role === 'admin';

  const refreshMembers = async () => {
    try {
      const [membersResponse, employeesResponse] = await Promise.all([
        fetch(`/api/projects/${id}/members`),
        fetch('/api/employees')
      ]);

      if (membersResponse.ok && employeesResponse.ok) {
        const membersData = await membersResponse.json();
        const employeesData = await employeesResponse.json();

        setMembers(membersData);

        // Update available employees (excluding current members)
        const memberIds = membersData.map(member => member.id);
        const available = employeesData.filter(emp => !memberIds.includes(emp.id));
        setAvailableEmployees(available);
      }
    } catch (error) {
      console.error('Failed to refresh members:', error);
    }
  };

  const handleDelete = async () => {
    setIsDeleting(true);

    try {
      const response = await fetch(`/api/projects/${id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        toast.success(`Project "${project.name}" has been deleted`);
        router.push('/projects');
      } else {
        throw new Error('Failed to delete project');
      }
    } catch (error) {
      console.error('Failed to delete project:', error);
      toast.error('Failed to delete project');
      setIsDeleting(false);
      setIsDeleteModalOpen(false);
    }
  };

  // Member management functions
  const handleAddMemberClick = () => {
    setSelectedEmployeeId('');
    setIsAddMemberModalOpen(true);
  };

  const handleEmployeeSelect = (e) => {
    setSelectedEmployeeId(e.target.value);
  };

  const handleAddMember = async () => {
    if (!selectedEmployeeId) {
      toast.error('Please select an employee');
      return;
    }

    setIsAddingMember(true);
    try {
      const response = await fetch(`/api/projects/${id}/members`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ employeeId: selectedEmployeeId }),
      });

      if (response.ok) {
        const employee = availableEmployees.find(emp => emp.id === selectedEmployeeId);
        toast.success(`${employee?.name} has been added to this project`);
        setIsAddMemberModalOpen(false);
        setSelectedEmployeeId('');
        // Refresh members list
        await refreshMembers();
      } else {
        const error = await response.json();
        throw new Error(error.error || 'Failed to add member to project');
      }
    } catch (error) {
      console.error('Failed to add member:', error);
      toast.error(error.message || 'Failed to add member to project');
    } finally {
      setIsAddingMember(false);
    }
  };

  const handleRemoveMemberClick = (member) => {
    setMemberToRemove(member);
    setIsRemoveMemberModalOpen(true);
  };

  const handleRemoveMember = async () => {
    if (!memberToRemove) return;

    setIsRemovingMember(true);
    try {
      const response = await fetch(`/api/projects/${id}/members`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ employeeId: memberToRemove.id }),
      });

      if (response.ok) {
        toast.success(`${memberToRemove.name} has been removed from this project`);
        setIsRemoveMemberModalOpen(false);
        setMemberToRemove(null);
        // Refresh members list
        await refreshMembers();
      } else {
        const error = await response.json();
        throw new Error(error.error || 'Failed to remove member from project');
      }
    } catch (error) {
