                        </div>
                        <div>
                          <p className="text-gray-500">Job Role</p>
                          <p className="font-medium">{employee.jobRole || employee.job_role}</p>
                        </div>
                      </div>
                    ) : null;
                  })()}
                </div>
              )}
            </>
          )}
        </div>
      </Modal>

      {/* Remove Member Modal */}
      <Modal
        isOpen={isRemoveMemberModalOpen}
        onClose={() => setIsRemoveMemberModalOpen(false)}
        title="Remove Team Member"
        description="Are you sure you want to remove this member from the project?"
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsRemoveMemberModalOpen(false)}
              disabled={isRemovingMember}
            >
