import { useState } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave, FiPlus, FiTrash2, FiEye, FiCheck, FiEdit2, FiCalendar } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';
import { Modal } from '../../components/Modal';

// Helper function to generate months from current month onwards
const getUpcomingMonths = (numberOfMonths = 6) => {
  const months = [];
  const currentDate = new Date();

  for (let i = 0; i < numberOfMonths; i++) {
    const date = new Date(currentDate.getFullYear(), currentDate.getMonth() + i, 1);
    const monthName = date.toLocaleDateString('en-US', { month: 'long' });
    const year = date.getFullYear();
    const monthKey = `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}`;

    months.push({
      value: monthKey,
      label: `${monthName} ${year}`,
      month: date.getMonth() + 1,
      year: year
    });
  }

  return months;
};

export default function NewForm() {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    frequency: 'once',
    audience: 'all',
    status: 'draft',
    start_date: '',
    form_type: 'general',
    allocation_month: ''
  });

  const [questions, setQuestions] = useState([]);
  const [currentQuestion, setCurrentQuestion] = useState({
    question_text: '',
    question_type: 'short_text',
    is_required: false,
    options: []
  });

  const [isAddingQuestion, setIsAddingQuestion] = useState(false);
  const [editingQuestionIndex, setEditingQuestionIndex] = useState(null);
  const [currentOption, setCurrentOption] = useState('');
  const [isPreviewModalOpen, setIsPreviewModalOpen] = useState(false);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const router = useRouter();

  const questionTypes = [
    { value: 'short_text', label: 'Short Text' },
    { value: 'long_text', label: 'Long Text' },
    { value: 'multiple_choice', label: 'Multiple Choice' },
    { value: 'checkbox', label: 'Checkboxes' },
    { value: 'dropdown', label: 'Dropdown' },
    { value: 'linear_scale', label: 'Linear Scale' },
    { value: 'date', label: 'Date' },
    { value: 'time', label: 'Time' }
  ];

  // Updated frequency options - only Once and Monthly
  const frequencies = [
    { value: 'once', label: 'Once' },
    { value: 'monthly', label: 'Monthly' }
  ];

  // Updated form types with Monthly Project Review
  const formTypes = [
    { value: 'general', label: 'General Form' },
    { value: 'feedback', label: 'Feedback Form' },
    { value: 'evaluation', label: 'Evaluation Form' },
    { value: 'monthly_project_review', label: 'Monthly Project Review' }
  ];

  // Updated target audience options - conditional based on form type
  const getAudienceOptions = (formType) => {
    if (formType === 'monthly_project_review') {
      return [
        { value: 'employee_to_pm', label: 'Employee to PM' },
        { value: 'pm_to_employee', label: 'PM to Employees' }
      ];
    }

    return [
      { value: 'all', label: 'All' },
      { value: 'employee', label: 'Employee' },
      { value: 'project_manager', label: 'Project Manager' },
      { value: 'team_lead', label: 'Team Lead' },
      { value: 'co_founders', label: 'Co-founders' }
    ];
  };

  // Get current audience options based on selected form type
  const currentAudienceOptions = getAudienceOptions(formData.form_type);

  // Get upcoming months for allocation
  const upcomingMonths = getUpcomingMonths(6);

  const validateForm = () => {
    const newErrors = {};

    if (!formData.title.trim()) {
      newErrors.title = 'Form title is required';
    }

    if (!formData.start_date) {
      newErrors.start_date = 'Start date is required';
    }

    // For monthly project review, allocation month is required
    if (formData.form_type === 'monthly_project_review' && !formData.allocation_month) {
      newErrors.allocation_month = 'Project allocation month is required for Monthly Project Review';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const validateQuestion = () => {
    const newErrors = {};

    if (!currentQuestion.question_text.trim()) {
      newErrors.question_text = 'Question text is required';
    }

    if (['multiple_choice', 'checkbox', 'dropdown'].includes(currentQuestion.question_type) && 
        currentQuestion.options.length < 2) {
      newErrors.options = 'At least two options are required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;

    // If form type changes, reset audience to appropriate default
    if (name === 'form_type') {
      const newAudienceOptions = getAudienceOptions(value);
      const currentAudience = formData.audience;

      // Check if current audience is valid for new form type
      const isAudienceValid = newAudienceOptions.some(option => option.value === currentAudience);

      setFormData(prev => ({ 
        ...prev, 
        [name]: value,
        // Reset audience if current selection is not valid for new form type
        audience: isAudienceValid ? currentAudience : newAudienceOptions[0]?.value || 'all'
      }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleQuestionChange = (e) => {
    const { name, value, type, checked } = e.target;
    const val = type === 'checkbox' ? checked : value;

    setCurrentQuestion(prev => ({ 
      ...prev, 
      [name]: val,
      // Reset options if changing from a type with options to one without
      ...(name === 'question_type' && 
        !['multiple_choice', 'checkbox', 'dropdown'].includes(value) && 
        { options: [] })
    }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleOptionChange = (e) => {
    setCurrentOption(e.target.value);
  };

  const addOption = () => {
    if (!currentOption.trim()) return;

    setCurrentQuestion(prev => ({
      ...prev,
      options: [...prev.options, currentOption.trim()]
    }));

    setCurrentOption('');

    // Clear option error if it exists
    if (errors.options) {
      setErrors(prev => ({ ...prev, options: undefined }));
    }
  };

  const removeOption = (index) => {
    setCurrentQuestion(prev => ({
      ...prev,
      options: prev.options.filter((_, i) => i !== index)
    }));
  };

  const addQuestion = () => {
    if (!validateQuestion()) return;

    if (editingQuestionIndex !== null) {
      // Update existing question
      setQuestions(prev => prev.map((q, i) => 
        i === editingQuestionIndex ? { ...currentQuestion } : q
      ));
      setEditingQuestionIndex(null);
    } else {
      // Add new question
      setQuestions(prev => [...prev, { ...currentQuestion }]);
    }

    // Reset current question
    setCurrentQuestion({
      question_text: '',
      question_type: 'short_text',
      is_required: false,
      options: []
    });

    setIsAddingQuestion(false);
  };

  const editQuestion = (index) => {
    setCurrentQuestion({ ...questions[index] });
    setEditingQuestionIndex(index);
    setIsAddingQuestion(true);
  };

  const removeQuestion = (index) => {
    setQuestions(prev => prev.filter((_, i) => i !== index));
  };

  const saveForm = async (status = 'draft') => {
    if (!validateForm()) return;

    setIsSubmitting(true);

    try {
      const formToSave = {
        ...formData,
        status,
        questions,
        published_at: status === 'published' ? new Date().toISOString() : null
      };

      const response = await fetch('/api/forms', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formToSave),
      });

      if (response.ok) {
        const newForm = await response.json();
        toast.success(`Form ${status === 'published' ? 'published' : 'saved as draft'} successfully`);
        router.push('/forms');
      } else {
        const error = await response.json();
        throw new Error(error.message || 'Failed to save form');
      }
    } catch (error) {
      console.error('Error saving form:', error);
      toast.error(`Failed to ${status === 'published' ? 'publish' : 'save'} form`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAddNewQuestion = () => {
    setIsAddingQuestion(true);
    setEditingQuestionIndex(null);
    setCurrentQuestion({
      question_text: '',
      question_type: 'short_text',
      is_required: false,
      options: []
    });
  };

  return (
    <div className="max-w-4xl mx-auto fade-in pb-12">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/forms')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Forms
        </Button>
        <h1 className="text-2xl font-bold">Create New Score Builder Form</h1>
      </div>

      <Card className="mb-6">
        <Card.Header>
          <Card.Title>Form Details</Card.Title>
        </Card.Header>
        <Card.Content className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="title">
              Form Title <span className="text-red-500">*</span>
            </Label>
            <Input
              id="title"
              name="title"
              value={formData.title}
              onChange={handleFormChange}
              placeholder="Enter form title"
              className={errors.title ? 'border-red-500' : ''}
            />
            {errors.title && (
              <p className="text-red-500 text-sm mt-1">{errors.title}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <textarea
              id="description"
              name="description"
              value={formData.description}
              onChange={handleFormChange}
              placeholder="Enter form description (optional)"
              rows={3}
              className="flex w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 focus-visible:ring-offset-2"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <Label htmlFor="form_type">Form Type</Label>
              <Select
                id="form_type"
                name="form_type"
                value={formData.form_type}
                onChange={handleFormChange}
              >
                {formTypes.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="start_date">
                Start Date <span className="text-red-500">*</span>
              </Label>
              <div className="relative">
                <Input
                  id="start_date"
                  name="start_date"
                  type="date"
                  value={formData.start_date}
                  onChange={handleFormChange}
                  min={new Date().toISOString().split('T')[0]}
                />
                <FiCalendar className="absolute right-3 top-3 h-4 w-4 text-gray-400 pointer-events-none" />
              </div>
              {errors.start_date && (
                <p className="text-red-500 text-sm mt-1">{errors.start_date}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <Label htmlFor="frequency">Frequency</Label>
              <Select
                id="frequency"
                name="frequency"
                value={formData.frequency}
                onChange={handleFormChange}
              >
                {frequencies.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="audience">Target Audience</Label>
              <Select
                id="audience"
                name="audience"
                value={formData.audience}
                onChange={handleFormChange}
              >
                {currentAudienceOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </Select>
            </div>
          </div>

          {/* Project Allocation Month - Only show for Monthly Project Review */}
          {formData.form_type === 'monthly_project_review' && (
            <div className="space-y-2">
              <Label htmlFor="allocation_month">
                Starting Project Allocation Month <span className="text-red-500">*</span>
              </Label>
              <Select
                id="allocation_month"
                name="allocation_month"
                value={formData.allocation_month}
                onChange={handleFormChange}
                className={errors.allocation_month ? 'border-red-500' : ''}
              >
                <option value="">Select allocation month</option>
                {upcomingMonths.map(month => (
                  <option key={month.value} value={month.value}>
                    {month.label}
                  </option>
                ))}
              </Select>
              {errors.allocation_month && (
                <p className="text-red-500 text-sm mt-1">{errors.allocation_month}</p>
              )}
              <p className="text-sm text-gray-500">
                Select the month for which project allocations will be reviewed (current month onwards, up to 6 months ahead)
              </p>
            </div>
          )}
        </Card.Content>
      </Card>

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-semibold">Form Questions</h2>
      </div>

      {/* Question List */}
      {questions.length === 0 ? (
        <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg p-8 text-center mb-6">
          <p className="text-gray-500">No questions added yet. Click the &quot;Add Question&quot; button to create your first question.</p>
        </div>
      ) : (
        <div className="space-y-4 mb-6">
          {questions.map((question, index) => (
            (isAddingQuestion && editingQuestionIndex === index) ? (
              <Card key={index} className="mb-6 border-primary-200 shadow-md">
                <Card.Header>
                  <Card.Title>Edit Question</Card.Title>
                </Card.Header>
                <Card.Content className="space-y-6">
                  <div className="space-y-2">
                    <Label htmlFor="question_text">
                      Question Text <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      id="question_text"
                      name="question_text"
                      value={currentQuestion.question_text}
                      onChange={handleQuestionChange}
                      placeholder="Enter your question"
                      className={errors.question_text ? 'border-red-500' : ''}
                    />
                    {errors.question_text && (
                      <p className="text-red-500 text-sm mt-1">{errors.question_text}</p>
                    )}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <Label htmlFor="question_type">Question Type</Label>
                      <Select
                        id="question_type"
                        name="question_type"
                        value={currentQuestion.question_type}
                        onChange={handleQuestionChange}
                      >
                        {questionTypes.map(option => (
                          <option key={option.value} value={option.value}>
                            {option.label}
                          </option>
                        ))}
