export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getFormSubmissions, getForms, getEmployees } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    if (!cookies.user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    const user = JSON.parse(cookies.user);
    const [allSubmissions, forms, employees] = await Promise.all([
      getFormSubmissions(),
      getForms(),
      getEmployees()
    ]);

    // Find current user's employee record
    const currentEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());

    // Filter submissions by current user (submitted by them)
    const mySubmissions = allSubmissions.filter(submission => {
      // Check both old and new field structures
      const isSubmittedByMe = 
        submission.user_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.employee_id === currentEmployee?.id ||
        submission.filled_by_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.filled_by_id === currentEmployee?.id;

      return isSubmittedByMe;
    });

    // Filter submissions for current user (forms filled for them)
    const submissionsForMe = allSubmissions.filter(submission => {
      // Check if the form was filled for the current user
      const isForMe = 
        submission.filled_for_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.filled_for_id === currentEmployee?.id;

      // Also include forms where they are the target based on form audience (for backward compatibility)
      if (!isForMe) {
        const form = forms.find(f => f.id === submission.form_id);
        if (form) {
          switch (form.audience) {
            case 'all':
              return true;
            case 'employee':
              return user.isEmployee || user.role === 'employee';
            case 'project_manager':
              return user.role === 'project_manager';
            case 'team_lead':
              return user.role === 'team_lead';
            case 'co_founders':
              return user.role === 'co_founder';
            case 'employee_to_pm':
              // Forms submitted by employees for PM review
              return user.role === 'project_manager';
            case 'pm_to_employee':
              // Forms submitted by PMs for employee review
              return user.isEmployee || user.role === 'employee';
            default:
              return false;
          }
        }
      }

      return isForMe;
    });

    // Get all submissions for admin users
    const allSubmissionsForAdmin = user.role === 'admin' || user.role === 'co_founder' ? allSubmissions : [];

    // Serialize dates and add form details
    const serializeSubmissions = (submissions) => {
      return submissions.map(submission => {
        const form = forms.find(f => f.id === submission.form_id);
        return {
          ...submission,
          submitted_at: submission.submitted_at ? submission.submitted_at.toISOString() : null,
          created_at: submission.created_at ? submission.created_at.toISOString() : null,
          updated_at: submission.updated_at ? submission.updated_at.toISOString() : null,
          next_due_date: submission.next_due_date ? submission.next_due_date.toISOString() : null,
          form_title: form?.title || 'Unknown Form',
          form_type: form?.form_type || 'general'
        };
      });
    };

    return {
      props: {
        mySubmissions: serializeSubmissions(mySubmissions),
        submissionsForMe: serializeSubmissions(submissionsForMe),
        allSubmissions: serializeSubmissions(allSubmissionsForAdmin),
        user: user,
        isAdmin: user.role === 'admin' || user.role === 'co_founder'
      }
    };
  } catch (error) {
    console.error('Error fetching submissions:', error);
    return {
      props: {
        mySubmissions: [],
        submissionsForMe: [],
        allSubmissions: [],
        user: null,
        isAdmin: false
      }
    };
  }
}

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { FiArrowLeft, FiFileText, FiCalendar, FiUser, FiEye, FiCheckCircle, FiClock, FiX, FiRefreshCw } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Card } from '../../components/Card';
import { Badge } from '../../components/Badge';
import { EmptyState } from '../../components/EmptyState';

export default function MySubmissions({ mySubmissions, submissionsForMe, allSubmissions, user, isAdmin }) {
  const [activeTab, setActiveTab] = useState(isAdmin ? 'all' : 'submitted'); // Default to 'all' for admins
  const [submissions, setSubmissions] = useState({
    mySubmissions,
    submissionsForMe,
    allSubmissions
  });
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastRefresh, setLastRefresh] = useState(Date.now());

  // Set default tab based on admin status
  useEffect(() => {
    if (isAdmin) {
      setActiveTab('all');
    }
  }, [isAdmin]);

  // Add real-time refresh functionality
  useEffect(() => {
    const refreshData = async () => {
      try {
        setIsRefreshing(true);
        const response = await fetch('/api/forms/submissions', {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
          },
        });

        if (response.ok) {
          const data = await response.json();
          setSubmissions({
            mySubmissions: data.mySubmissions || [],
            submissionsForMe: data.submissionsForMe || [],
            allSubmissions: data.allSubmissions || []
          });
          setLastRefresh(Date.now());
        }
      } catch (error) {
        console.error('Error refreshing submissions:', error);
      } finally {
        setIsRefreshing(false);
      }
    };

    // Listen for form submission events
    const handleMessage = (event) => {
      if (event.data && event.data.type === 'FORM_SUBMITTED') {
        refreshData();
      }
    };

    window.addEventListener('message', handleMessage);

    // Auto-refresh every 30 seconds
    const interval = setInterval(refreshData, 30000);

    return () => {
      window.removeEventListener('message', handleMessage);
      clearInterval(interval);
    };
  }, []);

  const refreshSubmissions = async () => {
    setIsRefreshing(true);
    try {
      const response = await fetch('/api/forms/submissions', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        const data = await response.json();
        setSubmissions({
          mySubmissions: data.mySubmissions || [],
          submissionsForMe: data.submissionsForMe || [],
          allSubmissions: data.allSubmissions || []
        });
        setLastRefresh(Date.now());
        toast.success('Submissions refreshed successfully');
      } else {
        toast.error('Failed to refresh submissions');
      }
    } catch (error) {
      console.error('Error refreshing submissions:', error);
      toast.error('Error refreshing submissions');
    } finally {
      setIsRefreshing(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusColors = {
      completed: 'bg-green-100 text-green-800',
      pending: 'bg-yellow-100 text-yellow-800',
      reviewed: 'bg-blue-100 text-blue-800'
    };

    return (
      <Badge className={statusColors[status] || statusColors.pending}>
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </Badge>
    );
  };

  const getFormTypeBadge = (formType) => {
    const typeColors = {
      general: 'bg-gray-100 text-gray-800',
      feedback: 'bg-purple-100 text-purple-800',
      evaluation: 'bg-orange-100 text-orange-800',
      monthly_project_review: 'bg-indigo-100 text-indigo-800'
    };

    return (
      <Badge className={typeColors[formType] || typeColors.general}>
        {(formType || 'general').replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}
      </Badge>
    );
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString();
  };

  const getCurrentSubmissions = () => {
    switch (activeTab) {
      case 'submitted':
        return submissions.mySubmissions;
      case 'received':
        return submissions.submissionsForMe;
      case 'all':
        return submissions.allSubmissions;
      default:
        return submissions.mySubmissions;
    }
  };

  const currentSubmissions = getCurrentSubmissions();

  return (
    <div className="max-w-6xl mx-auto space-y-6 fade-in">
      <div className="flex items-center justify-between">
        <div>
          <Link href="/forms">
            <a>
              <Button variant="ghost" size="sm" className="mb-2">
                <FiArrowLeft className="mr-2" />
                Back to Forms
              </Button>
            </a>
          </Link>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold">
              {isAdmin ? 'Form Submissions Management' : 'My Form Submissions'}
            </h1>
            {lastRefresh && (
              <div className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">
                Last updated: {new Date(lastRefresh).toLocaleTimeString()}
              </div>
            )}
          </div>
          <p className="text-gray-500">
            {isAdmin ? 'View and manage all form submissions' : 'Track your form submissions and responses'}
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            onClick={refreshSubmissions}
            disabled={isRefreshing}
            className="flex items-center"
          >
            <div className={`mr-2 ${isRefreshing ? 'animate-spin' : ''}`}>
              <FiRefreshCw />
            </div>
            {isRefreshing ? 'Refreshing...' : 'Refresh'}
          </Button>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="border-b border-gray-200">
        <nav className="-mb-px flex space-x-8">
          {!isAdmin && (
            <>
              <button
                onClick={() => setActiveTab('submitted')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'submitted'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Forms I Submitted ({submissions.mySubmissions.length})
              </button>
              <button
                onClick={() => setActiveTab('received')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'received'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
