                <div className="text-2xl font-bold text-purple-600">
                  {new Set(submissions.allSubmissions.map(s => s.form_id)).size}
                </div>
                <div className="text-sm text-gray-500">Unique Forms</div>
              </Card.Content>
            </Card>
          </>
        )}
