import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { FiFileText, FiPlus, FiSearch, FiFilter, FiX, FiEdit, FiEdit2, FiTrash2, FiEye, FiCalendar, FiUsers, FiCheck, FiClock, FiEdit3 } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Card } from '../../components/Card';
import { EmptyState } from '../../components/EmptyState';
import { Modal } from '../../components/Modal';
import { Badge } from '../../components/Badge';
import { DueFormsNotification } from '../../components/DueFormsNotification';
import { isAdmin, getUser } from '../../lib/auth';

export default function Forms({ initialForms, userSubmissions, user: initialUser, isMyFormsView }) {
  const [forms, setForms] = useState(initialForms);
  const [submissions, setSubmissions] = useState(Array.isArray(userSubmissions) ? userSubmissions : []);
  const [user, setUser] = useState(initialUser);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [audienceFilter, setAudienceFilter] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [formToDelete, setFormToDelete] = useState(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isAdminUser, setIsAdminUser] = useState(false);
  const [lastRefresh, setLastRefresh] = useState(Date.now());
  const router = useRouter();

  useEffect(() => {
    setIsAdminUser(isAdmin());
  }, []);

  // Ensure user state is maintained
  useEffect(() => {
    if (!user) {
      const currentUser = getUser();
      if (currentUser) {
        setUser(currentUser);
      }
    }
  }, [user]);

  // Ensure submissions is always an array
  useEffect(() => {
    if (!Array.isArray(submissions)) {
      console.warn('Fixing submissions state - was not an array:', submissions);
      setSubmissions([]);
    }
  }, [submissions]);

  // Debug user state changes
  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      console.log('Forms page - User state:', user);
      console.log('Forms page - isMyFormsView:', isMyFormsView);
      console.log('Forms page - isAdminUser:', isAdminUser);
    }
  }, [user, isMyFormsView, isAdminUser]);

  // Add real-time refresh listener
  useEffect(() => {
    const handleMessage = (event) => {
      if (event.data && event.data.type === 'FORM_SUBMITTED') {
        // Refresh data when a form is submitted
        refreshForms();
      }
    };

    // Handle route changes - refresh when returning to forms page
    const handleRouteChange = (url) => {
      if (url === '/forms' || url.startsWith('/forms?')) {
        console.log('Returning to forms page, refreshing data...');
        refreshForms(false);
      }
    };

    window.addEventListener('message', handleMessage);
    router.events.on('routeChangeComplete', handleRouteChange);

    // Auto-refresh every 30 seconds for real-time updates
    const interval = setInterval(() => {
      refreshForms(false); // Silent refresh
    }, 30000);

    return () => {
      window.removeEventListener('message', handleMessage);
      router.events.off('routeChangeComplete', handleRouteChange);
      clearInterval(interval);
    };
  }, [isMyFormsView, router]);

  const refreshForms = async (showLoading = true) => {
    try {
      if (showLoading) setIsLoading(true);

      const url = isMyFormsView ? '/api/forms?my=true' : '/api/forms';
      const [formsResponse, submissionsResponse] = await Promise.all([
        fetch(url),
        user ? fetch('/api/forms/submissions') : Promise.resolve({ ok: false })
      ]);

      if (formsResponse.ok) {
        let formData = await formsResponse.json();
        // Client-side audience filtering for non-admins
        if (user && user.role !== 'admin') {
          formData = formData.filter(form => {
            if (form.status !== 'published') return false;

            // Special handling for co-founders
            if (user.role === 'co_founder') {
              return form.audience === 'co_founders' || form.audience === 'all';
            }

            switch (form.audience) {
              case 'all':
                return true;
              case 'employee':
                return user.isEmployee || user.role === 'employee';
              case 'project_manager':
                return user.role === 'project_manager';
              case 'team_lead':
                return user.role === 'team_lead';
              case 'co_founders':
                return user.role === 'co_founder';
              case 'employee_to_pm':
                return user.isEmployee || user.role === 'employee';
              case 'pm_to_employee':
                return user.role === 'project_manager';
              default:
                return false;
            }
          });
        }
        setForms(formData);
      }

      if (submissionsResponse && submissionsResponse.ok) {
        const submissionsData = await submissionsResponse.json();
        // Ensure submissionsData is always an array
        setSubmissions(Array.isArray(submissionsData) ? submissionsData : []);
      } else {
        // If submissions fetch fails, ensure submissions remains an array
        setSubmissions(prevSubmissions => Array.isArray(prevSubmissions) ? prevSubmissions : []);
      }
    } catch (error) {
      console.error('Error refreshing forms:', error);
      // Ensure submissions remains an array even on error
      setSubmissions(prevSubmissions => Array.isArray(prevSubmissions) ? prevSubmissions : []);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteClick = (form) => {
    setFormToDelete(form);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (!formToDelete) return;

    try {
      setIsDeleting(true);
      const response = await fetch(`/api/forms/${formToDelete.id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        setForms(forms.filter(f => f.id !== formToDelete.id));
        toast.success('Form deleted successfully');
      } else {
        toast.error('Failed to delete form');
      }
    } catch (error) {
      console.error('Error deleting form:', error);
      toast.error('Error deleting form');
    } finally {
      setIsDeleting(false);
      setIsDeleteModalOpen(false);
      setFormToDelete(null);
    }
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const handleStatusFilterChange = (e) => {
    setStatusFilter(e.target.value);
  };

  const handleAudienceFilterChange = (e) => {
    setAudienceFilter(e.target.value);
  };

  const clearFilters = () => {
    setSearchQuery('');
    setStatusFilter('');
    setAudienceFilter('');
  };

  const filteredForms = forms.filter(form => {
    if (searchQuery) {
      if (!form.title?.toLowerCase().includes(searchQuery.toLowerCase()) &&
          !form.description?.toLowerCase().includes(searchQuery.toLowerCase())) {
        return false;
      }
    }
    if (statusFilter && form.status !== statusFilter) return false;
    if (audienceFilter && form.audience !== audienceFilter) return false;
    return true;
  });

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'published':
        return 'bg-green-100 text-green-800';
      case 'draft':
        return 'bg-gray-100 text-gray-800';
      case 'archived':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getAudienceLabel = (audience) => {
    switch (audience) {
      case 'all':
        return 'All Users';
      case 'employee':
        return 'Employees';
      case 'project_manager':
        return 'Project Managers';
      case 'team_lead':
        return 'Team Leads';
      case 'co_founders':
        return 'Co-Founders';
      case 'employee_to_pm':
        return 'Employee → PM';
      case 'pm_to_employee':
        return 'PM → Employee';
      default:
        return audience;
    }
  };

  const getPageTitle = () => {
    return isMyFormsView ? 'My Forms' : 'All Forms';
  };

  const getPageDescription = () => {
    return isMyFormsView ? 'Forms assigned to you' : 'Manage all forms in the system';
  };

  const showCreateButton = () => {
    return !isMyFormsView && user && user.role === 'admin';
  };

  const getFormSubmissionStatus = (form) => {
    // Ensure submissions is always an array before calling find
    if (!Array.isArray(submissions)) {
      console.warn('submissions is not an array:', submissions);
      return false;
    }

    const userSubmission = submissions.find(sub => 
      sub.form_id === form.id && 
      (sub.user_email?.toLowerCase() === user?.email?.toLowerCase() ||
       sub.filled_by_email?.toLowerCase() === user?.email?.toLowerCase())
    );
    return userSubmission?.status === 'completed';
  };

  const getStatusBadge = (status) => {
    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusBadgeClass(status)}`}>
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </span>
    );
  };

  const getAudienceBadge = (audience) => {
    const colors = {
      all: 'bg-blue-100 text-blue-800',
      employee: 'bg-indigo-100 text-indigo-800',
      project_manager: 'bg-purple-100 text-purple-800',
      team_lead: 'bg-yellow-100 text-yellow-800',
      co_founders: 'bg-red-100 text-red-800',
      employee_to_pm: 'bg-cyan-100 text-cyan-800',
      pm_to_employee: 'bg-pink-100 text-pink-800',
    };

    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${colors[audience] || 'bg-gray-100 text-gray-800'}`}>
        {getAudienceLabel(audience)}
      </span>
    );
  };

  const canUserFillForm = (form) => {
    if (!user) return false;

    switch (form.audience) {
      case 'all':
        return true;
      case 'employee':
        return user.isEmployee || user.role === 'employee';
      case 'project_manager':
        return user.role === 'project_manager';
      case 'team_lead':
        return user.role === 'team_lead';
      case 'co_founders':
        return user.role === 'co_founder';
      case 'employee_to_pm':
        return user.isEmployee || user.role === 'employee';
      case 'pm_to_employee':
        return user.role === 'project_manager';
      default:
        return false;
    }
  };

  const canUserEditForm = (form) => {
    return user && user.role === 'admin';
  };

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold">Forms</h1>
            {lastRefresh && (
              <div className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">
                Last updated: {new Date(lastRefresh).toLocaleTimeString()}
              </div>
            )}
          </div>
          <p className="text-gray-500">
            {isAdminUser ? 'Manage and view all forms' : 'View and fill available forms'}
          </p>
        </div>
        <div className="flex gap-2">
          {/* My Submissions Link for all users */}
          <Link href="/forms/submissions">
            <a>
              <Button variant="outline" className="flex items-center">
                <FiFileText className="mr-2" />
                My Submissions
              </Button>
            </a>
          </Link>

          {/* Admin only buttons */}
          {isAdminUser && (
            <>
              <Link href="/reports/forms">
                <a>
                  <Button variant="outline" className="flex items-center">
                    <FiFileText className="mr-2" />
                    Form Reports
                  </Button>
                </a>
              </Link>
              <Link href="/forms/new">
                <a>
                  <Button className="flex items-center">
                    <FiPlus className="mr-2" />
                    Create Form
                  </Button>
                </a>
              </Link>
            </>
          )}
        </div>
      </div>

      {/* Due Forms Notification - with refresh key */}
      <DueFormsNotification key={lastRefresh} user={user} />

      {/* Search and Filter Controls */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
        <div className="sm:col-span-2 relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
            <FiSearch />
          </div>
          <Input
            type="text"
            placeholder={isMyFormsView ? "Search my forms..." : "Search forms..."}
            value={searchQuery}
            onChange={handleSearchChange}
            className="pl-10"
          />
        </div>

        {!isMyFormsView && (
          <>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                <FiFilter />
              </div>
              <Select
                value={statusFilter}
                onChange={handleStatusFilterChange}
                className="pl-10"
              >
                <option value="">All Statuses</option>
                <option value="draft">Draft</option>
                <option value="published">Published</option>
                <option value="archived">Archived</option>
              </Select>
            </div>

            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                <FiUsers />
              </div>
              <Select
                value={audienceFilter}
                onChange={handleAudienceFilterChange}
                className="pl-10"
              >
                <option value="">All Audiences</option>
                <option value="employee">Employee</option>
                <option value="team_lead">Team Lead</option>
                <option value="project_manager">Project Manager</option>
                <option value="all">All</option>
              </Select>
            </div>
          </>
        )}
      </div>

      {/* Filter indicator */}
      {(searchQuery || statusFilter || audienceFilter) && (
        <div className="flex items-center bg-gray-100 px-4 py-2 rounded-md">
          <span className="text-sm text-gray-600 mr-2">Filters applied:</span>
          {searchQuery && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Search: &quot;{searchQuery}&quot;
              <button 
                onClick={() => setSearchQuery('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          {statusFilter && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Status: {statusFilter.charAt(0).toUpperCase() + statusFilter.slice(1)}
              <button 
                onClick={() => setStatusFilter('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          {audienceFilter && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Audience: {getAudienceLabel(audienceFilter)}
              <button 
                onClick={() => setAudienceFilter('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          <button 
            onClick={clearFilters}
            className="text-xs text-gray-500 hover:text-gray-700 ml-auto"
          >
            Clear all
          </button>
        </div>
      )}

      {/* Forms List */}
      {isLoading ? (
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
        </div>
      ) : forms.length === 0 ? (
        <EmptyState 
          title="No forms yet"
          description="Get started by creating your first score builder form"
          action={() => router.push('/forms/new')}
        />
      ) : filteredForms.length === 0 ? (
        <EmptyState 
          title="No matching forms"
          description="Try different search terms or filters"
          action={clearFilters}
          actionText="Clear Filters"
        />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredForms.map((form) => {
            const isCompleted = isMyFormsView ? getFormSubmissionStatus(form) : false;

            return (
              <Card key={form.id} className="h-full transition-all duration-300 hover:shadow-md hover:border-primary-200">
                <Card.Header>
                  <div className="flex justify-between items-start">
                    <div>
                      <Card.Title className="truncate">{form.title}</Card.Title>
                      <div className="flex gap-2 mt-2">
                        {getStatusBadge(form.status)}
                        {getAudienceBadge(form.audience)}
                        {isMyFormsView && (
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                            isCompleted ? 'bg-green-100 text-green-800' : 'bg-orange-100 text-orange-800'
                          }`}>
                            {isCompleted ? (
                              <>
                                <FiCheck className="mr-1 h-3 w-3" />
                                Completed
                              </>
                            ) : (
                              <>
                                <FiClock className="mr-1 h-3 w-3" />
                                Pending
                              </>
                            )}
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex space-x-1">
                      {isMyFormsView ? (
                        // Employee view - Show submission/preview actions
                        <>
                          <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => router.push(`/forms/${form.id}/preview`)}
                            className="h-7 w-7 p-0"
                            aria-label="Preview form"
                          >
                            <FiEye className="h-4 w-4" />
                          </Button>
                          {!isCompleted && (
                            <Button 
                              variant="ghost" 
                              size="sm" 
                              onClick={() => router.push(`/forms/${form.id}/submit`)}
                              className="h-7 w-7 p-0 text-blue-500 hover:text-blue-700 hover:bg-blue-50"
                              aria-label="Submit form"
                            >
                              <FiFileText className="h-4 w-4" />
                            </Button>
                          )}
                        </>
                      ) : (
                        // Non-employee view - Show appropriate actions based on role
                        <>
                          {user && (
                            <>
                              {/* Preview button for all users */}
                              <Button 
                                variant="ghost" 
                                size="sm" 
                                onClick={() => router.push(`/forms/${form.id}/preview`)}
                                className="h-7 w-7 p-0"
                                aria-label="Preview form"
                              >
                                <FiEye className="h-4 w-4" />
                              </Button>

                              {/* Submit button for non-admin users who can fill the form */}
                              {user.role !== 'admin' && canUserFillForm(form) && !getFormSubmissionStatus(form) && (
                                <Button 
                                  variant="ghost" 
                                  size="sm" 
                                  onClick={() => router.push(`/forms/${form.id}/submit`)}
                                  className="h-7 w-7 p-0 text-blue-500 hover:text-blue-700 hover:bg-blue-50"
                                  aria-label="Submit form"
                                >
                                  <FiFileText className="h-4 w-4" />
                                </Button>
                              )}

                              {/* Admin specific actions */}
                              {user.role === 'admin' && (
                                <>
                                  <Button 
                                    variant="ghost" 
                                    size="sm" 
