                  ) : (
                    !isMyFormsView && user && user.role === 'admin' && (
                      <div className="flex gap-2 w-full">
                        <Button 
                          variant="outline" 
                          size="sm" 
                          onClick={() => router.push(`/forms/${form.id}`)}
                          className="flex-1"
                        >
                          <FiEye className="mr-2 h-4 w-4" />
                          View Details
                        </Button>
                      </div>
                    )
                  )}
                </Card.Footer>
              </Card>
            );
          })}
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Form"
        description="Are you sure you want to delete this form? This action cannot be undone."
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsDeleteModalOpen(false)}
              disabled={isDeleting}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={confirmDelete}
              disabled={isDeleting}
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </Button>
          </>
        }
      >
        {formToDelete && (
          <div className="text-sm text-gray-500">
            <p>
              This will permanently delete the form 
              <span className="font-semibold text-gray-700"> &quot;{formToDelete.title}&quot; </span>
              and all associated questions and responses.
            </p>
          </div>
        )}
      </Modal>
    </div>
  );
}

export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getForms, getFormSubmissions } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    // Check if this is "my forms" view for employees
    const isMyFormsView = context.query.my === 'true';

    const [formsData, userSubmissions] = await Promise.all([
      getForms(),
      user ? getFormSubmissions() : Promise.resolve([])
    ]);

    let filteredForms = formsData;
    let userFormSubmissions = [];

    // Filter user's submissions if user exists
    if (user) {
      userFormSubmissions = userSubmissions.filter(submission => 
        submission.user_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.filled_by_email?.toLowerCase() === user.email?.toLowerCase()
      );

      // Filter forms based on user role and audience
      filteredForms = formsData.filter(form => {
        // Admins can see all forms
        if (user.role === 'admin') {
          return true;
        }

        // Co-founders can only see forms targeted to them or all users
        if (user.role === 'co_founder') {
          // Only show published forms to co-founders
          if (form.status !== 'published') return false;

          // Co-founders can only see forms with audience 'co_founders' or 'all'
          return form.audience === 'co_founders' || form.audience === 'all';
        }

        // Only show published forms to non-admin users
        if (form.status !== 'published') return false;

        // Handle different audience types
        switch (form.audience) {
          case 'all':
            return true;

          case 'employee':
            return user.role === 'employee';

          case 'project_manager':
            return user.role === 'project_manager';

          case 'team_lead':
            return user.role === 'team_lead';

          case 'co_founders':
            return user.role === 'co_founder';

          case 'employee_to_pm':
            // Only employees can see and fill this form initially
            // PMs will see it after employee submission in their submissions list
            return user.role === 'employee';

          case 'pm_to_employee':
            // Only PMs can see and fill this form initially  
            // Employees will see it after PM submission in their submissions list
            return user.role === 'project_manager';

          default:
            return false;
        }
      });
    }

    // Serialize dates
    const serializedForms = Array.isArray(filteredForms) ? filteredForms.map(form => ({
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null,
      start_date: form.start_date ? form.start_date.toISOString() : null
    })) : [];

    const serializedSubmissions = userFormSubmissions.map(submission => ({
      ...submission,
      submitted_at: submission.submitted_at ? submission.submitted_at.toISOString() : null,
      created_at: submission.created_at ? submission.created_at.toISOString() : null,
      updated_at: submission.updated_at ? submission.updated_at.toISOString() : null
    }));

    return {
      props: {
        initialForms: serializedForms,
        userSubmissions: serializedSubmissions,
        user: user,
        isMyFormsView: isMyFormsView
      }
    };
  } catch (error) {
    console.error('Error fetching forms:', error);
    return {
      props: {
        initialForms: [],
        userSubmissions: [],
        user: null,
        isMyFormsView: false
      }
    };
  }
}

