export async function getServerSideProps(context) {
  const { id } = context.params;

  // Import database functions only on server-side
  const { getFormSubmissionById, getFormById, getEmployees } = require('../../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    if (!cookies.user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    const user = JSON.parse(cookies.user);

    const [submission, employees] = await Promise.all([
      getFormSubmissionById(id),
      getEmployees()
    ]);

    if (!submission) {
      return {
        notFound: true,
      };
    }

    // Get the form details
    const form = await getFormById(submission.form_id);

    // Check if user has permission to view this submission
    const currentEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());

    let hasPermission = false;

    // Admins can see all submissions
    if (user.role === 'admin' || user.role === 'co_founder') {
      hasPermission = true;
    } else {
      // Check if user is involved in this submission
      const isSubmitter = 
        submission.user_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.filled_by_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.filled_by_id === currentEmployee?.id;

      const isTarget = 
        submission.filled_for_email?.toLowerCase() === user.email?.toLowerCase() ||
        submission.filled_for_id === currentEmployee?.id;

      hasPermission = isSubmitter || isTarget;
    }

    if (!hasPermission) {
      return {
        redirect: {
          destination: '/forms/submissions',
          permanent: false,
        },
      };
    }

    // Serialize dates
    const serializedSubmission = {
      ...submission,
      submitted_at: submission.submitted_at ? submission.submitted_at.toISOString() : null,
      created_at: submission.created_at ? submission.created_at.toISOString() : null,
      updated_at: submission.updated_at ? submission.updated_at.toISOString() : null,
      next_due_date: submission.next_due_date ? submission.next_due_date.toISOString() : null,
    };

    const serializedForm = form ? {
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null,
      start_date: form.start_date ? form.start_date.toISOString() : null,
    } : null;

    return {
      props: {
        submission: serializedSubmission,
        form: serializedForm,
        user: user,
        isAdmin: user.role === 'admin' || user.role === 'co_founder'
      }
    };
  } catch (error) {
    console.error('Error fetching submission details:', error);
    return {
      notFound: true,
    };
  }
}

