export async function getServerSideProps(context) {
  const { id } = context.params;

  // Import database functions only on server-side
  const { getFormById, getEmployees, getFormSubmissions } = require('../../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    if (!cookies.user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    const user = JSON.parse(cookies.user);
    const [form, employees, allSubmissions] = await Promise.all([
      getFormById(id),
      getEmployees(),
      getFormSubmissions()
    ]);

    if (!form) {
      return {
        notFound: true,
      };
    }

    // Check if form is published and available to this user
    let isFormAvailable = false;
    if (form.status === 'published') {
      switch (form.audience) {
        case 'all':
          isFormAvailable = true;
          break;
        case 'employee':
          isFormAvailable = user.isEmployee || user.role === 'employee';
          break;
        case 'team_lead':
          isFormAvailable = user.role === 'team_lead';
          break;
        case 'project_manager':
          isFormAvailable = user.role === 'project_manager';
          break;
        case 'co_founders':
          isFormAvailable = user.role === 'co_founder';
          break;
        case 'employee_to_pm':
          // Employees can fill forms targeted at PMs
          isFormAvailable = user.isEmployee || user.role === 'employee';
          break;
        case 'pm_to_employee':
          // Project managers can fill forms targeted at employees
          isFormAvailable = user.role === 'project_manager';
          break;
        default:
          isFormAvailable = false;
      }
    }

    if (!isFormAvailable) {
      return {
        redirect: {
          destination: '/forms',
          permanent: false,
        },
      };
    }

    // Find the current user's employee record
    const currentEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());

    // Check for existing submissions by this user for this form
    const currentMonth = new Date().getMonth() + 1;
    const currentYear = new Date().getFullYear();

    const existingSubmissions = allSubmissions.filter(submission => {
      return submission.form_id === form.id && 
             submission.filled_by_id === currentEmployee?.id;
    });

    // For one-time forms, check if any submission exists
    let hasExistingSubmission = false;
    let existingSubmissionDetails = null;

    if (form.frequency === 'once') {
      const oneTimeSubmission = existingSubmissions.find(submission => 
        submission.filled_by_id === currentEmployee?.id
      );
      if (oneTimeSubmission) {
        hasExistingSubmission = true;
        existingSubmissionDetails = oneTimeSubmission;
      }
    } else {
      // For recurring forms, check for current month/year
      const monthlySubmission = existingSubmissions.find(submission => 
        submission.filled_by_id === currentEmployee?.id &&
        submission.submission_month === currentMonth &&
        submission.submission_year === currentYear
      );
      if (monthlySubmission) {
        hasExistingSubmission = true;
        existingSubmissionDetails = monthlySubmission;
      }
    }

    // Serialize dates and add form details
    const serializedForm = {
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null,
      start_date: form.start_date ? form.start_date.toISOString() : null,
      questions: form.questions || []
    };

    // Serialize employees
    const serializedEmployees = employees.map(emp => ({
      ...emp,
      created_at: emp.created_at ? emp.created_at.toISOString() : null,
      updated_at: emp.updated_at ? emp.updated_at.toISOString() : null
    }));

    // Serialize existing submission if any
    const serializedExistingSubmission = existingSubmissionDetails ? {
      ...existingSubmissionDetails,
      submitted_at: existingSubmissionDetails.submitted_at ? existingSubmissionDetails.submitted_at.toISOString() : null,
      created_at: existingSubmissionDetails.created_at ? existingSubmissionDetails.created_at.toISOString() : null,
      updated_at: existingSubmissionDetails.updated_at ? existingSubmissionDetails.updated_at.toISOString() : null
    } : null;

    return {
      props: {
        form: serializedForm,
        user: user,
        currentEmployee: currentEmployee ? {
          ...currentEmployee,
          created_at: currentEmployee.created_at ? currentEmployee.created_at.toISOString() : null,
          updated_at: currentEmployee.updated_at ? currentEmployee.updated_at.toISOString() : null
        } : null,
        allEmployees: serializedEmployees,
        hasExistingSubmission: hasExistingSubmission,
        existingSubmission: serializedExistingSubmission
      }
    };
  } catch (error) {
    console.error('Error fetching form:', error);
    return {
      notFound: true,
    };
  }
}

