  // Set default values based on form audience
  useEffect(() => {
    if (form.audience === 'employee_to_pm' || form.audience === 'pm_to_employee') {
      // For directional forms, set appropriate defaults
      setFilledBy(currentEmployee);
      // Don't set filledFor automatically - let user select
    } else {
      // For general forms, set both to current employee by default
      setFilledBy(currentEmployee);
      setFilledFor(currentEmployee);
    }
  }, [form.audience, currentEmployee]);

  const handleInputChange = (questionId, value) => {
    setFormData(prev => ({
      ...prev,
      [questionId]: value
    }));
  };

  const validateForm = () => {
    // Validate employee selection
    if (!filledBy) {
      toast.error('Please select who is filling this form');
      return false;
    }

    if (!filledFor) {
      toast.error('Please select for whom this form is being filled');
      return false;
    }

    // Validate questions
    const questions = form.questions || [];
    const requiredQuestions = questions.filter(q => q.required);

    for (const question of requiredQuestions) {
      if (!formData[question.id] || formData[question.id].toString().trim() === '') {
        toast.error(`Please answer: ${question.question || question.title}`);
        return false;
      }
    }
    return true;
  };

  const calculateScore = () => {
    const questions = form.questions || [];
    let totalScore = 0;
    let maxScore = 0;

    questions.forEach(question => {
      if (question.type === 'rating' || question.type === 'scale') {
        const answer = parseInt(formData[question.id]) || 0;
        const questionMaxScore = question.max_score || 5;

        totalScore += answer;
        maxScore += questionMaxScore;
      }
    });

    return { totalScore, maxScore };
  };

  const handleSubmit = async () => {
    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const { totalScore, maxScore } = calculateScore();

      const submissionData = {
        form_id: form.id,
        user_id: user.id,
        user_email: user.email,
        employee_id: filledFor.id,
        employee_name: filledFor.name,
        department_id: filledFor.department_id || null,
        department_name: filledFor.departments?.[0]?.name || null,
        answers: formData,
        total_score: totalScore,
        max_possible_score: maxScore,
        status: 'completed',
        submission_month: new Date().getMonth() + 1,
        submission_year: new Date().getFullYear(),
        form_frequency: form.frequency,
        // New fields
        filled_by_id: filledBy.id,
        filled_by_email: filledBy.email,
        filled_by_name: filledBy.name,
        filled_for_id: filledFor.id,
        filled_for_email: filledFor.email,
        filled_for_name: filledFor.name
      };

      const response = await fetch('/api/forms/submit', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(submissionData),
      });

      if (response.ok) {
        toast.success('Form submitted successfully!');

        // Trigger real-time updates
        try {
          // Check for due forms update
          await fetch('/api/forms/check-due', { method: 'POST' });

          // Trigger dashboard refresh if possible
          if (window.opener && !window.opener.closed) {
            window.opener.postMessage({ type: 'FORM_SUBMITTED' }, '*');
          }
        } catch (error) {
          console.log('Could not trigger real-time updates:', error);
        }

        router.push('/forms/submissions');
      } else {
        const errorData = await response.json();
        toast.error(errorData.message || 'Failed to submit form');
      }
    } catch (error) {
      console.error('Error submitting form:', error);
      toast.error('Failed to submit form');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getOptionText = (option) => {
    if (typeof option === 'string') {
      return option;
    }
    if (typeof option === 'object' && option !== null) {
      return option.label || option.text || option.value || '';
    }
    return '';
  };

  const getOptionValue = (option) => {
    if (typeof option === 'string') {
      return option;
    }
    if (typeof option === 'object' && option !== null) {
      return option.value || option.label || option.text || '';
    }
    return '';
  };

  const renderQuestion = (question, index) => {
    const questionId = question.id || `question_${index}`;
    const value = formData[questionId] || '';

    switch (question.type) {
      case 'text':
      case 'short_text':
        return (
          <Input
            key={questionId}
            value={value}
            onChange={(e) => handleInputChange(questionId, e.target.value)}
            placeholder="Your answer..."
            required={question.required}
          />
        );

      case 'textarea':
      case 'long_text':
        return (
          <Textarea
            key={questionId}
            value={value}
            onChange={(e) => handleInputChange(questionId, e.target.value)}
            placeholder="Your answer..."
            rows={4}
            required={question.required}
          />
        );

      case 'rating':
      case 'scale':
        const maxRating = question.max_score || 5;
        return (
          <div key={questionId} className="flex items-center space-x-2">
            <span className="text-sm text-gray-500">1</span>
            <div className="flex space-x-1">
              {[...Array(maxRating)].map((_, i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => handleInputChange(questionId, i + 1)}
                  className={`w-8 h-8 rounded-full border-2 flex items-center justify-center text-sm font-medium transition-colors ${
                    parseInt(value) > i
                      ? 'bg-blue-500 border-blue-500 text-white'
                      : 'border-gray-300 text-gray-400 hover:border-blue-300'
                  }`}
                >
                  {i + 1}
                </button>
              ))}
            </div>
            <span className="text-sm text-gray-500">{maxRating}</span>
            {value && (
              <span className="text-sm font-medium text-blue-600 ml-2">
                Score: {value}/{maxRating}
              </span>
            )}
          </div>
        );

      case 'select':
      case 'dropdown':
        return (
          <Select
            key={questionId}
            value={value}
            onChange={(e) => handleInputChange(questionId, e.target.value)}
            required={question.required}
          >
            <option value="">Select an option...</option>
            {question.options?.map((option, optionIndex) => (
              <option key={optionIndex} value={getOptionValue(option)}>
                {getOptionText(option)}
              </option>
            ))}
          </Select>
        );

      case 'radio':
        return (
          <div key={questionId} className="space-y-2">
            {question.options?.map((option, optionIndex) => {
              const optionValue = getOptionValue(option);
              const optionText = getOptionText(option);

              return (
                <label key={optionIndex} className="flex items-center">
                  <input
                    type="radio"
                    name={questionId}
                    value={optionValue}
                    checked={value === optionValue}
                    onChange={(e) => handleInputChange(questionId, e.target.value)}
                    className="mr-2"
                    required={question.required}
                  />
                  <span className="text-sm">{optionText}</span>
                </label>
              );
            })}
          </div>
        );

      case 'checkbox':
        return (
          <div key={questionId} className="space-y-2">
            {question.options?.map((option, optionIndex) => {
              const optionValue = getOptionValue(option);
              const optionText = getOptionText(option);
              const currentValues = Array.isArray(value) ? value : (value ? [value] : []);

              return (
                <label key={optionIndex} className="flex items-center">
                  <input
                    type="checkbox"
                    checked={currentValues.includes(optionValue)}
                    onChange={(e) => {
                      let newValues;
                      if (e.target.checked) {
                        newValues = [...currentValues, optionValue];
                      } else {
                        newValues = currentValues.filter(v => v !== optionValue);
                      }
                      handleInputChange(questionId, newValues);
                    }}
                    className="mr-2"
                  />
                  <span className="text-sm">{optionText}</span>
                </label>
              );
            })}
          </div>
        );

      default:
        return (
          <Input
            key={questionId}
            value={value}
            onChange={(e) => handleInputChange(questionId, e.target.value)}
            placeholder="Your answer..."
            required={question.required}
          />
        );
    }
  };

  const questions = form.questions || [];

  return (
    <div className="max-w-4xl mx-auto space-y-6 fade-in">
      <div className="flex items-center justify-between">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.back()}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Forms
          </Button>
          <h1 className="text-2xl font-bold">{form.title}</h1>
          <p className="text-gray-500">Complete and submit this form</p>
        </div>
        <div className="flex items-center space-x-2 text-sm text-gray-500">
          <FiFileText />
          <span>{questions.length} questions</span>
        </div>
      </div>

      {/* Form Info */}
      <Card>
        <Card.Content className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="flex items-center">
              <FiUser className="mr-2 text-gray-400" />
              <div>
                <p className="text-sm text-gray-500">Submitting as</p>
                <p className="font-medium">{filledBy?.name || user.name}</p>
              </div>
            </div>
            <div className="flex items-center">
              <FiCalendar className="mr-2 text-gray-400" />
              <div>
                <p className="text-sm text-gray-500">Submission Date</p>
                <p className="font-medium">{new Date().toLocaleDateString()}</p>
              </div>
            </div>
            <div className="flex items-center">
              <FiCheckCircle className="mr-2 text-gray-400" />
              <div>
                <p className="text-sm text-gray-500">Audience</p>
                <p className="font-medium capitalize">{form.audience?.replace('_', ' ')}</p>
              </div>
            </div>
          </div>
          {form.description && (
            <div className="mt-4 pt-4 border-t">
              <p className="text-gray-700">{form.description}</p>
            </div>
          )}
        </Card.Content>
      </Card>

      {/* Employee Selection - Required for all forms */}
      <Card allowDropdown={true}>
        <Card.Header>
          <Card.Title>Form Submission Details</Card.Title>
          <Card.Description>
            Please specify who is filling this form and for whom it is being filled.
          </Card.Description>
        </Card.Header>
        <Card.Content className="p-6" allowDropdown={true}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <EmployeeSelector
              value={filledBy}
              onChange={setFilledBy}
              label="Who is filling this form?"
              placeholder="Search and select employee who is filling..."
              required={true}
              employees={allEmployees || []}
            />
            <EmployeeSelector
              value={filledFor}
              onChange={setFilledFor}
              label="For whom is this form being filled?"
              placeholder="Search and select employee for whom this is filled..."
              required={true}
              employees={allEmployees || []}
            />
          </div>

          {/* Debug information for development */}
          {process.env.NODE_ENV === 'development' && (
            <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-md">
              <p className="text-xs text-yellow-800">
                Debug: {allEmployees?.length || 0} employees loaded | Current user: {user?.email} | Role: {user?.role}
              </p>
            </div>
          )}

          {/* Show helpful text based on form audience */}
          {form.audience === 'employee_to_pm' && (
            <div className="mt-4 p-4 bg-blue-50 border border-blue-200 rounded-md">
              <p className="text-sm text-blue-700">
                <strong>Note:</strong> This form is designed for employees to evaluate project managers. 
                Please ensure you&apos;re filling it for the appropriate PM.
              </p>
            </div>
          )}

          {form.audience === 'pm_to_employee' && (
            <div className="mt-4 p-4 bg-green-50 border border-green-200 rounded-md">
              <p className="text-sm text-green-700">
                <strong>Note:</strong> This form is designed for project managers to evaluate employees. 
                Please ensure you&apos;re filling it for the appropriate employee.
              </p>
            </div>
          )}
        </Card.Content>
      </Card>

      {/* Questions */}
      {questions.length === 0 ? (
        <Card>
          <Card.Content className="p-6 text-center">
            <FiFileText className="mx-auto h-12 w-12 text-gray-400 mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No Questions Available</h3>
            <p className="text-gray-500">This form doesn&apos;t have any questions yet.</p>
          </Card.Content>
        </Card>
      ) : (
        <Card>
          <Card.Header>
            <Card.Title>Form Questions</Card.Title>
            <Card.Description>
              Please answer all required questions marked with *
            </Card.Description>
          </Card.Header>
          <Card.Content className="p-6">
            <div className="space-y-6">
              {questions.map((question, index) => (
                <div key={question.id || index} className="space-y-2">
                  <Label className="text-base font-medium">
                    {index + 1}. {question.question || question.title}
                    {question.required && <span className="text-red-500 ml-1">*</span>}
                  </Label>
                  {question.description && (
                    <p className="text-sm text-gray-600">{question.description}</p>
                  )}
                  {renderQuestion(question, index)}
                </div>
              ))}
            </div>
          </Card.Content>
        </Card>
      )}

      {/* Submit Section */}
      <Card>
        <Card.Content className="p-6">
          {hasExistingSubmission ? (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="font-medium text-gray-900 flex items-center">
                    <FiCheckCircle className="mr-2 text-green-500" />
                    Form Already Submitted
                  </h3>
                  <p className="text-sm text-gray-500">
                    {form.frequency === 'once' 
                      ? 'This form can only be submitted once and you have already completed it.'.replace('once', 'once').replace('you have', 'you have')
                      : `You have already submitted this form for ${new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}.`.replace('You have', 'You have')
                    }
                  </p>
                </div>
                <div className="flex space-x-2">
                  <Button
                    variant="outline"
                    onClick={() => router.push('/forms/submissions')}
                  >
                    View Submissions
                  </Button>
                  <Button
                    variant="outline"
                    onClick={() => router.back()}
                  >
                    Back to Forms
                  </Button>
                </div>
              </div>

              {existingSubmission && (
                <div className="mt-4 p-4 bg-green-50 border border-green-200 rounded-md">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="font-medium text-green-800">Submission Details:</p>
                      <p className="text-green-700">Status: <span className="capitalize">{existingSubmission.status}</span></p>
                      <p className="text-green-700">Submitted: {new Date(existingSubmission.submitted_at).toLocaleDateString()}</p>
                    </div>
                    <div>
                      <p className="font-medium text-green-800">Form Details:</p>
                      <p className="text-green-700">Filled by: {existingSubmission.filled_by_name}</p>
                      <p className="text-green-700">For: {existingSubmission.filled_for_name}</p>
                      {existingSubmission.total_score !== null && (
                        <p className="text-green-700">Score: {existingSubmission.total_score}/{existingSubmission.max_possible_score}</p>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-center justify-between">
              <div>
                <h3 className="font-medium text-gray-900">Ready to Submit?</h3>
                <p className="text-sm text-gray-500">
                  Please review your answers before submitting. You cannot edit after submission.
                  {form.frequency !== 'once' && (
                    <span className="block mt-1 text-blue-600">
                      Note: This form can be submitted {form.frequency === 'monthly' ? 'once per month' : `${form.frequency}ly`}.
                    </span>
                  )}
                </p>
              </div>
              <div className="flex space-x-2">
                <Button
                  variant="outline"
                  onClick={() => router.back()}
                >
                  Cancel
                </Button>
                <Button
                  onClick={handleSubmit}
                  disabled={isSubmitting || questions.length === 0 || hasExistingSubmission}
                  className="min-w-[120px]"
                >
                  {isSubmitting ? (
                    <>
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                      Submitting...
                    </>
                  ) : (
                    <>
                      <FiSend className="mr-2" />
                      Submit Form
                    </>
                  )}
                </Button>
              </div>
            </div>
          )}
        </Card.Content>
      </Card>
    </div>
  );
}

