import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { FiArrowLeft, FiSave, FiList, FiAlertCircle } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { isSupabaseConfigured, supabase } from '../../../lib/supabase-client';

export default function FormScoreSettings() {
  const [form, setForm] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [categories, setCategories] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [newCategory, setNewCategory] = useState({ name: '', description: '', weight: 1 });

  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      fetchFormData();
    }
  }, [id]);

  const fetchFormData = async () => {
    try {
      setIsLoading(true);

      if (isSupabaseConfigured()) {
        // Fetch form data from Supabase
        const { data: formData, error: formError } = await supabase
          .from('score_forms')
          .select('*')
          .eq('id', id)
          .single();

        if (formError) throw formError;

        // Fetch questions
        const { data: questionsData, error: questionsError } = await supabase
          .from('form_questions')
          .select('*')
          .eq('form_id', id)
          .order('order_number');

        if (questionsError) throw questionsError;

        // Fetch categories
        const { data: categoriesData, error: categoriesError } = await supabase
          .from('score_categories')
          .select('*')
          .eq('form_id', id);

        if (categoriesError) throw categoriesError;

        setForm(formData);
        setQuestions(questionsData.map(q => ({
          ...q,
          category_id: q.category_id || '',
          max_score: q.max_score || 5,
          score_weight: q.score_weight || 1
        })));
        setCategories(categoriesData);
      } else {
        // Mock data for demo
        const mockForm = {
          id: id,
          title: 'Employee Performance Review',
          description: 'Quarterly performance evaluation form',
          status: 'published'
        };

        const mockQuestions = [
          {
            id: 'q1',
            question_text: 'How would you rate your overall performance?',
            question_type: 'linear_scale',
            is_required: true,
            order_number: 0,
            category_id: '',
            max_score: 5,
            score_weight: 1
          },
          {
            id: 'q2',
            question_text: 'What skills have you improved in the last quarter?',
            question_type: 'multiple_choice',
            is_required: true,
            order_number: 1,
            category_id: '',
            max_score: 5,
            score_weight: 2
          },
          {
            id: 'q3',
            question_text: 'What are your goals for the next quarter?',
            question_type: 'long_text',
            is_required: false,
            order_number: 2,
            category_id: '',
            max_score: 5,
            score_weight: 1
          }
        ];

        const mockCategories = [
          {
            id: 'cat1',
            form_id: id,
            name: 'Technical Skills',
            description: 'Assessment of technical abilities and competencies',
            weight: 3
          },
          {
            id: 'cat2',
            form_id: id,
            name: 'Communication',
            description: 'Assessment of communication skills and effectiveness',
            weight: 2
          },
          {
            id: 'cat3',
            form_id: id,
            name: 'Teamwork',
            description: 'Assessment of collaboration and team contributions',
            weight: 2
          }
        ];

        setForm(mockForm);
        setQuestions(mockQuestions);
        setCategories(mockCategories);
      }
    } catch (error) {
      console.error('Error fetching form data:', error);
      toast.error('Failed to load form data');
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuestionChange = (questionId, field, value) => {
    setQuestions(prev => 
      prev.map(q => 
        q.id === questionId 
          ? { ...q, [field]: value } 
          : q
      )
    );
  };

  const handleCategoryChange = (categoryId, field, value) => {
    setCategories(prev => 
      prev.map(c => 
        c.id === categoryId 
          ? { ...c, [field]: value } 
          : c
      )
    );
  };

  const handleAddCategory = async () => {
    if (!newCategory.name.trim()) {
      toast.error('Category name is required');
      return;
    }

    try {
      if (isSupabaseConfigured()) {
        const { data, error } = await supabase
          .from('score_categories')
          .insert([
            { 
              form_id: id,
              name: newCategory.name,
              description: newCategory.description,
              weight: parseInt(newCategory.weight) || 1
            }
          ])
          .select()
          .single();

        if (error) throw error;

        setCategories(prev => [...prev, data]);
      } else {
        // Mock for demo
        const newCat = {
          id: `cat${Math.random().toString(36).substring(2, 9)}`,
          form_id: id,
          name: newCategory.name,
          description: newCategory.description,
          weight: parseInt(newCategory.weight) || 1
        };

        setCategories(prev => [...prev, newCat]);
      }

      setNewCategory({ name: '', description: '', weight: 1 });
      toast.success('Category added successfully');
    } catch (error) {
      console.error('Error adding category:', error);
      toast.error('Failed to add category');
    }
  };

  const handleSave = async () => {
    setIsSaving(true);

    try {
      if (isSupabaseConfigured()) {
        // Update questions with scoring settings
        const updates = questions.map(q => ({
          id: q.id,
          category_id: q.category_id || null,
          max_score: parseInt(q.max_score) || 5,
          score_weight: parseInt(q.score_weight) || 1
        }));

        const { error } = await supabase
          .from('form_questions')
          .upsert(updates);

        if (error) throw error;

        // Update categories
        const categoryUpdates = categories.map(c => ({
          id: c.id,
          name: c.name,
          description: c.description,
          weight: parseInt(c.weight) || 1
        }));

        const { error: categoryError } = await supabase
          .from('score_categories')
          .upsert(categoryUpdates);

        if (categoryError) throw categoryError;
      }

      toast.success('Score settings saved successfully');
      router.push(`/forms/${id}`);
    } catch (error) {
      console.error('Error saving score settings:', error);
      toast.error('Failed to save score settings');
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto fade-in pb-12">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push(`/forms/${id}`)}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Form
        </Button>
        <h1 className="text-2xl font-bold">Score Settings: {form?.title}</h1>
        <p className="text-gray-500">Configure how questions are scored and categorized for reports</p>
      </div>

      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-6">
        <div className="flex items-start">
          <FiAlertCircle className="text-yellow-500 mt-1 mr-3 flex-shrink-0" />
          <div>
            <h3 className="font-medium text-yellow-800">Scoring Configuration</h3>
