                      Description
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Weight
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {categories.map((category) => (
                    <tr key={category.id}>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <Input
                          value={category.name}
                          onChange={(e) => handleCategoryChange(category.id, 'name', e.target.value)}
                          className="border-none hover:border hover:border-gray-300 focus:border-primary-500"
                        />
                      </td>
                      <td className="px-6 py-4">
                        <Input
                          value={category.description}
                          onChange={(e) => handleCategoryChange(category.id, 'description', e.target.value)}
                          className="border-none hover:border hover:border-gray-300 focus:border-primary-500"
                        />
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <Input
                          type="number"
                          min="1"
                          max="5"
                          value={category.weight}
                          onChange={(e) => handleCategoryChange(category.id, 'weight', e.target.value)}
                          className="w-20 border-none hover:border hover:border-gray-300 focus:border-primary-500"
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="text-center py-4 text-gray-500">No categories defined yet.</div>
          )}
        </Card.Content>
      </Card>

      {/* Questions Scoring Section */}
      <Card>
        <Card.Header>
          <Card.Title>Question Scoring</Card.Title>
          <Card.Description>
            Configure how each question contributes to the overall score
          </Card.Description>
        </Card.Header>
        <Card.Content>
          {questions.length > 0 ? (
            <div className="border rounded-md overflow-hidden">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Question
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Category
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Max Score
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Weight
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {questions.map((question) => (
                    <tr key={question.id}>
                      <td className="px-6 py-4">
                        <div className="font-medium text-gray-900">{question.question_text}</div>
                        <div className="text-xs text-gray-500">{question.question_type}</div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <Select
                          value={question.category_id}
                          onChange={(e) => handleQuestionChange(question.id, 'category_id', e.target.value)}
                        >
                          <option value="">No Category</option>
                          {categories.map(cat => (
                            <option key={cat.id} value={cat.id}>
                              {cat.name}
                            </option>
                          ))}
                        </Select>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <Input
                          type="number"
                          min="1"
                          max="10"
                          value={question.max_score}
                          onChange={(e) => handleQuestionChange(question.id, 'max_score', e.target.value)}
                          className="w-20"
                        />
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <Input
                          type="number"
                          min="1"
                          max="5"
                          value={question.score_weight}
                          onChange={(e) => handleQuestionChange(question.id, 'score_weight', e.target.value)}
                          className="w-20"
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="text-center py-8 text-gray-500">
              <p>This form has no questions yet.</p>
              <Link href={`/forms/${id}/edit`}>
                <a className="mt-4 inline-flex items-center text-primary-600 hover:text-primary-700">
                  <FiList className="mr-2" />
                  Add questions to your form
                </a>
              </Link>
            </div>
          )}
        </Card.Content>
        <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
          <Button
            variant="outline"
            onClick={() => router.push(`/forms/${id}`)}
            disabled={isSaving}
          >
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            disabled={isSaving || questions.length === 0}
            className="flex items-center"
          >
            <FiSave className="mr-2" />
            {isSaving ? 'Saving...' : 'Save Score Settings'}
          </Button>
        </Card.Footer>
      </Card>
    </div>
  );
}

