import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave, FiPlus, FiTrash2, FiEye, FiCheck, FiEdit2 } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { Modal } from '../../../components/Modal';

export default function EditForm() {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    frequency: 'once',
    audience: 'all',
    status: 'draft',
    start_date: ''
  });

  const [questions, setQuestions] = useState([]);
  const [deletedQuestionIds, setDeletedQuestionIds] = useState([]);
  const [currentQuestion, setCurrentQuestion] = useState({
    id: null,
    question_text: '',
    question_type: 'short_text',
    is_required: false,
    options: []
  });

  const [originalQuestions, setOriginalQuestions] = useState([]);
  const [isAddingQuestion, setIsAddingQuestion] = useState(false);
  const [editingQuestionIndex, setEditingQuestionIndex] = useState(null);
  const [currentOption, setCurrentOption] = useState('');
  const [isPreviewModalOpen, setIsPreviewModalOpen] = useState(false);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const router = useRouter();
  const { id } = router.query;

  const questionTypes = [
    { value: 'short_text', label: 'Short Text' },
    { value: 'long_text', label: 'Long Text' },
    { value: 'multiple_choice', label: 'Multiple Choice' },
    { value: 'checkbox', label: 'Checkboxes' },
    { value: 'dropdown', label: 'Dropdown' },
    { value: 'linear_scale', label: 'Linear Scale' },
    { value: 'date', label: 'Date' },
    { value: 'time', label: 'Time' }
  ];

  const frequencies = [
    { value: 'once', label: 'Once' },
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'biweekly', label: 'Bi-weekly' },
    { value: 'monthly', label: 'Monthly' },
    { value: 'quarterly', label: 'Quarterly' },
    { value: 'yearly', label: 'Yearly' }
  ];

  const audiences = [
    { value: 'employee', label: 'Employee' },
    { value: 'team_lead', label: 'Team Lead' },
    { value: 'project_manager', label: 'Project Manager' },
    { value: 'co_founders', label: 'Co-founders' },
    { value: 'all', label: 'All' }
  ];

  useEffect(() => {
    if (id) {
      fetchFormData();
    }
  }, [id]);

  const fetchFormData = async () => {
    try {
      setIsLoading(true);

      // Fetch actual form data from API
      const response = await fetch(`/api/forms/${id}`);
      if (!response.ok) {
        throw new Error('Failed to fetch form data');
      }

      const formData = await response.json();

      // Set form basic data
      setFormData({
        title: formData.title || '',
        description: formData.description || '',
        frequency: formData.frequency || 'once',
        audience: formData.audience || 'all',
        status: formData.status || 'draft',
        start_date: formData.start_date || ''
      });

      // Set questions data - properly map API fields to component fields
      const questionsData = (formData.questions || []).map(question => ({
        id: question.id,
        question_text: question.title || question.question || question.question_text,
        question_type: question.type || question.question_type,
        is_required: question.required || question.is_required || false,
        options: question.options || []
      }));

      setQuestions(questionsData);
      setOriginalQuestions(JSON.parse(JSON.stringify(questionsData)));

      setIsLoading(false);
    } catch (error) {
      console.error('Error fetching form data:', error);
      toast.error('Failed to load form data');
      setIsLoading(false);
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.title.trim()) {
      newErrors.title = 'Form title is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const validateQuestion = () => {
    const newErrors = {};

    if (!currentQuestion.question_text.trim()) {
      newErrors.question_text = 'Question text is required';
    }

    if (['multiple_choice', 'checkbox', 'dropdown'].includes(currentQuestion.question_type) && 
        currentQuestion.options.length < 2) {
      newErrors.options = 'At least two options are required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleQuestionChange = (e) => {
    const { name, value, type, checked } = e.target;
    const val = type === 'checkbox' ? checked : value;

    setCurrentQuestion(prev => ({ 
      ...prev, 
      [name]: val,
      // Reset options if changing from a type with options to one without
      ...(name === 'question_type' && 
        !['multiple_choice', 'checkbox', 'dropdown'].includes(value) && 
        { options: [] })
    }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleOptionChange = (e) => {
    setCurrentOption(e.target.value);
  };

  const addOption = () => {
    if (!currentOption.trim()) return;

    setCurrentQuestion(prev => ({
      ...prev,
      options: [...prev.options, currentOption.trim()]
    }));

    setCurrentOption('');

    // Clear option error if it exists
    if (errors.options) {
      setErrors(prev => ({ ...prev, options: undefined }));
    }
  };

  const removeOption = (index) => {
    setCurrentQuestion(prev => ({
      ...prev,
      options: prev.options.filter((_, i) => i !== index)
    }));
  };

  const addQuestion = () => {
    if (!validateQuestion()) return;

    if (editingQuestionIndex !== null) {
      // Update existing question
      setQuestions(prev => prev.map((q, i) => 
        i === editingQuestionIndex ? { ...currentQuestion } : q
      ));
      setEditingQuestionIndex(null);
    } else {
      // Add new question
      setQuestions(prev => [...prev, { ...currentQuestion }]);
    }

    // Reset current question
    setCurrentQuestion({
      id: null,
      question_text: '',
      question_type: 'short_text',
      is_required: false,
      options: []
    });

    setIsAddingQuestion(false);
  };

  const editQuestion = (index) => {
    setCurrentQuestion({ ...questions[index] });
    setEditingQuestionIndex(index);
    setIsAddingQuestion(true);

    // Scroll to the question being edited
    const questionElement = document.getElementById(`question-${index}`);
    if (questionElement) {
      questionElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  const removeQuestion = (index) => {
    const questionToRemove = questions[index];

    // If the question has an ID (exists in the database), add it to deletedQuestionIds
    if (questionToRemove.id) {
      setDeletedQuestionIds(prev => [...prev, questionToRemove.id]);
    }

    setQuestions(prev => prev.filter((_, i) => i !== index));
  };

  const saveForm = async (status = null) => {
    if (!validateForm()) return;

    setIsSubmitting(true);

    try {
      // Update form basic info
      const formUpdateData = {
        title: formData.title,
        description: formData.description,
        frequency: formData.frequency,
        audience: formData.audience,
        status: status || formData.status,
        start_date: formData.start_date
      };

      const formResponse = await fetch(`/api/forms/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formUpdateData)
      });

      if (!formResponse.ok) {
        throw new Error('Failed to update form');
      }

      // Delete removed questions
      for (const questionId of deletedQuestionIds) {
        try {
          await fetch(`/api/forms/${id}/questions/${questionId}`, {
            method: 'DELETE'
          });
        } catch (error) {
          console.warn('Failed to delete question:', questionId, error);
        }
      }

      // Save/update questions
      for (const question of questions) {
        try {
          const questionData = {
            question: question.question_text,
            type: question.question_type,
            required: question.is_required,
            options: question.options || [],
            order_number: questions.indexOf(question)
          };

          if (question.id) {
            // Update existing question
            await fetch(`/api/forms/${id}/questions/${question.id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(questionData)
            });
          } else {
            // Create new question
            await fetch(`/api/forms/${id}/questions`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(questionData)
            });
          }
        } catch (error) {
          console.warn('Failed to save question:', question, error);
        }
      }

      const statusText = status === 'published' ? 'published' : 'updated';
      toast.success(`Form ${statusText} successfully`);
      router.push(`/forms/${id}`);
    } catch (error) {
      console.error('Error saving form:', error);
      toast.error(`Failed to ${status === 'published' ? 'publish' : 'update'} form`);
      setIsSubmitting(false);
    }
  };

  const handleAddNewQuestion = () => {
    setIsAddingQuestion(true);
    setEditingQuestionIndex(null);
    setCurrentQuestion({
      id: null,
      question_text: '',
      question_type: 'short_text',
      is_required: false,
      options: []
    });
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto fade-in pb-12">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/forms')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Forms
        </Button>
        <h1 className="text-2xl font-bold">Edit Form</h1>
      </div>

      <Card className="mb-6">
        <Card.Header>
          <Card.Title>Form Details</Card.Title>
        </Card.Header>
        <Card.Content className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="title">
              Form Title <span className="text-red-500">*</span>
            </Label>
            <Input
              id="title"
              name="title"
              value={formData.title}
              onChange={handleFormChange}
              placeholder="Enter form title"
              className={errors.title ? 'border-red-500' : ''}
            />
            {errors.title && (
              <p className="text-red-500 text-sm mt-1">{errors.title}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <textarea
              id="description"
              name="description"
              value={formData.description}
              onChange={handleFormChange}
              placeholder="Enter form description (optional)"
              rows={3}
              className="flex w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 focus-visible:ring-offset-2"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <Label htmlFor="frequency">Frequency</Label>
              <Select
                id="frequency"
                name="frequency"
                value={formData.frequency}
                onChange={handleFormChange}
              >
                {frequencies.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="audience">Target Audience</Label>
              <Select
                id="audience"
                name="audience"
                value={formData.audience}
                onChange={handleFormChange}
              >
                {audiences.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="start_date">When to Start Date</Label>
            <Input
              id="start_date"
              name="start_date"
              type="date"
              value={formData.start_date}
              onChange={handleFormChange}
              placeholder="Select start date"
            />
          </div>
        </Card.Content>
      </Card>

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-semibold">Form Questions</h2>
      </div>

      {/* Question List */}
      {questions.length === 0 ? (
        <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg p-8 text-center mb-6">
          <p className="text-gray-500">No questions added yet. Click the &quot;Add Question&quot; button to create your first question.</p>
          {!isAddingQuestion && editingQuestionIndex === null && (
            <div className="flex justify-center mt-6">
              <Button
                onClick={handleAddNewQuestion}
                className="flex items-center"
              >
                <FiPlus className="mr-2" />
                Add Question
              </Button>
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-4 mb-6">
          {questions.map((question, index) => (
            editingQuestionIndex === index ? (
              <Card key={index} id={`question-${index}`} className="mb-6 border-primary-200 shadow-md">
                <Card.Header>
                  <Card.Title>Edit Question</Card.Title>
                </Card.Header>
                <Card.Content className="space-y-6">
                  {/* Question edit form */}
                  <div className="space-y-2">
                    <Label htmlFor="question_text">
                      Question Text <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      id="question_text"
                      name="question_text"
                      value={currentQuestion.question_text}
                      onChange={handleQuestionChange}
                      placeholder="Enter your question"
                      className={errors.question_text ? 'border-red-500' : ''}
                    />
                    {errors.question_text && (
                      <p className="text-red-500 text-sm mt-1">{errors.question_text}</p>
                    )}
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <Label htmlFor="question_type">Question Type</Label>
                      <Select
                        id="question_type"
                        name="question_type"
                        value={currentQuestion.question_type}
                        onChange={handleQuestionChange}
                      >
                        {questionTypes.map(option => (
                          <option key={option.value} value={option.value}>
                            {option.label}
                          </option>
                        ))}
                      </Select>
                    </div>
                    <div className="flex items-end space-x-2">
                      <div className="flex items-center h-10">
                        <input
                          type="checkbox"
                          id="is_required"
                          name="is_required"
                          checked={currentQuestion.is_required}
                          onChange={handleQuestionChange}
                          className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                        />
                        <Label htmlFor="is_required" className="ml-2">
                          Required Question
                        </Label>
                      </div>
                    </div>
                  </div>
                  {/* Options for multiple choice, checkbox, dropdown */}
                  {['multiple_choice', 'checkbox', 'dropdown'].includes(currentQuestion.question_type) && (
                    <div className="space-y-2">
                      <Label>Options</Label>
                      <div className="space-y-2">
                        {currentQuestion.options.map((option, idx) => (
                          <div key={idx} className="flex items-center space-x-2">
                            <Input
                              value={option}
                              onChange={(e) => {
                                const newOptions = [...currentQuestion.options];
                                newOptions[idx] = e.target.value;
                                setCurrentQuestion(prev => ({ ...prev, options: newOptions }));
                              }}
                            />
                            <Button
                              type="button"
                              variant="outline"
                              size="sm"
                              onClick={() => removeOption(idx)}
                              className="text-red-600 hover:text-red-700"
                            >
                              <FiTrash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        ))}
                        <div className="flex items-center space-x-2">
                          <Input
                            value={currentOption}
                            onChange={handleOptionChange}
                            placeholder="Add new option"
                          />
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={addOption}
                          >
                            <FiPlus className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                      {errors.options && (
                        <p className="text-red-500 text-sm mt-1">{errors.options}</p>
                      )}
                    </div>
                  )}
                  <div className="flex justify-end space-x-2">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        setIsAddingQuestion(false);
                        setEditingQuestionIndex(null);
                        setCurrentQuestion({
                          id: null,
                          question_text: '',
