          {/* Render add question form at the bottom if isAddingQuestion and not editing */}
          {isAddingQuestion && editingQuestionIndex === null && (
            <Card className="mb-6 border-primary-200 shadow-md">
              <Card.Header>
                <Card.Title>Add New Question</Card.Title>
              </Card.Header>
              <Card.Content className="space-y-6">
                <div className="space-y-2">
                  <Label htmlFor="question_text">
                    Question Text <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="question_text"
                    name="question_text"
                    value={currentQuestion.question_text}
                    onChange={handleQuestionChange}
                    placeholder="Enter your question"
                    className={errors.question_text ? 'border-red-500' : ''}
                  />
                  {errors.question_text && (
                    <p className="text-red-500 text-sm mt-1">{errors.question_text}</p>
