                            <FiTrash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      ))}
                      <div className="flex items-center space-x-2">
                        <Input
                          value={currentOption}
                          onChange={handleOptionChange}
                          placeholder="Add new option"
                        />
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
