                        >
                          <FiPlus className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                    {errors.options && (
                      <p className="text-red-500 text-sm mt-1">{errors.options}</p>
                    )}
                  </div>
                )}
                <div className="flex justify-end space-x-2">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => {
                      setIsAddingQuestion(false);
                      setCurrentQuestion({
                        id: null,
                        question_text: '',
                        question_type: 'short_text',
                        is_required: false,
                        options: []
                      });
                    }}
                  >
                    Cancel
                  </Button>
                  <Button
                    type="button"
                    onClick={addQuestion}
                  >
                    Add Question
                  </Button>
                </div>
              </Card.Content>
            </Card>
          )}
          {/* Always show Add Question button at the bottom unless adding/editing */}
          {!isAddingQuestion && editingQuestionIndex === null && (
            <div className="flex justify-center mt-6">
              <Button
                onClick={handleAddNewQuestion}
                className="flex items-center"
              >
                <FiPlus className="mr-2" />
                Add Question
              </Button>
            </div>
          )}
        </div>
      )}

      <div className="flex justify-between mt-8">
        <Button
          variant="outline"
          onClick={() => router.push(`/forms/${id}/preview`)}
          className="flex items-center"
          disabled={questions.length === 0}
        >
          <FiEye className="mr-2" />
          Preview Form
        </Button>

        <div className="space-x-2">
          <Button
            variant="outline"
            onClick={() => router.push(`/forms/${id}`)}
            disabled={isSubmitting}
          >
            Cancel
          </Button>
          <Button
            variant="outline"
            onClick={() => saveForm('draft')}
            disabled={isSubmitting}
