          </Button>
          <Button
            onClick={() => saveForm('published')}
            disabled={isSubmitting || questions.length === 0}
            className="flex items-center"
          >
            <FiCheck className="mr-2" />
            {isSubmitting ? 'Publishing...' : 'Publish Form'}
          </Button>
        </div>
      </div>
    </div>
  );
}

