export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getFormById } = require('../../../lib/data');
  const { id } = context.params;

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    const formData = await getFormById(id);

    if (!formData) {
      return {
        notFound: true
      };
    }

    // Serialize dates
    const serializedForm = {
      ...formData,
      created_at: formData.created_at ? formData.created_at.toISOString() : null,
      updated_at: formData.updated_at ? formData.updated_at.toISOString() : null,
      published_at: formData.published_at ? formData.published_at.toISOString() : null,
      start_date: formData.start_date ? formData.start_date.toISOString() : null,
      // Parse questions if they're stored as JSON string and ensure options are properly parsed
      questions: formData.questions ? (typeof formData.questions === 'string' ? JSON.parse(formData.questions) : formData.questions).map(question => ({
        ...question,
        // Ensure options are properly parsed if they're stored as JSON string
        options: question.options ? 
          (typeof question.options === 'string' ? 
            JSON.parse(question.options) : 
            question.options
          ) : []
      })) : []
    };

    // Check form availability based on user role and form status
    let isFormAvailable = false;

    // Admins and co-founders can preview all forms
    if (user && (user.role === 'admin' || user.role === 'co_founder')) {
      isFormAvailable = true;
    } else if (user && serializedForm.status === 'published') {
      switch (serializedForm.audience) {
        case 'all':
          isFormAvailable = true;
          break;
        case 'employee':
          isFormAvailable = user.isEmployee || user.role === 'employee';
          break;
        case 'team_lead':
          isFormAvailable = user.role === 'team_lead';
          break;
        case 'project_manager':
          isFormAvailable = user.role === 'project_manager';
          break;
        case 'co_founders':
          isFormAvailable = user.role === 'co_founder';
          break;
        case 'employee_to_pm':
          // Only employees can see this form initially
          isFormAvailable = user.isEmployee || user.role === 'employee';
          break;
        case 'pm_to_employee':
          // Only PMs can see this form initially
          isFormAvailable = user.role === 'project_manager';
          break;
        default:
          isFormAvailable = false;
      }
    }

    // If user is not authenticated, redirect to login
    if (!user) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    // If form is not available to user (except for admins/co-founders), redirect to forms
    if (!isFormAvailable) {
      return {
        redirect: {
          destination: '/forms',
          permanent: false,
        },
      };
    }

    return {
      props: {
        form: serializedForm,
        user: user
      }
    };
  } catch (error) {
    console.error('Error fetching form:', error);
    return {
      notFound: true
    };
  }
}

import { useState } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { FiArrowLeft, FiEye, FiEdit } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Card } from '../../../components/Card';
import { Input } from '../../../components/Input';
import { Textarea } from '../../../components/Textarea';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';

export default function FormPreview({ form, user }) {
  const [answers, setAnswers] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isPreviewSubmitted, setIsPreviewSubmitted] = useState(false);
  const router = useRouter();

  // Debug logging
  console.log('Form data in preview:', form);
  console.log('Questions:', form?.questions);

  const handleAnswerChange = (questionId, value) => {
    setAnswers(prev => ({
      ...prev,
      [questionId]: value
    }));
  };

  const handlePreviewSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    // Simulate submission delay
    setTimeout(() => {
      setIsPreviewSubmitted(true);
      setIsSubmitting(false);
      toast.success('Preview submission completed!');
    }, 1000);
  };

  const renderQuestion = (question, index) => {
    const questionId = question.id || `question-${index}`;

    // Safely get options with fallbacks
    const getQuestionOptions = (question) => {
      if (!question.options) return [];

      try {
        let options = question.options;

        // If options is a string, try to parse it
        if (typeof options === 'string') {
          options = JSON.parse(options);
        }

        // Ensure options is an array
        if (!Array.isArray(options)) {
          console.warn('Question options is not an array:', options);
          return [];
        }

        return options;
      } catch (error) {
        console.error('Error parsing question options:', error);
        return [];
      }
    };

    const questionOptions = getQuestionOptions(question);

    switch (question.type) {
      case 'text':
      case 'short_text':
        return (
          <div key={questionId} className="space-y-2">
            <Label htmlFor={questionId}>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <Input
              id={questionId}
              placeholder={question.placeholder || "Enter your answer here..."}
              value={answers[questionId] || ''}
              onChange={(e) => handleAnswerChange(questionId, e.target.value)}
              required={question.required}
            />
          </div>
        );

      case 'textarea':
      case 'long_text':
        return (
          <div key={questionId} className="space-y-2">
            <Label htmlFor={questionId}>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <Textarea
              id={questionId}
              placeholder={question.placeholder || "Enter your detailed answer here..."}
              rows={question.rows || 4}
              value={answers[questionId] || ''}
              onChange={(e) => handleAnswerChange(questionId, e.target.value)}
              required={question.required}
            />
          </div>
        );

      case 'select':
      case 'multiple_choice':
        return (
          <div key={questionId} className="space-y-2">
            <Label htmlFor={questionId}>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <Select
              id={questionId}
              value={answers[questionId] || ''}
              onChange={(e) => handleAnswerChange(questionId, e.target.value)}
              required={question.required}
            >
              <option value="">-- Select an option --</option>
              {questionOptions.length > 0 ? (
                questionOptions.map((option, optIndex) => (
                  <option key={optIndex} value={option.value || option}>
                    {option.label || option}
                  </option>
                ))
              ) : (
                <option value="" disabled>No options available</option>
              )}
            </Select>
            {questionOptions.length === 0 && (
              <p className="text-xs text-red-500">Warning: No options configured for this question</p>
            )}
          </div>
        );

      case 'radio':
        return (
          <div key={questionId} className="space-y-2">
            <Label>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <div className="space-y-2">
              {questionOptions.length > 0 ? (
                questionOptions.map((option, optIndex) => (
                  <label key={optIndex} className="flex items-center">
                    <input
                      type="radio"
                      name={questionId}
                      value={option.value || option}
                      checked={answers[questionId] === (option.value || option)}
                      onChange={(e) => handleAnswerChange(questionId, e.target.value)}
                      className="mr-2"
                      required={question.required}
                    />
                    {option.label || option}
                  </label>
                ))
              ) : (
                <p className="text-sm text-red-500">No options available for this question</p>
              )}
            </div>
          </div>
        );

      case 'checkbox':
        return (
          <div key={questionId} className="space-y-2">
            <Label>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <div className="space-y-2">
              {questionOptions.length > 0 ? (
                questionOptions.map((option, optIndex) => (
                  <label key={optIndex} className="flex items-center">
                    <input
                      type="checkbox"
                      value={option.value || option}
                      checked={(answers[questionId] || []).includes(option.value || option)}
                      onChange={(e) => {
                        const currentValues = answers[questionId] || [];
                        const newValues = e.target.checked
                          ? [...currentValues, e.target.value]
                          : currentValues.filter(v => v !== e.target.value);
                        handleAnswerChange(questionId, newValues);
                      }}
                      className="mr-2"
                    />
                    {option.label || option}
                  </label>
                ))
              ) : (
                <p className="text-sm text-red-500">No options available for this question</p>
              )}
            </div>
          </div>
        );

      case 'linear_scale':
        return (
          <div key={questionId} className="space-y-2">
            <Label>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <div className="flex items-center space-x-4">
              <span className="text-sm text-gray-500">{question.scale?.min_label || '1'}</span>
              <div className="flex space-x-2">
                {Array.from({ length: (question.scale?.max || 5) - (question.scale?.min || 1) + 1 }, (_, i) => {
                  const value = (question.scale?.min || 1) + i;
                  return (
                    <label key={value} className="flex flex-col items-center">
                      <input
                        type="radio"
                        name={questionId}
                        value={value}
                        checked={answers[questionId] == value}
                        onChange={(e) => handleAnswerChange(questionId, parseInt(e.target.value))}
                        className="mb-1"
                        required={question.required}
                      />
                      <span className="text-xs">{value}</span>
                    </label>
                  );
                })}
              </div>
              <span className="text-sm text-gray-500">{question.scale?.max_label || '5'}</span>
            </div>
          </div>
        );

      default:
        return (
          <div key={questionId} className="space-y-2">
            <Label htmlFor={questionId}>
              {question.title || question.question}
              {question.required && <span className="text-red-500 ml-1">*</span>}
            </Label>
            {question.description && (
              <p className="text-sm text-gray-600">{question.description}</p>
            )}
            <Input
              id={questionId}
              placeholder="Enter your answer here..."
              value={answers[questionId] || ''}
              onChange={(e) => handleAnswerChange(questionId, e.target.value)}
              required={question.required}
            />
            <p className="text-xs text-gray-500">Question type: {question.type}</p>
          </div>
        );
    }
  };

  if (isPreviewSubmitted) {
    return (
      <div className="max-w-4xl mx-auto space-y-6 fade-in">
        <div className="text-center py-12">
          <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100 mb-4">
            <FiEye className="h-6 w-6 text-green-600" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900 mb-2">Preview Completed</h2>
          <p className="text-gray-500 mb-6">
            This was a preview submission. No data has been saved.
          </p>
          <div className="space-x-3">
            <Button onClick={() => setIsPreviewSubmitted(false)}>
              Preview Again
            </Button>
            <Link href={`/forms/${form.id}/edit`}>
              <a>
                <Button variant="outline">
                  <FiEdit className="mr-2" />
                  Edit Form
                </Button>
              </a>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6 fade-in">
      <div className="flex items-center justify-between">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/forms')}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Forms
          </Button>
          <h1 className="text-2xl font-bold">Form Preview</h1>
          <p className="text-gray-500">Preview how this form will appear to users</p>
        </div>
        {user && user.role === 'admin' && (
          <Link href={`/forms/${form.id}/edit`}>
            <a>
              <Button variant="outline">
                <FiEdit className="mr-2" />
                Edit Form
              </Button>
            </a>
          </Link>
        )}
      </div>

      <Card>
        <Card.Header>
          <Card.Title>{form.title}</Card.Title>
          {form.description && (
            <Card.Description>{form.description}</Card.Description>
          )}
        </Card.Header>
        <Card.Content>
          <form onSubmit={handlePreviewSubmit} className="space-y-6">
            <div className="bg-blue-50 border border-blue-200 rounded-md p-4">
              <p className="text-blue-700 text-sm">
                <FiEye className="inline mr-2" />
                This is a preview mode. No data will be saved when you submit this form.
              </p>
            </div>

            {/* Debug Info - Remove in production */}
            {process.env.NODE_ENV === 'development' && (
              <div className="bg-yellow-50 border border-yellow-200 rounded-md p-4">
                <h4 className="text-sm font-medium text-yellow-800 mb-2">Debug Information:</h4>
                <div className="text-xs text-yellow-700 space-y-1">
                  <p>Form ID: {form.id}</p>
                  <p>Form Title: {form.title}</p>
                  <p>Questions Array Length: {form.questions?.length || 0}</p>
                  <p>Questions Type: {typeof form.questions}</p>
                  {form.questions?.length > 0 && (
                    <p>First Question: {JSON.stringify(form.questions[0], null, 2)}</p>
                  )}
                </div>
              </div>
            )}

            {/* Render actual form questions */}
            <div className="space-y-6">
              {form.questions && form.questions.length > 0 ? (
                form.questions.map((question, index) => renderQuestion(question, index))
              ) : (
                <div className="text-center py-8">
                  <div className="bg-gray-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                    <FiEdit className="h-8 w-8 text-gray-400" />
                  </div>
                  <h3 className="text-lg font-medium text-gray-900 mb-2">No Questions Added Yet</h3>
                  <p className="text-gray-500 mb-4">This form doesn&apos;t have any questions. Add some questions to see the preview.</p>
                  {user && user.role === 'admin' && (
                    <Link href={`/forms/${form.id}/edit`}>
                      <a>
                        <Button>
                          <FiEdit className="mr-2" />
                          Add Questions
                        </Button>
                      </a>
                    </Link>
                  )}
                </div>
              )}
            </div>

            {form.questions && form.questions.length > 0 && (
              <div className="flex justify-end space-x-3 pt-6 border-t">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => router.push('/forms')}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={isSubmitting}
                >
                  {isSubmitting ? 'Submitting...' : 'Submit Preview'}
                </Button>
              </div>
            )}
          </form>
        </Card.Content>
      </Card>
    </div>
  );
}

