      updated_at: formData.updated_at ? formData.updated_at.toISOString() : null,
      published_at: formData.published_at ? formData.published_at.toISOString() : null,
      start_date: formData.start_date ? formData.start_date.toISOString() : null,
      // Parse questions if they're stored as JSON string and ensure options are properly parsed
      questions: formData.questions ? (typeof formData.questions === 'string' ? JSON.parse(formData.questions) : formData.questions).map(question => ({
        ...question,
        // Ensure options are properly parsed if they're stored as JSON string
        options: question.options ? 
          (typeof question.options === 'string' ? 
            JSON.parse(question.options) : 
            question.options
          ) : []
      })) : []
    };

    return {
      props: {
        form: serializedForm,
        user: user
      }
    };
  } catch (error) {
    console.error('Error fetching form:', error);
    return {
      notFound: true
    };
  }
}

