export async function getServerSideProps() {
  // Import database functions only on server-side
  const { getForms, getEmployees, getFormSubmissions } = require('../../lib/data');

  try {
    const [forms, employees, submissions] = await Promise.all([
      getForms(),
      getEmployees(),
      getFormSubmissions()
    ]);

    // Calculate submission counts for each form
    const submissionCounts = submissions.reduce((acc, submission) => {
      acc[submission.form_id] = (acc[submission.form_id] || 0) + 1;
      return acc;
    }, {});

    // Calculate target audience counts for each form
    const formsWithStats = forms.map(form => {
      let targetCount = 0;

      // Count target audience based on form audience
      switch (form.audience) {
        case 'all':
          targetCount = employees.length;
          break;
        case 'employee':
          targetCount = employees.filter(emp => emp.job_role === 'employee').length;
          break;
        case 'project_manager':
          targetCount = employees.filter(emp => emp.job_role === 'project_manager').length;
          break;
        case 'team_lead':
          targetCount = employees.filter(emp => emp.job_role === 'team_lead').length;
          break;
        case 'co_founders':
          targetCount = employees.filter(emp => emp.job_role === 'co_founder').length;
          break;
        case 'employee_to_pm':
          // For employee to PM forms, target is employees (who fill forms for PMs)
          targetCount = employees.filter(emp => emp.job_role === 'employee').length;
          break;
        case 'pm_to_employee':
          // For PM to employee forms, target is project managers (who fill forms for employees)
          targetCount = employees.filter(emp => emp.job_role === 'project_manager').length;
          break;
        default:
          targetCount = 0;
      }

      return {
        ...form,
        targetCount,
        submissionCount: submissionCounts[form.id] || 0
      };
    });

    // Serialize dates
    const serializedForms = formsWithStats.map(form => ({
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null,
      start_date: form.start_date ? form.start_date.toISOString() : null
    }));

    return {
      props: {
        initialForms: serializedForms
      }
    };
  } catch (error) {
    console.error('Error fetching form reports:', error);
    return {
      props: {
        initialForms: []
      }
    };
  }
}

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
