import { Select } from '../../components/Select';
import { Card } from '../../components/Card';
import { EmptyState } from '../../components/EmptyState';

export default function FormReports({ initialForms }) {
  const [forms, setForms] = useState(initialForms);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [audienceFilter, setAudienceFilter] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastRefresh, setLastRefresh] = useState(Date.now());
  const router = useRouter();

  // Add real-time refresh functionality
  useEffect(() => {
    const refreshReports = async () => {
      try {
        const response = await fetch('/api/reports/forms');
        if (response.ok) {
          const data = await response.json();
          setForms(data.forms);
          setLastRefresh(Date.now());
        }
      } catch (error) {
        console.error('Error refreshing reports:', error);
      }
    };

    // Listen for form submission events
    const handleMessage = (event) => {
      if (event.data && event.data.type === 'FORM_SUBMITTED') {
        refreshReports();
      }
    };

    window.addEventListener('message', handleMessage);

    // Auto-refresh every 60 seconds for reports
    const interval = setInterval(refreshReports, 60000);

    return () => {
      window.removeEventListener('message', handleMessage);
      clearInterval(interval);
    };
  }, []);

  const refreshData = async () => {
    setIsRefreshing(true);
    try {
      const response = await fetch('/api/reports/forms');
      if (response.ok) {
        const data = await response.json();
        setForms(data.forms);
        setLastRefresh(Date.now());
        toast.success('Reports refreshed successfully');
      } else {
        toast.error('Failed to refresh reports');
      }
    } catch (error) {
      console.error('Error refreshing reports:', error);
      toast.error('Error refreshing reports');
    } finally {
      setIsRefreshing(false);
    }
  };

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'published':
        return 'bg-green-100 text-green-800';
      case 'draft':
        return 'bg-yellow-100 text-yellow-800';
      case 'archived':
        return 'bg-gray-100 text-gray-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getAudienceLabel = (audience) => {
    switch (audience) {
      case 'employee':
        return 'Employee';
      case 'team_lead':
        return 'Team Lead';
      case 'project_manager':
        return 'Project Manager';
      case 'co_founders':
        return 'Co-founders';
      case 'employee_to_pm':
        return 'Employee to PM';
      case 'pm_to_employee':
        return 'PM to Employees';
      case 'all':
        return 'All';
      default:
        return audience;
    }
  };

  const getCompletionPercentage = (submitted, target) => {
    if (target === 0) return 0;
    return Math.round((submitted / target) * 100);
  };

  const getCompletionStatusClass = (percentage) => {
    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 50) return 'text-yellow-600';
    return 'text-red-600';
  };

  // Filter forms
  const filteredForms = forms.filter(form => {
    const matchesSearch = form.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         (form.description && form.description.toLowerCase().includes(searchQuery.toLowerCase()));
    const matchesStatus = !statusFilter || form.status === statusFilter;
    const matchesAudience = !audienceFilter || form.audience === audienceFilter;

    return matchesSearch && matchesStatus && matchesAudience;
  });

  // Calculate summary statistics
  const totalForms = forms.length;
  const publishedForms = forms.filter(f => f.status === 'published').length;
  const totalTargetUsers = forms.reduce((sum, form) => sum + form.targetCount, 0);
  const totalSubmissions = forms.reduce((sum, form) => sum + form.submissionCount, 0);

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
