              <div className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">
                Last updated: {new Date(lastRefresh).toLocaleTimeString()}
              </div>
            )}
          </div>
          <p className="text-gray-500">Track form submissions and completion rates</p>
        </div>
        <div className="flex gap-2">
          <Button 
            variant="outline"
            onClick={refreshData}
            disabled={isRefreshing}
            className="flex items-center"
          >
            <div className={`mr-2 ${isRefreshing ? 'animate-spin' : ''}`}>
              <FiRefreshCw />
            </div>
            {isRefreshing ? 'Refreshing...' : 'Refresh'}
          </Button>
          <Button variant="outline">
            <FiDownload className="mr-2" />
            Export Report
          </Button>
          <Link href="/forms">
            <a>
              <Button>
                <FiFileText className="mr-2" />
                Manage Forms
              </Button>
            </a>
          </Link>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <Card>
          <Card.Content className="p-6">
            <div className="flex items-center">
              <div className="p-2 bg-blue-100 rounded-lg">
                <FiFileText className="h-6 w-6 text-blue-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">Total Forms</p>
                <p className="text-2xl font-bold text-gray-900">{totalForms}</p>
              </div>
            </div>
          </Card.Content>
        </Card>

        <Card>
          <Card.Content className="p-6">
            <div className="flex items-center">
              <div className="p-2 bg-green-100 rounded-lg">
                <FiTrendingUp className="h-6 w-6 text-green-600" />
