export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { 
    getEmployees, 
    getDepartments, 
    getForms, 
    getFormAssignments, 
    getFormResponses 
  } = require('../../lib/data');

  try {
    // Get user data from cookie
    const cookies = context.req.cookies;
    let user = null;
    if (cookies.user) {
      user = JSON.parse(cookies.user);
    }

    // Check if this is "my reports" view for employees
    const isMyReportsView = context.query.my === 'true';

    const [employees, departments, forms, assignments, responses] = await Promise.all([
      getEmployees(),
      getDepartments(),
      getForms(),
      getFormAssignments(),
      getFormResponses()
    ]);

    // Filter data based on user role and view type
    let filteredEmployees = employees;
    let filteredReports = [];

    if (user && user.isEmployee && isMyReportsView) {
      // For employee view, only show their own data
      filteredEmployees = employees.filter(emp => 
        emp.email.toLowerCase() === user.email.toLowerCase()
      );
    } else if (user && user.role === 'team_lead') {
      // For team leads, show their department members' reports
      const teamLeadEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());
      if (teamLeadEmployee) {
        filteredEmployees = employees.filter(emp => emp.department_id === teamLeadEmployee.department_id);
      }
    } else if (user && user.role === 'project_manager') {
      // For project managers, show their project team members' reports
      // This would need to be enhanced with actual project allocation data
      // For now, showing all employees who could be in their projects
      filteredEmployees = employees; // In real implementation, filter by project membership
    }

    // Serialize dates for all data
    const serializedEmployees = filteredEmployees.map(emp => ({
      ...emp,
      created_at: emp.created_at ? emp.created_at.toISOString() : null,
      updated_at: emp.updated_at ? emp.updated_at.toISOString() : null
    }));

    const serializedDepartments = departments.map(dept => ({
      ...dept,
      created_at: dept.created_at ? dept.created_at.toISOString() : null,
      updated_at: dept.updated_at ? dept.updated_at.toISOString() : null
    }));

    const serializedForms = forms.map(form => ({
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null
    }));

    // Form analytics
    const formAnalytics = forms.map(form => {
      const assigned = assignments.filter(a => a.form_id === form.id);
      const filled = responses.filter(r => r.form_id === form.id);

      // If employee view, filter to only their data
      const relevantAssigned = isMyReportsView && user?.isEmployee 
        ? assigned.filter(a => {
            const emp = employees.find(e => e.id === a.employee_id);
            return emp && emp.email.toLowerCase() === user.email.toLowerCase();
          })
        : assigned;

      const relevantFilled = isMyReportsView && user?.isEmployee
        ? filled.filter(r => {
            const emp = employees.find(e => e.id === r.employee_id);
            return emp && emp.email.toLowerCase() === user.email.toLowerCase();
          })
        : filled;

      return {
        form: serializedForms.find(f => f.id === form.id),
        assignedCount: relevantAssigned.length,
        filledCount: relevantFilled.length,
        assignedEmployees: relevantAssigned.map(a => serializedEmployees.find(e => e.id === a.employee_id)).filter(Boolean),
        filledEmployees: relevantFilled.map(r => serializedEmployees.find(e => e.id === r.employee_id)).filter(Boolean)
      };
    });

    return {
      props: {
        initialEmployees: serializedEmployees,
        initialDepartments: serializedDepartments,
        initialForms: serializedForms,
        initialFormAnalytics: formAnalytics,
        user: user,
        isMyReportsView: isMyReportsView
      }
    };
  } catch (error) {
    console.error('Error fetching reports data:', error);
    return {
      props: {
        initialEmployees: [],
        initialDepartments: [],
        initialForms: [],
        initialFormAnalytics: [],
        user: null,
        isMyReportsView: false
      }
    };
  }
}

export default function ScoreReports({ initialEmployees, initialDepartments, initialForms, initialFormAnalytics, user, isMyReportsView }) {
  const [reports, setReports] = useState([]);
  const [employees, setEmployees] = useState(initialEmployees);
  const [departments, setDepartments] = useState(initialDepartments);
  const [forms, setForms] = useState(initialForms);
  const [isLoading, setIsLoading] = useState(false);
  const [expandedItems, setExpandedItems] = useState({});
  const [currentUser, setCurrentUser] = useState(user);
  const [isAdminUser, setIsAdminUser] = useState(false);
  const [isTeamLeadUser, setIsTeamLeadUser] = useState(false);
  const [isPMUser, setIsPMUser] = useState(false);
  const [userTeamMembers, setUserTeamMembers] = useState([]);
  const [userProjectMembers, setUserProjectMembers] = useState([]);
  const [formAnalytics, setFormAnalytics] = useState(initialFormAnalytics);
  const [editingScore, setEditingScore] = useState(null);
  const [editingFeedback, setEditingFeedback] = useState(null);
  const [newScore, setNewScore] = useState('');
  const [newFeedback, setNewFeedback] = useState('');

  // Filters
  const [filters, setFilters] = useState({
    search: '',
    department: '',
    employee: '',
    form: '',
    month: '',
    year: new Date().getFullYear().toString(),
    status: ''
  });

  const router = useRouter();
  const months = getMonthsArray();
  const years = getYearsArray(2020, new Date().getFullYear());

  useEffect(() => {
    const authUser = getUser();
    const currentUser = authUser || user;
    setCurrentUser(currentUser);
    setIsAdminUser(isAdmin());
    setIsTeamLeadUser(isTeamLead());
    setIsPMUser(isProjectManager());

    if (authUser && !isAdmin()) {
      filterEmployeesBasedOnRole(authUser);
    }

    // Generate some mock reports for demo
    generateMockReports();
  }, []);

  const filterEmployeesBasedOnRole = (authUser) => {
    if (isTeamLead()) {
      // For demo purposes, show all employees for team leads
      // In a real implementation, this would be filtered based on user's teams
    } else if (isProjectManager()) {
      // For demo purposes, show all employees for project managers
      // In a real implementation, this would be filtered based on user's projects
    } else {
      // Regular employees can only see themselves
      const userEmployee = employees.find(emp => emp.email === authUser.email);
      if (userEmployee) {
        setEmployees([userEmployee]);
      }
    }
  };

  const generateMockReports = () => {
    // Generate mock report data - for employee view, show their reports (both by them and about them)
    const targetEmployees = isMyReportsView && user?.isEmployee ? 
      employees.filter(emp => emp.email.toLowerCase() === user.email.toLowerCase()) :
      employees.slice(0, 5);

    const mockReports = targetEmployees.map((emp, index) => ({
      id: `report-${emp.id}-${index + 1}`,
      employee: emp,
      form: forms[index % forms.length] || { id: 'form-1', title: 'Performance Review' },
      score: Math.floor(Math.random() * 50) + 50, // Score between 50-100
      maxScore: 100,
      status: ['completed', 'pending', 'in_progress'][Math.floor(Math.random() * 3)],
      submittedAt: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
      department: departments.find(d => d.id === emp.department_id) || { name: 'No Department' },
      submittedBy: emp.id, // Self-assessment
      submittedByName: emp.name,
      reportType: 'self-assessment',
      canEdit: user && (user.role === 'admin' || user.role === 'team_lead'),
      feedback: null,
      reviewedBy: null,
      reviewedAt: null
    }));

    // If employee view, add more reports for the same employee including assessments BY others ABOUT them
    if (isMyReportsView && user?.isEmployee && targetEmployees.length > 0) {
      const employee = targetEmployees[0];

      // Add self-assessments
      const selfAssessments = forms.slice(0, 2).map((form, index) => ({
        id: `report-${employee.id}-self-${index + 1}`,
        employee: employee,
        form: form,
        score: Math.floor(Math.random() * 50) + 50,
        maxScore: 100,
        status: ['completed', 'pending'][Math.floor(Math.random() * 2)],
        submittedAt: new Date(Date.now() - Math.random() * 60 * 24 * 60 * 60 * 1000).toISOString(),
        department: departments.find(d => d.id === employee.department_id) || { name: 'No Department' },
        submittedBy: employee.id,
        submittedByName: employee.name,
        reportType: 'self-assessment',
        canEdit: false,
        feedback: null,
        reviewedBy: null,
        reviewedAt: null
      }));

      // Add assessments BY team lead/manager ABOUT the employee
      const managerAssessments = forms.slice(0, 3).map((form, index) => ({
        id: `report-${employee.id}-manager-${index + 1}`,
        employee: employee, // This employee is being assessed
        form: { ...form, title: `${form.title} (Manager Review)` },
        score: Math.floor(Math.random() * 40) + 60, // Slightly higher scores from managers
        maxScore: 100,
        status: 'completed', // Manager assessments are usually completed
        submittedAt: new Date(Date.now() - Math.random() * 45 * 24 * 60 * 60 * 1000).toISOString(),
        department: departments.find(d => d.id === employee.department_id) || { name: 'No Department' },
        submittedBy: 'manager-001', // Submitted by manager
        submittedByName: 'Team Lead / Manager',
        reportType: 'manager-assessment',
        canEdit: false,
        feedback: Math.random() > 0.5 ? "Good performance with room for improvement in communication skills." : null,
        reviewedBy: 'Team Lead / Manager',
        reviewedAt: new Date(Date.now() - Math.random() * 20 * 24 * 60 * 60 * 1000).toISOString()
      }));

      // Add peer reviews ABOUT the employee
      const peerReviews = forms.slice(1, 2).map((form, index) => ({
        id: `report-${employee.id}-peer-${index + 1}`,
        employee: employee, // This employee is being assessed
        form: { ...form, title: `${form.title} (Peer Review)` },
        score: Math.floor(Math.random() * 30) + 55, 
        maxScore: 100,
        status: 'completed',
        submittedAt: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
        department: departments.find(d => d.id === employee.department_id) || { name: 'No Department' },
        submittedBy: 'peer-001',
        submittedByName: 'Team Colleague',
        reportType: 'peer-review',
        canEdit: false,
        feedback: Math.random() > 0.7 ? "Excellent collaboration and teamwork." : null,
        reviewedBy: null,
        reviewedAt: null
      }));

      mockReports.push(...selfAssessments, ...managerAssessments, ...peerReviews);
    }

    // If team lead view, add reports for all department members
    if (user && user.role === 'team_lead' && !isMyReportsView) {
      const teamLeadEmployee = employees.find(emp => emp.email?.toLowerCase() === user.email?.toLowerCase());
      if (teamLeadEmployee) {
        const departmentEmployees = employees.filter(emp => emp.department_id === teamLeadEmployee.department_id);

        const departmentReports = departmentEmployees.flatMap((emp, empIndex) => {
          return forms.slice(0, 2).map((form, formIndex) => ({
            id: `dept-report-${emp.id}-${form.id}-${formIndex}`,
            employee: emp,
            form: form,
            score: Math.floor(Math.random() * 50) + 50,
            maxScore: 100,
            status: ['completed', 'pending'][Math.floor(Math.random() * 2)],
            submittedAt: new Date(Date.now() - Math.random() * 60 * 24 * 60 * 60 * 1000).toISOString(),
            department: departments.find(d => d.id === emp.department_id) || { name: 'No Department' },
            submittedBy: emp.id,
            submittedByName: emp.name,
            reportType: 'department-submission',
            canEdit: true, // Team leads can edit/review their department reports
            feedback: Math.random() > 0.6 ? `Review pending for ${emp.name}` : `Good progress shown by ${emp.name}`,
            reviewedBy: user.role === 'team_lead' && Math.random() > 0.5 ? 'Team Lead' : null,
            reviewedAt: user.role === 'team_lead' && Math.random() > 0.5 ? new Date(Date.now() - Math.random() * 10 * 24 * 60 * 60 * 1000).toISOString() : null
          }));
        });

        mockReports.push(...departmentReports);
      }
    }

    // If project manager view, add reports for all project team members
    if (user && user.role === 'project_manager' && !isMyReportsView) {
      // Generate project-based reports for all team members in PM's projects
      const projectTeamMembers = employees.slice(0, Math.min(15, employees.length)); // Mock project team

      const projectReports = projectTeamMembers.flatMap((emp, empIndex) => {
        return forms.slice(0, 2).map((form, formIndex) => ({
          id: `proj-report-${emp.id}-${form.id}-${formIndex}`,
          employee: emp,
          form: form,
          score: Math.floor(Math.random() * 50) + 50,
          maxScore: 100,
          status: ['completed', 'pending', 'in_progress'][Math.floor(Math.random() * 3)],
          submittedAt: new Date(Date.now() - Math.random() * 60 * 24 * 60 * 60 * 1000).toISOString(),
          department: departments.find(d => d.id === emp.department_id) || { name: 'No Department' },
          submittedBy: emp.id,
          submittedByName: emp.name,
          reportType: 'project-submission',
          canEdit: true, // Project managers can review reports from their project members
          feedback: Math.random() > 0.7 ? `Project performance review for ${emp.name}` : null,
          reviewedBy: user.role === 'project_manager' && Math.random() > 0.4 ? 'Project Manager' : null,
          reviewedAt: user.role === 'project_manager' && Math.random() > 0.4 ? new Date(Date.now() - Math.random() * 15 * 24 * 60 * 60 * 1000).toISOString() : null,
          projectName: ['Website Redesign', 'Mobile App', 'API Integration', 'Analytics Dashboard'][empIndex % 4],
          projectId: `proj-${empIndex % 4 + 1}`
        }));
      });

      mockReports.push(...projectReports);
    }

    setReports(mockReports);
  };

  // Employee-specific functions
  const getPageTitle = () => {
    if (isMyReportsView && user?.isEmployee) {
      return "My Performance Reports";
    } else if (user && user.role === 'project_manager') {
      return "Project Team Reports";
    }
    return "Score Reports";
  };

  const getPageDescription = () => {
    if (isMyReportsView && user?.isEmployee) {
      return "View your performance evaluations and assessments submitted by yourself and others";
    } else if (user && user.role === 'project_manager') {
      return "View and review performance reports from your project team members";
    }
    return "View and analyze performance assessment reports";
  };

  const showAllFilters = () => {
    return !isMyReportsView || (user && user.role === 'admin');
  };

  const loadTeamMembersForTeamLead = () => {
    try {
      // Note: This would need to be implemented via API calls in a real implementation
      // For now, showing all employees for team leads
      console.log('Team lead member loading would be implemented via API');
    } catch (error) {
      console.error('Error loading team members for team lead:', error);
    }
  };

  const loadTeamMembersForProjectManager = () => {
    try {
      // Note: This would need to be implemented via API calls in a real implementation
      // For now, showing all employees for project managers
      console.log('Project manager member loading would be implemented via API');
    } catch (error) {
      console.error('Error loading team members for project manager:', error);
    }
  };

  const fetchReports = async () => {
    setIsLoading(true);

    try {
      let reportData = [];

      if (isSupabaseConfigured()) {
        // Start building the query
        let query = supabase
          .from('employee_score_reports')
          .select('*');

        if (isAdmin()) {
          // Admin can see all reports, so no additional filtering needed
        } else if (isTeamLead() && userTeamMembers.length > 0) {
          // Team leads can see their own reports and their team members' reports
          const employeeIds = [currentUser.id, ...userTeamMembers.map(m => m.id)];
          query = query.in('employee_id', employeeIds);
        } else if (isProjectManager() && userProjectMembers.length > 0) {
          // Project managers can see their own reports and their project members' reports
          const employeeIds = [currentUser.id, ...userProjectMembers.map(m => m.id)];
          query = query.in('employee_id', employeeIds);
        } else {
          // Regular employees can only see their own reports
          query = query.eq('employee_id', currentUser.id);
        }

        // Apply other filters
        if (filters.department) {
          query = query.eq('department_id', filters.department);
        }

        if (filters.employee) {
          query = query.eq('employee_id', filters.employee);
        }

        if (filters.form) {
          query = query.eq('form_id', filters.form);
        }

        if (filters.month) {
          query = query.eq('submission_month', filters.month);
        }

        if (filters.year) {
          query = query.eq('submission_year', filters.year);
        }

        if (filters.status) {
          query = query.eq('status', filters.status);
        }

        // Execute the query
        const { data, error } = await query.order('submitted_at', { ascending: false });

        if (error) throw error;
        reportData = data;
      } else {
        // Mock data for demo
        reportData = generateMockReports();

        // Filter mock data
        reportData = reportData.filter(report => {
          // Apply role-based filtering
          if (isAdmin()) {
            // Admin can see all reports
            return true;
          } else if (isTeamLead() && userTeamMembers.length > 0) {
            // Team leads can see their own reports and their team members' reports
            const teamMemberIds = userTeamMembers.map(m => m.id);
            return report.employee_id === currentUser.id || teamMemberIds.includes(report.employee_id);
          } else if (isProjectManager() && userProjectMembers.length > 0) {
            // Project managers can see their own reports and their project members' reports
            const projectMemberIds = userProjectMembers.map(m => m.id);
            return report.employee_id === currentUser.id || projectMemberIds.includes(report.employee_id);
          } else {
            // Regular employees can only see their own reports
            return report.employee_id === currentUser.id;
          }

          // Apply other filters
          if (filters.department && report.department_id !== filters.department) return false;
          if (filters.employee && report.employee_id !== filters.employee) return false;
          if (filters.form && report.form_id !== filters.form) return false;
          if (filters.month && report.submission_month !== filters.month) return false;
          if (filters.year && report.submission_year !== filters.year) return false;
          if (filters.status && report.status !== filters.status) return false;

          return true;
        });
      }

      // Apply search filter
      if (filters.search) {
        const searchLower = filters.search.toLowerCase();
        reportData = reportData.filter(report => 
          (report.employee_name && report.employee_name.toLowerCase().includes(searchLower)) ||
          (report.form_title && report.form_title.toLowerCase().includes(searchLower)) ||
          (report.department_name && report.department_name.toLowerCase().includes(searchLower)) ||
          (report.user_email && report.user_email.toLowerCase().includes(searchLower))
        );
      }

      setReports(reportData);
    } catch (error) {
      console.error('Error fetching reports:', error);
      toast.error('Failed to load reports');
    } finally {
      setIsLoading(false);
    }
  };

  const handleFilterChange = (name, value) => {
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const clearFilters = () => {
    setFilters({
      search: '',
      department: '',
      employee: '',
      form: '',
      month: '',
      year: new Date().getFullYear().toString(),
      status: ''
    });
  };

  const toggleExpand = (id) => {
    setExpandedItems(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const handleExport = () => {
    toast.success('Reports exported successfully');
  };

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'completed':
        return 'bg-green-100 text-green-800';
      case 'pending':
        return 'bg-yellow-100 text-yellow-800';
      case 'reviewed':
        return 'bg-blue-100 text-blue-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getScoreColorClass = (score, maxScore) => {
    if (!score || !maxScore) return 'text-gray-500';

    const percentage = (score / maxScore) * 100;

    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 60) return 'text-blue-600';
    if (percentage >= 40) return 'text-yellow-600';
    return 'text-red-600';
  };

  const handleScoreEdit = (reportId) => {
    const report = reports.find(r => r.id === reportId);
    if (report) {
      setEditingScore(reportId);
      setNewScore(report.score.toString());
    }
  };

  const handleFeedbackEdit = (reportId) => {
    const report = reports.find(r => r.id === reportId);
    if (report) {
      setEditingFeedback(reportId);
      setNewFeedback(report.feedback || '');
    }
  };

  const saveScore = async (reportId) => {
    try {
      // In a real implementation, this would make an API call
      const updatedReports = reports.map(report => 
        report.id === reportId 
          ? { 
              ...report, 
              score: parseInt(newScore) || report.score,
              reviewedBy: user?.role === 'team_lead' ? 'Team Lead' : user?.role === 'project_manager' ? 'Project Manager' : user.name || 'Reviewer',
              reviewedAt: new Date().toISOString()
            }
          : report
      );

      setReports(updatedReports);
      setEditingScore(null);
      setNewScore('');
      toast.success('Score updated successfully');
    } catch (error) {
      toast.error('Failed to update score');
    }
  };

  const saveFeedback = async (reportId) => {
    try {
      // In a real implementation, this would make an API call
      const updatedReports = reports.map(report => 
        report.id === reportId 
          ? { 
              ...report, 
              feedback: newFeedback,
              reviewedBy: user?.role === 'team_lead' ? 'Team Lead' : user?.role === 'project_manager' ? 'Project Manager' : user.name || 'Reviewer',
              reviewedAt: new Date().toISOString()
            }
          : report
      );

      setReports(updatedReports);
      setEditingFeedback(null);
      setNewFeedback('');
      toast.success('Feedback updated successfully');
    } catch (error) {
      toast.error('Failed to update feedback');
    }
  };

  const cancelEdit = () => {
    setEditingScore(null);
    setEditingFeedback(null);
    setNewScore('');
    setNewFeedback('');
  };

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">{getPageTitle()}</h1>
          <p className="text-gray-500">
            {getPageDescription()}
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-2">
          {isMyReportsView && (
            <Link href="/reports">
              <a>
                <Button variant="outline" className="w-full sm:w-auto flex items-center justify-center">
                  <FiFileText className="mr-2" />
                  All Reports
                </Button>
              </a>
            </Link>
          )}
          {(user && user.role === 'project_manager') && (
            <Link href="/projects/allocations">
              <a>
                <Button variant="outline" className="w-full sm:w-auto flex items-center justify-center">
                  <FiUsers className="mr-2" />
                  Manage Allocations
                </Button>
              </a>
            </Link>
          )}
          {isAdminUser && (
            <Button 
              variant="outline" 
              onClick={handleExport}
              className="w-full sm:w-auto flex items-center justify-center"
            >
              <FiDownload className="mr-2" />
              Export
            </Button>
          )}
          {(isAdminUser || (user && user.role === 'project_manager')) && (
            <Link href="/analytics">
              <a>
                <Button className="w-full sm:w-auto flex items-center justify-center">
                  <FiBarChart2 className="mr-2" />
                  View Analytics
                </Button>
              </a>
            </Link>
          )}
        </div>
      </div>

      {/* Quick Access Cards */}
      {isAdminUser && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <Card className="hover:shadow-md transition-shadow cursor-pointer" onClick={() => router.push('/reports/forms')}>
