export async function getServerSideProps(context) {
  // Import database functions only on server-side
  const { getFormById, getEmployees, getFormSubmissions } = require('../../../lib/data');
  const { id } = context.params;

  try {
    const [form, employees, submissions] = await Promise.all([
      getFormById(id),
      getEmployees(),
      getFormSubmissions() // We'll filter by form_id in the component
    ]);

    if (!form) {
      return {
        notFound: true
      };
    }

    // Calculate target audience
    let targetEmployees = [];
    switch (form.audience) {
      case 'all':
        targetEmployees = employees;
        break;
      case 'employee':
        targetEmployees = employees.filter(emp => emp.job_role === 'employee');
        break;
      case 'project_manager':
        targetEmployees = employees.filter(emp => emp.job_role === 'project_manager');
        break;
      case 'team_lead':
        targetEmployees = employees.filter(emp => emp.job_role === 'team_lead');
        break;
      case 'co_founders':
        targetEmployees = employees.filter(emp => emp.job_role === 'co_founder');
        break;
      case 'employee_to_pm':
        // For employee to PM forms, target is project managers
        targetEmployees = employees.filter(emp => emp.job_role === 'project_manager');
        break;
      case 'pm_to_employee':
        // For PM to employee forms, target is employees
        targetEmployees = employees.filter(emp => emp.job_role === 'employee');
        break;
      default:
        targetEmployees = [];
    }

    // Filter submissions for this form
    const formSubmissions = submissions.filter(sub => sub.form_id === id);

    // Create employee status list
    const employeeStatuses = targetEmployees.map(emp => {
      const submission = formSubmissions.find(sub => sub.employee_id === emp.id);
      return {
        ...emp,
        hasSubmitted: !!submission,
        submission: submission || null,
        submittedAt: submission ? submission.submitted_at : null
      };
    });

    // Serialize dates
    const serializedForm = {
      ...form,
      created_at: form.created_at ? form.created_at.toISOString() : null,
      updated_at: form.updated_at ? form.updated_at.toISOString() : null,
      published_at: form.published_at ? form.published_at.toISOString() : null,
      start_date: form.start_date ? form.start_date.toISOString() : null
    };

    const serializedEmployeeStatuses = employeeStatuses.map(emp => ({
      ...emp,
      created_at: emp.created_at ? emp.created_at.toISOString() : null,
      updated_at: emp.updated_at ? emp.updated_at.toISOString() : null,
      submittedAt: emp.submittedAt ? emp.submittedAt.toISOString() : null,
      submission: emp.submission ? {
        ...emp.submission,
        submitted_at: emp.submission.submitted_at ? emp.submission.submitted_at.toISOString() : null,
        created_at: emp.submission.created_at ? emp.submission.created_at.toISOString() : null,
        updated_at: emp.submission.updated_at ? emp.submission.updated_at.toISOString() : null
      } : null
    }));

    const serializedSubmissions = formSubmissions.map(sub => ({
      ...sub,
      submitted_at: sub.submitted_at ? sub.submitted_at.toISOString() : null,
      created_at: sub.created_at ? sub.created_at.toISOString() : null,
      updated_at: sub.updated_at ? sub.updated_at.toISOString() : null
    }));

    return {
      props: {
        form: serializedForm,
        employeeStatuses: serializedEmployeeStatuses,
        submissions: serializedSubmissions,
        targetCount: targetEmployees.length,
        submissionCount: formSubmissions.length
      }
    };
  } catch (error) {
    console.error('Error fetching form report:', error);
    return {
      notFound: true
    };
  }
}

