export default function FormReportDetails({ form, employeeStatuses, submissions, targetCount, submissionCount }) {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [selectedSubmission, setSelectedSubmission] = useState(null);
  const [isResponseModalOpen, setIsResponseModalOpen] = useState(false);
  const router = useRouter();

  const getAudienceLabel = (audience) => {
    switch (audience) {
      case 'employee':
        return 'Employee';
      case 'team_lead':
        return 'Team Lead';
      case 'project_manager':
        return 'Project Manager';
      case 'co_founders':
        return 'Co-founders';
      case 'employee_to_pm':
        return 'Employee to PM';
      case 'pm_to_employee':
        return 'PM to Employees';
      case 'all':
        return 'All';
      default:
        return audience;
    }
  };

  const getCompletionPercentage = () => {
    if (targetCount === 0) return 0;
    return Math.round((submissionCount / targetCount) * 100);
  };

  const viewResponse = (employee) => {
    if (employee.submission) {
      setSelectedSubmission({
        employee,
        submission: employee.submission
      });
      setIsResponseModalOpen(true);
    }
  };

  // Filter employees
  const filteredEmployees = employeeStatuses.filter(emp => {
    const matchesSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         emp.email.toLowerCase().includes(searchQuery.toLowerCase());

    let matchesStatus = true;
    if (statusFilter === 'submitted') {
      matchesStatus = emp.hasSubmitted;
    } else if (statusFilter === 'pending') {
      matchesStatus = !emp.hasSubmitted;
    }

    return matchesSearch && matchesStatus;
  });

  const submittedEmployees = employeeStatuses.filter(emp => emp.hasSubmitted);
  const pendingEmployees = employeeStatuses.filter(emp => !emp.hasSubmitted);

  return (
    <div className="space-y-6 fade-in">
      <div className="flex items-center justify-between">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/reports/forms')}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Form Reports
          </Button>
          <h1 className="text-2xl font-bold">{form.title}</h1>
          <p className="text-gray-500">Detailed submission report</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline">
            <FiDownload className="mr-2" />
            Export Responses
          </Button>
          <Link href={`/forms/${form.id}`}>
            <a>
              <Button variant="outline">
                <FiFileText className="mr-2" />
                View Form
              </Button>
            </a>
          </Link>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <Card>
          <Card.Content className="p-6">
            <div className="flex items-center">
              <div className="p-2 bg-blue-100 rounded-lg">
                <FiUsers className="h-6 w-6 text-blue-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">Target Audience</p>
                <p className="text-2xl font-bold text-gray-900">{targetCount}</p>
                <p className="text-xs text-gray-500">{getAudienceLabel(form.audience)}</p>
              </div>
            </div>
          </Card.Content>
        </Card>

        <Card>
          <Card.Content className="p-6">
            <div className="flex items-center">
              <div className="p-2 bg-green-100 rounded-lg">
                <FiCheck className="h-6 w-6 text-green-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">Submitted</p>
                <p className="text-2xl font-bold text-gray-900">{submissionCount}</p>
                <p className="text-xs text-gray-500">{submittedEmployees.length} employees</p>
              </div>
            </div>
          </Card.Content>
        </Card>

        <Card>
          <Card.Content className="p-6">
            <div className="flex items-center">
              <div className="p-2 bg-yellow-100 rounded-lg">
                <FiX className="h-6 w-6 text-yellow-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">Pending</p>
                <p className="text-2xl font-bold text-gray-900">{targetCount - submissionCount}</p>
                <p className="text-xs text-gray-500">{pendingEmployees.length} employees</p>
              </div>
            </div>
          </Card.Content>
        </Card>

        <Card>
          <Card.Content className="p-6">
            <div className="flex items-center">
              <div className="p-2 bg-purple-100 rounded-lg">
                <FiFileText className="h-6 w-6 text-purple-600" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-gray-500">Completion Rate</p>
                <p className="text-2xl font-bold text-gray-900">{getCompletionPercentage()}%</p>
                <div className="w-full bg-gray-200 rounded-full h-1.5 mt-2">
                  <div 
                    className="bg-purple-600 h-1.5 rounded-full" 
                    style={{ width: `${getCompletionPercentage()}%` }}
                  />
                </div>
              </div>
            </div>
          </Card.Content>
        </Card>
      </div>

      {/* Form Info */}
      <Card>
        <Card.Header>
          <Card.Title>Form Information</Card.Title>
        </Card.Header>
        <Card.Content>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <p className="text-sm text-gray-500">Created</p>
              <p className="font-medium">{new Date(form.created_at).toLocaleDateString()}</p>
            </div>
            <div>
              <p className="text-sm text-gray-500">Status</p>
              <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                form.status === 'published' ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'
              }`}>
                {form.status.charAt(0).toUpperCase() + form.status.slice(1)}
