          />
        </div>

        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
            <FiFilter />
          </div>
          <Select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="pl-10"
          >
            <option value="">All Status</option>
            <option value="submitted">Submitted</option>
            <option value="pending">Pending</option>
          </Select>
        </div>

        <Button 
          variant="outline" 
          onClick={() => {
            setSearchQuery('');
            setStatusFilter('');
          }}
        >
          Clear Filters
        </Button>
      </div>

      {/* Employee Status List */}
      <Card>
        <Card.Header>
          <Card.Title>Employee Submission Status</Card.Title>
          <Card.Description>
            Track which employees have submitted the form and view their responses
          </Card.Description>
        </Card.Header>
        <Card.Content>
          {filteredEmployees.length === 0 ? (
            <EmptyState 
              title="No employees found"
              description="No employees match your current filters"
              action={() => {
                setSearchQuery('');
                setStatusFilter('');
              }}
              actionText="Clear Filters"
            />
          ) : (
            <div className="space-y-4">
              {filteredEmployees.map((employee) => (
                <div key={employee.id} className="flex items-center justify-between p-4 border rounded-lg hover:bg-gray-50">
                  <div className="flex items-center">
                    <Avatar 
                      fallback={employee.name} 
                      size="md" 
                      className="mr-4"
                    />
                    <div>
                      <h4 className="font-medium">{employee.name}</h4>
                      <p className="text-sm text-gray-500">{employee.email}</p>
                      <p className="text-xs text-gray-400">{employee.designation}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-4">
                    {employee.hasSubmitted ? (
                      <>
                        <div className="text-right">
                          <div className="flex items-center text-green-600 mb-1">
                            <FiCheck className="mr-1 h-4 w-4" />
                            <span className="text-sm font-medium">Submitted</span>
                          </div>
                          <p className="text-xs text-gray-500">
                            {new Date(employee.submittedAt).toLocaleDateString()}
                          </p>
                        </div>
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => viewResponse(employee)}
                        >
                          <FiEye className="mr-1" />
                          View Response
                        </Button>
                      </>
                    ) : (
                      <div className="text-right">
                        <div className="flex items-center text-yellow-600 mb-1">
                          <FiX className="mr-1 h-4 w-4" />
                          <span className="text-sm font-medium">Pending</span>
                        </div>
                        <p className="text-xs text-gray-500">Not submitted</p>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card.Content>
      </Card>

      {/* Response Modal */}
      <Modal
        isOpen={isResponseModalOpen}
        onClose={() => setIsResponseModalOpen(false)}
        title={`Response from ${selectedSubmission?.employee?.name}`}
        size="3xl"
        footer={
          <Button onClick={() => setIsResponseModalOpen(false)}>
            Close
          </Button>
        }
      >
        {selectedSubmission && (
          <div className="space-y-6">
            <div className="bg-gray-50 p-4 rounded-lg">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-gray-500">Employee</p>
                  <p className="font-medium">{selectedSubmission.employee.name}</p>
                </div>
                <div>
                  <p className="text-gray-500">Submitted On</p>
                  <p className="font-medium">
                    {new Date(selectedSubmission.submission.submitted_at).toLocaleDateString()}
                  </p>
                </div>
                <div>
                  <p className="text-gray-500">Email</p>
                  <p className="font-medium">{selectedSubmission.employee.email}</p>
                </div>
                <div>
                  <p className="text-gray-500">Status</p>
                  <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                    {selectedSubmission.submission.status}
                  </span>
                </div>
              </div>
            </div>

            <div>
              <h4 className="font-medium mb-4">Form Responses</h4>
              <div className="bg-yellow-50 border border-yellow-200 rounded-md p-4">
                <p className="text-yellow-700 text-sm">
                  <FiFileText className="inline mr-2" />
                  Response details will be displayed here once the submission system is fully implemented.
                  For now, you can see that {selectedSubmission.employee.name} has submitted the form.
                </p>
              </div>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

