export default function ViewScoreReport({ reportId, user }) {
  const [report, setReport] = useState(null);
  const [form, setForm] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [categories, setCategories] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [employee, setEmployee] = useState(null);
  const [department, setDepartment] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isReviewing, setIsReviewing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [currentUser, setCurrentUser] = useState(user);
  const [isAdminUser, setIsAdminUser] = useState(false);
  const [canEdit, setCanEdit] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [accessDenied, setAccessDenied] = useState(false);

  const router = useRouter();
  const months = getMonthsArray();

  useEffect(() => {
    if (!currentUser) {
      setCurrentUser(getUser());
    }
    setIsAdminUser(isAdmin());

    if (reportId) {
      fetchReportData();
    }
  }, [reportId, currentUser]);

  const fetchReportData = async () => {
    try {
      setIsLoading(true);

      if (isSupabaseConfigured()) {
        // Fetch report data from Supabase
        const { data: reportData, error: reportError } = await supabase
          .from('form_submissions')
          .select('*')
          .eq('id', reportId)
          .single();

        if (reportError) throw reportError;

        // Check if user has permission to view this report
        if (!canViewReport(reportData.employee_id)) {
          setAccessDenied(true);
          setIsLoading(false);
          return;
        }

        // Fetch form data
        const { data: formData, error: formError } = await supabase
          .from('score_forms')
          .select('*')
          .eq('id', reportData.form_id)
          .single();

        if (formError) throw formError;

        // Fetch questions
        const { data: questionsData, error: questionsError } = await supabase
          .from('form_questions')
          .select('*, score_categories(*)')
          .eq('form_id', reportData.form_id)
          .order('order_number');

        if (questionsError) throw questionsError;

        // Fetch answers
        const { data: answersData, error: answersError } = await supabase
          .from('submission_answers')
          .select('*')
          .eq('submission_id', reportId);

        if (answersError) throw answersError;

        // Fetch categories
        const { data: categoriesData, error: categoriesError } = await supabase
          .from('score_categories')
          .select('*')
          .eq('form_id', reportData.form_id);

        if (categoriesError) throw categoriesError;

        setReport(reportData);
        setForm(formData);
        setQuestions(questionsData);
        setCategories(categoriesData);
        setAnswers(answersData);

        // Determine if current user can edit this report
        setCanEdit(isAdmin() || (isTeamLead() && reportData.status !== 'reviewed'));

        // Fetch employee data via API
        if (reportData.employee_id) {
          try {
            const empResponse = await fetch(`/api/employees/${reportData.employee_id}`);
            if (empResponse.ok) {
              const employeeData = await empResponse.json();
              setEmployee(employeeData);

              if (employeeData && employeeData.departmentId) {
                const deptResponse = await fetch(`/api/departments/${employeeData.departmentId}`);
                if (deptResponse.ok) {
                  const departmentData = await deptResponse.json();
                  setDepartment(departmentData);
                }
              }
            }
          } catch (error) {
            console.error('Error fetching employee/department data:', error);
          }
