      }
    } catch (error) {
      console.error('Error fetching report data:', error);
      toast.error('Failed to load report data');
    } finally {
      setIsLoading(false);
    }
  };

  const handleScoreChange = (answerId, field, value) => {
    setAnswers(prev => 
      prev.map(ans => 
        ans.id === answerId 
          ? { ...ans, [field]: field === 'score' ? parseInt(value) || 0 : value } 
          : ans
      )
    );
  };

  const handleSaveReview = async () => {
    setIsSubmitting(true);

    try {
      if (isSupabaseConfigured()) {
        // Update answers
        const answerUpdates = answers.map(answer => ({
          id: answer.id,
          score: answer.score,
          comments: answer.comments
        }));

        const { error: answersError } = await supabase
          .from('submission_answers')
          .upsert(answerUpdates);

        if (answersError) throw answersError;

        // Calculate total score
        const totalScore = answers.reduce((sum, ans) => {
          return sum + (ans.score || 0);
        }, 0);

        const maxPossibleScore = answers.reduce((sum, ans) => {
          return sum + (ans.max_score || 0);
        }, 0);

        // Update report status
        const { error: reportError } = await supabase
          .from('form_submissions')
          .update({
            status: 'reviewed',
            reviewed_at: new Date().toISOString(),
            reviewed_by: currentUser?.id,
            total_score: totalScore,
            max_possible_score: maxPossibleScore
          })
          .eq('id', reportId);

        if (reportError) throw reportError;
      }

      toast.success('Review saved successfully');
      setReport(prev => ({
        ...prev,
        status: 'reviewed',
        reviewed_at: new Date().toISOString(),
        reviewed_by: currentUser?.id,
        total_score: answers.reduce((sum, ans) => sum + (ans.score || 0), 0),
        max_possible_score: answers.reduce((sum, ans) => sum + (ans.max_score || 0), 0)
      }));
      setEditMode(false);
    } catch (error) {
      console.error('Error saving review:', error);
      toast.error('Failed to save review');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getCategoryScores = () => {
    const categoryScores = {};

    // Initialize categories
    categories.forEach(cat => {
      categoryScores[cat.id] = {
        name: cat.name,
        score: 0,
        maxScore: 0,
        weight: cat.weight || 1
      };
    });

    // Calculate scores per category
    answers.forEach(answer => {
      const question = questions.find(q => q.id === answer.question_id);
      if (question && question.category_id && answer.score) {
        categoryScores[question.category_id].score += answer.score;
        categoryScores[question.category_id].maxScore += answer.max_score;
      }
    });

    return Object.values(categoryScores);
  };

  const getScoreColorClass = (score, maxScore) => {
    if (!score || !maxScore) return 'text-gray-500';

    const percentage = (score / maxScore) * 100;

    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 60) return 'text-blue-600';
    if (percentage >= 40) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getScoreText = (score, maxScore) => {
    if (!score || !maxScore) return 'Not Rated';

    const percentage = (score / maxScore) * 100;

    if (percentage >= 90) return 'Outstanding';
    if (percentage >= 80) return 'Excellent';
    if (percentage >= 70) return 'Very Good';
    if (percentage >= 60) return 'Good';
    if (percentage >= 50) return 'Satisfactory';
    if (percentage >= 40) return 'Needs Improvement';
    return 'Unsatisfactory';
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (accessDenied) {
    return (
      <div className="text-center py-12">
        <h2 className="text-xl font-semibold mb-2">Access Denied</h2>
        <p className="text-gray-500 mb-6">You don&apos;t have permission to view this report.</p>
        <Link href="/reports">
          <a>
            <Button>Return to Reports</Button>
          </a>
        </Link>
      </div>
    );
  }

  if (!report || !form) {
    return (
      <div className="text-center py-12">
        <h2 className="text-xl font-semibold mb-2">Report not found</h2>
        <p className="text-gray-500 mb-6">The report you&apos;re looking for doesn&apos;t exist or has been removed.</p>
        <Link href="/reports">
          <a>
            <Button>Return to Reports</Button>
          </a>
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-6 fade-in pb-16">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/reports')}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Reports
          </Button>
          <h1 className="text-2xl font-bold">{form.title}</h1>
          <p className="text-gray-500">
            {months.find(m => m.value === report.submission_month)?.label} {report.submission_year} Assessment
          </p>
        </div>
        <div className="flex space-x-2">
          {canEdit && !editMode && (
            <Button
              variant="outline"
              className="flex items-center"
              onClick={() => setEditMode(true)}
            >
              <FiEdit className="mr-2" />
              Edit Review
            </Button>
          )}
          <Button
            variant="outline"
            className="flex items-center"
            onClick={() => toast.success('Report downloaded successfully')}
          >
            <FiDownload className="mr-2" />
            Download
          </Button>
        </div>
      </div>

      {/* Summary Card */}
      <Card>
        <div className="md:flex md:items-stretch">
          <div className="md:w-2/3 p-6">
            <div className="flex flex-col md:flex-row md:items-center mb-6">
              <div className="flex-shrink-0 mb-4 md:mb-0 md:mr-6">
                <Avatar 
                  fallback={employee?.name || report.user_email} 
                  size="xl" 
                />
              </div>
              <div>
                <h2 className="text-xl font-bold">
                  {employee?.name || 'Unknown Employee'}
                  {employee?.id === currentUser?.id ? ' (You)' : ''}
                </h2>
                <p className="text-gray-600">{employee?.designation || 'No Designation'}</p>
                <div className="flex items-center mt-1 text-gray-500 text-sm">
                  <FiUser className="mr-1" />
                  {report.user_email}
                </div>
                {department && (
                  <div className="mt-2">
                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                      {department.name}
                    </span>
                  </div>
                )}
              </div>
            </div>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-500">Submitted on</span>
                <span className="text-sm font-medium">
                  {new Date(report.submitted_at).toLocaleDateString()} 
                  {new Date(report.submitted_at).toLocaleTimeString()}
                </span>
              </div>
              {report.reviewed_at && (
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-500">Reviewed on</span>
                  <span className="text-sm font-medium">
                    {new Date(report.reviewed_at).toLocaleDateString()} 
                    {new Date(report.reviewed_at).toLocaleTimeString()}
                  </span>
                </div>
              )}
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-500">Status</span>
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                  report.status === 'reviewed' ? 'bg-green-100 text-green-800' : 
                  report.status === 'completed' ? 'bg-blue-100 text-blue-800' : 
                  'bg-yellow-100 text-yellow-800'
                }`}>
                  {report.status.charAt(0).toUpperCase() + report.status.slice(1)}
                </span>
              </div>
            </div>
          </div>
          <div className="bg-gray-50 md:w-1/3 p-6 flex flex-col justify-center border-t md:border-t-0 md:border-l border-gray-200">
            <div className="text-center">
              <h3 className="text-lg font-medium text-gray-900 mb-2">Overall Score</h3>
              {report.total_score ? (
                <>
                  <div className={`text-5xl font-bold mb-2 ${getScoreColorClass(report.total_score, report.max_possible_score)}`}>
                    {Math.round((report.total_score / report.max_possible_score) * 100)}%
                  </div>
                  <p className="text-lg font-medium mb-4">
                    {getScoreText(report.total_score, report.max_possible_score)}
                  </p>
                  <p className="text-sm text-gray-500">
                    {report.total_score} out of {report.max_possible_score} points
                  </p>
                </>
              ) : (
                <p className="text-lg text-gray-400">Not yet scored</p>
              )}
            </div>
          </div>
        </div>
      </Card>

      {/* Category Scores */}
      {report.total_score && categories.length > 0 && (
        <Card>
          <Card.Header>
            <Card.Title>Performance by Category</Card.Title>
          </Card.Header>
          <Card.Content>
            <div className="space-y-6">
              {getCategoryScores().map((category, index) => (
                <div key={index} className="space-y-2">
                  <div className="flex justify-between items-center">
                    <div>
                      <h3 className="font-medium">{category.name}</h3>
                      <p className="text-sm text-gray-500">Weight: {category.weight}x</p>
                    </div>
                    <div className={`text-xl font-bold ${getScoreColorClass(category.score, category.maxScore)}`}>
                      {category.maxScore > 0 ? Math.round((category.score / category.maxScore) * 100) : 0}%
                    </div>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2.5">
                    <div 
                      className="bg-primary-600 h-2.5 rounded-full" 
                      style={{ width: `${category.maxScore > 0 ? (category.score / category.maxScore) * 100 : 0}%` }}
                    ></div>
                  </div>
                </div>
              ))}
            </div>
          </Card.Content>
        </Card>
      )}

      {/* Responses and Scores */}
      <Card>
        <Card.Header>
          <Card.Title>Responses & Scores</Card.Title>
          {editMode ? (
            <Card.Description>Updating scores and feedback</Card.Description>
          ) : (
            <Card.Description>Detailed responses and evaluations</Card.Description>
          )}
        </Card.Header>
        <Card.Content>
          <div className="space-y-8">
            {questions.map((question, qIndex) => {
              const answer = answers.find(a => a.question_id === question.id);
              const category = question.score_categories;

              return (
                <div key={question.id} className={`pb-6 ${qIndex < questions.length - 1 ? 'border-b border-gray-200' : ''}`}>
                  <div className="mb-2 flex justify-between">
                    <div>
                      <h3 className="font-medium text-gray-900">{qIndex + 1}. {question.question_text}</h3>
                      {category && (
                        <span className="text-xs font-medium text-gray-500">
                          Category: {category.name}
                        </span>
                      )}
                    </div>
                    {answer?.score && !editMode && (
                      <div className={`text-lg font-bold ${getScoreColorClass(answer.score, answer.max_score)}`}>
                        {answer.score}/{answer.max_score}
                      </div>
                    )}
                  </div>

                  {/* Display the answer */}
                  <div className="bg-gray-50 p-3 rounded-md mb-4">
                    {question.question_type === 'long_text' ? (
                      <p className="text-gray-700 whitespace-pre-wrap">{answer?.answer_text || 'No response'}</p>
                    ) : question.question_type === 'multiple_choice' || question.question_type === 'checkbox' ? (
                      <p className="text-gray-700">{answer?.answer_text || 'No response'}</p>
                    ) : question.question_type === 'linear_scale' ? (
                      <div className="flex items-center">
                        <div className="w-full max-w-xs bg-gray-200 rounded-full h-2.5 mr-2">
                          <div 
                            className="bg-blue-600 h-2.5 rounded-full" 
                            style={{ width: `${answer?.answer_text ? (parseInt(answer.answer_text) / 5) * 100 : 0}%` }}
                          ></div>
                        </div>
                        <span className="text-gray-700 font-medium">{answer?.answer_text || '0'}/5</span>
                      </div>
                    ) : (
                      <p className="text-gray-700">{answer?.answer_text || 'No response'}</p>
                    )}
                  </div>

                  {/* Scoring section - visible to admins and team leads */}
                  {canEdit && question.max_score > 0 && (
                    <div className={`mt-4 ${editMode ? 'space-y-4' : ''}`}>
                      {editMode ? (
                        <>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                              <Label htmlFor={`score-${question.id}`}>Score (max: {answer?.max_score || question.max_score})</Label>
                              <Input
                                id={`score-${question.id}`}
                                type="number"
                                min="0"
                                max={answer?.max_score || question.max_score}
                                value={answer?.score || 0}
                                onChange={(e) => handleScoreChange(answer?.id, 'score', e.target.value)}
                                className="w-full"
                              />
                            </div>

                            <div className="space-y-2">
                              <Label htmlFor={`comments-${question.id}`}>Feedback/Comments</Label>
                              <Input
                                id={`comments-${question.id}`}
                                value={answer?.comments || ''}
                                onChange={(e) => handleScoreChange(answer?.id, 'comments', e.target.value)}
                                placeholder="Provide feedback on this response"
                                className="w-full"
                              />
                            </div>
                          </div>
                        </>
                      ) : answer?.score !== undefined && answer?.score !== null ? (
                        <div className="border-t border-gray-100 pt-4 mt-2">
                          <div className="flex justify-between items-start">
                            <div>
                              <h4 className="text-sm font-medium text-gray-500">Reviewer Feedback</h4>
                              <p className="text-gray-700 mt-1">{answer.comments || 'No comments provided'}</p>
                            </div>
                            <div className="bg-gray-100 px-3 py-2 rounded-md">
                              <div className="text-xs text-gray-500">Score</div>
                              <div className={`text-lg font-bold ${getScoreColorClass(answer.score, answer.max_score)}`}>
                                {answer.score}/{answer.max_score}
                              </div>
                            </div>
                          </div>
                        </div>
                      ) : null}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </Card.Content>

        {editMode && (
          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              variant="outline"
              onClick={() => setEditMode(false)}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              onClick={handleSaveReview}
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Saving...' : 'Save Review'}
            </Button>
          </Card.Footer>
        )}
      </Card>
    </div>
  );
}

