scripts/restore-data.js.code:
const { Pool } = require('pg');
const { mockDepartments, mockEmployees, mockDepartmentTeamLeads } = require('../lib/mockData');

// Create a new pool using environment variables
const pool = new Pool({
  user: process.env.DB_USER || 'postgres',
  host: process.env.DB_HOST || 'localhost',
  database: process.env.DB_NAME || 'your_database_name',
  password: process.env.DB_PASSWORD || 'your_password',
  port: process.env.DB_PORT || 5432,
});

async function restoreData() {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // Clear existing data
    await client.query('TRUNCATE departments, employees, department_team_leads CASCADE');

    // Insert departments
    for (const dept of mockDepartments) {
      await client.query(
        'INSERT INTO departments (id, name, created_at, updated_at) VALUES ($1, $2, $3, $4)',
        [dept.id, dept.name, dept.created_at, dept.updated_at]
      );
    }

    // Insert employees
    for (const emp of mockEmployees) {
      await client.query(
        'INSERT INTO employees (id, name, email, phone_number, designation, department_id, job_role, created_at, updated_at) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)',
        [emp.id, emp.name, emp.email, emp.phoneNumber, emp.designation, emp.departmentId, emp.jobRole, emp.created_at, emp.updated_at]
      );
    }

    // Insert department team leads
    for (const lead of mockDepartmentTeamLeads) {
      await client.query(
        'INSERT INTO department_team_leads (id, department_id, employee_id, created_at) VALUES ($1, $2, $3, $4)',
        [lead.id, lead.department_id, lead.employee_id, lead.created_at]
      );
    }

    await client.query('COMMIT');
    console.log('Data restored successfully!');
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error restoring data:', error);
    throw error;
  } finally {
    client.release();
  }
}

restoreData()
  .then(() => {
    console.log('Database restoration completed');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Database restoration failed:', error);
    process.exit(1);
  });

