const fs = require('fs');
const path = require('path');
const { query } = require('../lib/postgres');

async function runMigration() {
  try {
    console.log('Starting database schema migration...');

    // Read the schema file
    const schemaPath = path.join(__dirname, '..', 'lib', 'schema.sql');
    const schemaSql = fs.readFileSync(schemaPath, 'utf8');

    // Split into individual statements
    const statements = schemaSql
      .split(';')
      .map(stmt => stmt.trim())
      .filter(stmt => stmt.length > 0);

    console.log(`Found ${statements.length} SQL statements to execute...`);

    // Execute each statement
    for (let i = 0; i < statements.length; i++) {
      const statement = statements[i];
      if (statement.trim()) {
        try {
          console.log(`Executing statement ${i + 1}/${statements.length}...`);
          await query(statement);
        } catch (error) {
          // Ignore "already exists" errors
          if (error.message.includes('already exists') || 
              error.message.includes('relation') && error.message.includes('already exists')) {
            console.log(`  - Skipped (already exists): ${statement.substring(0, 50)}...`);
          } else {
            console.error(`  - Error in statement ${i + 1}:`, error.message);
            console.error(`  - Statement: ${statement.substring(0, 100)}...`);
            // Continue with next statement instead of failing
          }
        }
      }
    }

    console.log('✅ Database schema migration completed successfully!');

    // Test the connection
    const testResult = await query('SELECT COUNT(*) as table_count FROM information_schema.tables WHERE table_schema = \'public\'');
    console.log(`📊 Total tables in database: ${testResult.rows[0].table_count}`);

  } catch (error) {
    console.error('❌ Migration failed:', error);
    process.exit(1);
  } finally {
    process.exit(0);
  }
}

// Run the migration
runMigration();
